//! Component and modal routing for the button-panel UI.
//!
//! Every settings hub page and every public panel flows through here.
//! Handlers render panels from `ui::panels`, mutate the shared SQLite database
//! and answer with an updated ephemeral message.

use super::Error;
use crate::db;
use crate::permissions;
use crate::state::Data;
use crate::ui::theme::{colors, icons};
use crate::ui::{components, embeds, panels, theme};
use base64::Engine as _;
use poise::serenity_prelude as serenity;
use serenity::{
    ComponentInteraction, CreateActionRow, CreateEmbed, CreateInteractionResponse,
    CreateInteractionResponseMessage, EditInteractionResponse, ModalInteraction,
};
use sqlx;
use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};
use std::time::{Duration, Instant};

// ------------------------------------------------------------------ helpers

async fn send_modal(
    ctx: &serenity::Context,
    interaction: &ComponentInteraction,
    id: &str,
    title: &str,
    inputs: Vec<CreateActionRow>,
) -> anyhow::Result<()> {
    interaction
        .create_response(&ctx.http, modal(id, title, inputs))
        .await?;
    Ok(())
}

fn message(
    embed: CreateEmbed,
    components: Vec<CreateActionRow>,
    ephemeral: bool,
) -> CreateInteractionResponse {
    CreateInteractionResponse::Message(
        CreateInteractionResponseMessage::new()
            .embed(embed)
            .components(components)
            .ephemeral(ephemeral),
    )
}

fn update(embed: CreateEmbed, rows: Vec<CreateActionRow>) -> CreateInteractionResponse {
    CreateInteractionResponse::UpdateMessage(
        CreateInteractionResponseMessage::new()
            .embed(embed)
            .components(rows),
    )
}

fn modal(id: &str, title: &str, inputs: Vec<CreateActionRow>) -> CreateInteractionResponse {
    CreateInteractionResponse::Modal(serenity::CreateModal::new(id, title).components(inputs))
}

async fn reply(
    ctx: &serenity::Context,
    interaction: &ComponentInteraction,
    embed: CreateEmbed,
    rows: Vec<CreateActionRow>,
    ephemeral: bool,
) -> anyhow::Result<()> {
    interaction
        .create_response(&ctx.http, message(embed, rows, ephemeral))
        .await?;
    Ok(())
}

async fn update_panel(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    embed: CreateEmbed,
    rows: Vec<CreateActionRow>,
) -> anyhow::Result<()> {
    let post_tool = db::admin_toolkit::find_post(&data.db, interaction.message.id.get())
        .await
        .ok()
        .flatten()
        .map(|(_, tool)| tool);
    if let Some(tool) = post_tool {
        interaction
            .create_response(&ctx.http, message(embed, rows, true))
            .await?;
        if let Ok(response) = interaction.get_response(&ctx.http).await {
            crate::admintoolkit::track_ephemeral(response.id.get());
        }
        crate::admintoolkit::schedule_post_refresh(
            ctx.clone(),
            data.clone(),
            interaction.guild_id.map(|id| id.get()).unwrap_or(0),
            tool,
        );
        return Ok(());
    }
    interaction
        .create_response(&ctx.http, update(embed, rows))
        .await?;
    Ok(())
}

async fn update_panel_embeds(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    embeds: Vec<CreateEmbed>,
    rows: Vec<CreateActionRow>,
) -> anyhow::Result<()> {
    let is_post = db::admin_toolkit::find_post(&data.db, interaction.message.id.get())
        .await
        .ok()
        .flatten()
        .is_some();
    let response = if is_post {
        CreateInteractionResponse::Message(
            CreateInteractionResponseMessage::new()
                .embeds(embeds)
                .components(rows)
                .ephemeral(true),
        )
    } else {
        CreateInteractionResponse::UpdateMessage(
            CreateInteractionResponseMessage::new()
                .embeds(embeds)
                .components(rows),
        )
    };
    interaction.create_response(&ctx.http, response).await?;
    if is_post {
        if let Ok(response) = interaction.get_response(&ctx.http).await {
            crate::admintoolkit::track_ephemeral(response.id.get());
        }
    }
    Ok(())
}

fn char_field<F>(interaction: &ModalInteraction, id: &str, f: F) -> Option<String>
where
    F: FnOnce(&str) -> Option<String>,
{
    interaction
        .data
        .components
        .iter()
        .flat_map(|row| row.components.iter())
        .find_map(|component| match component {
            serenity::ActionRowComponent::InputText(input) if input.custom_id == id => {
                input.value.as_deref().map(str::to_string)
            }
            _ => None,
        })
        .and_then(|value| f(&value))
}

fn trimmed(interaction: &ModalInteraction, id: &str) -> Option<String> {
    char_field(interaction, id, |value| {
        let value = value.trim();
        (!value.is_empty()).then(|| value.to_string())
    })
}

fn guild_of(interaction: &ModalInteraction) -> Result<u64, Error> {
    interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("run this inside a server"))
}

fn opt_parse_channel(raw: &str) -> Result<Option<u64>, anyhow::Error> {
    let raw = raw.trim();
    if raw.eq_ignore_ascii_case("none") || raw.is_empty() {
        return Ok(None);
    }
    let id = raw
        .trim_end_matches('>')
        .trim_start_matches('<')
        .trim_start_matches('#')
        .parse::<u64>()
        .map_err(|_| anyhow::anyhow!("not a channel id or `none`"))?;
    Ok(Some(id))
}

fn parse_number_input(raw: &str) -> Option<i64> {
    let cleaned: String = raw
        .chars()
        .filter(|c| {
            c.is_ascii_digit() || *c == '.' || *c == 'K' || *c == 'M' || *c == 'k' || *c == 'm'
        })
        .collect();
    let value = crate::calculator::game_numbers::parse_game_amount(&cleaned);
    (value > 0 || raw.trim().chars().any(|c| c.is_ascii_digit())).then_some(value)
}

pub(crate) async fn defer_modal(
    ctx: &serenity::Context,
    interaction: &ModalInteraction,
) -> anyhow::Result<()> {
    interaction
        .create_response(
            &ctx.http,
            CreateInteractionResponse::Defer(
                CreateInteractionResponseMessage::new().ephemeral(true),
            ),
        )
        .await?;
    Ok(())
}

pub(crate) async fn finish_modal(
    ctx: &serenity::Context,
    interaction: &ModalInteraction,
    embed: CreateEmbed,
) -> anyhow::Result<()> {
    interaction
        .edit_response(&ctx.http, EditInteractionResponse::new().embed(embed))
        .await?;
    Ok(())
}

// ---------------------------------------------------------------------------
// Component router
// ---------------------------------------------------------------------------

pub async fn handle_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
) {
    let custom_id = interaction.data.custom_id.clone();
    if let Err(err) = route_component(ctx, data, interaction, &custom_id).await {
        tracing::warn!(error = %crate::error::display_anyhow(&err), id = %custom_id, "component failed");
        let embed = embeds::error(
            "That did not work",
            format!("`{}`", crate::error::public(&err)),
        );
        let _ = interaction
            .create_response(&ctx.http, message(embed, Vec::new(), true))
            .await;
    }
}

pub async fn route_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    custom_id: &str,
) -> anyhow::Result<()> {
    if crate::notifications::handle_quarantine_component(ctx, data, interaction).await? {
        return Ok(());
    }
    let (namespace, action) = custom_id
        .split_once(':')
        .ok_or_else(|| anyhow::anyhow!("unknown component `{custom_id}`"))?;

    match namespace {
        "settings" => settings_component(ctx, data, interaction, action).await,
        "ticket" => crate::tickets::handle_component(ctx, data, interaction, custom_id).await,
        "music" => music_component(ctx, data, interaction, action).await,
        "lookup" => lookup_component(ctx, data, interaction, action).await,
        "lvl" => leveling_public_component(ctx, data, interaction, action).await,
        "gift" => gift_component(ctx, data, interaction, action).await,
        "ballot" => {
            let kind = action.split(':').next().unwrap_or("");
            match kind {
                "addq" | "togglepublic" | "togglechange" | "removeq" | "setrole" | "post"
                | "discard" => ballot_draft_component(ctx, data, interaction, action).await,
                _ => ballot_component(ctx, data, interaction, action).await,
            }
        }
        "giveaway" => giveaway_component(ctx, data, interaction, action).await,
        "translate" | "translate_lang" => {
            translate_component(ctx, data, interaction, namespace, action).await
        }
        "translate_view" => translate_view_component(ctx, data, interaction, action).await,
        "atkset" => crate::admintoolkit::settings::handle(ctx, data, interaction, action).await,
        "atk" => toolkit_component(ctx, data, interaction, action).await,
        "player" => playerid_component(ctx, data, interaction, action).await,
        "bdaypanel" => birthday_public_component(ctx, interaction, action).await,
        "wreg" => {
            let (operation, raw_guild) = action.split_once(':').unwrap_or(("register", action));
            let mut parts = raw_guild.splitn(2, ':');
            let guild_id = parts.next().unwrap_or_default().parse::<u64>()?;
            if guild_id == 0 {
                return Err(anyhow::anyhow!("invalid registration guild"));
            }
            let user_id = interaction.user.id.get();
            match operation {
                "manage" => {
                    let players = db::players::for_user(&data.db, guild_id, user_id).await?;
                    let list = if players.is_empty() {
                        "No Player IDs are linked to your account in this server.".to_string()
                    } else {
                        players
                            .iter()
                            .map(|p| format!("• `{}` — {}", p.fid, p.label()))
                            .collect::<Vec<_>>()
                            .join("\n")
                    };
                    let buttons = vec![
                        components::primary(
                            format!("wreg:register:{guild_id}"),
                            "Register Player ID",
                        ),
                        components::danger(format!("wreg:remove:{guild_id}"), "Remove Player ID"),
                    ];
                    return reply(
                        ctx,
                        interaction,
                        embeds::brand("🪪 Your Player IDs").description(list),
                        vec![CreateActionRow::Buttons(buttons)],
                        true,
                    )
                    .await;
                }
                "remove" => {
                    let players = db::players::for_user(&data.db, guild_id, user_id).await?;
                    if players.is_empty() {
                        return reply(
                            ctx,
                            interaction,
                            embeds::warn(
                                "No linked IDs",
                                "You have no Player IDs registered in this server.",
                            ),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    let options = players
                        .iter()
                        .map(|p| {
                            serenity::CreateSelectMenuOption::new(
                                format!("{} · {}", p.fid, p.label())
                                    .chars()
                                    .take(100)
                                    .collect::<String>(),
                                p.fid.clone(),
                            )
                        })
                        .collect();
                    let menu = serenity::CreateSelectMenu::new(
                        format!("wreg:remove_select:{guild_id}"),
                        serenity::CreateSelectMenuKind::String { options },
                    )
                    .placeholder("Pick Player IDs to remove")
                    .min_values(1)
                    .max_values(25);
                    return reply(
                        ctx,
                        interaction,
                        embeds::info(
                            "Remove Player IDs",
                            "Select the IDs you added. Redemption history is kept.",
                        ),
                        vec![CreateActionRow::SelectMenu(menu)],
                        true,
                    )
                    .await;
                }
                "use" => {
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                &format!("wreggiftmodal:{guild_id}"),
                                "Redeem a gift code",
                                vec![CreateActionRow::InputText(components::short(
                                    "code",
                                    "Gift code to redeem",
                                ))],
                            ),
                        )
                        .await?;
                    return Ok(());
                }
                "history" => {
                    let rows: Vec<(String, String, String, i64)> = sqlx::query_as(
                        "SELECT r.fid, r.code, r.status, r.redeemed_at FROM redemptions r JOIN players p ON p.fid = r.fid WHERE p.user_id = ? AND p.home_guild_id = ? ORDER BY r.redeemed_at DESC LIMIT 20",
                    ).bind(user_id.to_string()).bind(guild_id.to_string()).fetch_all(&data.db.pool).await?;
                    let body = if rows.is_empty() {
                        "No gift-code redemption history was found for your Player IDs.".to_string()
                    } else {
                        rows.iter()
                            .map(|(fid, code, status, at)| {
                                format!("• `{code}` · `{status}` · ID `{fid}` · <t:{at}:R>")
                            })
                            .collect::<Vec<_>>()
                            .join("\n")
                    };
                    return reply(
                        ctx,
                        interaction,
                        embeds::brand("🎁 My Gift Code History").description(body),
                        Vec::new(),
                        true,
                    )
                    .await;
                }
                "nickname" => {
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                &format!("wregnickmodal:{guild_id}"),
                                "Set My In-Game Nickname",
                                vec![
                                    CreateActionRow::InputText(
                                        components::short("alliance", "Alliance Tag (3 letters)")
                                            .max_length(3),
                                    ),
                                    CreateActionRow::InputText(
                                        components::short("name", "Player Name").max_length(32),
                                    ),
                                    CreateActionRow::InputText(
                                        components::short("rank", "Rank (R1–R5)").max_length(2),
                                    ),
                                ],
                            ),
                        )
                        .await?;
                    return Ok(());
                }
                "remove_select" => {
                    let selected = match &interaction.data.kind {
                        serenity::ComponentInteractionDataKind::StringSelect { values } => {
                            values.clone()
                        }
                        _ => Vec::new(),
                    };
                    let owned = db::players::for_user(&data.db, guild_id, user_id)
                        .await?
                        .into_iter()
                        .map(|p| p.fid)
                        .collect::<std::collections::HashSet<_>>();
                    let valid = selected
                        .into_iter()
                        .filter(|fid| owned.contains(fid))
                        .take(5)
                        .collect::<Vec<_>>();
                    if valid.is_empty() {
                        return reply(
                            ctx,
                            interaction,
                            embeds::denied("one of your linked IDs"),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    let rows = valid
                        .iter()
                        .map(|fid| {
                            CreateActionRow::Buttons(vec![components::danger(
                                format!("wreg:rmgo:{guild_id}:{fid}"),
                                format!("Remove {fid}"),
                            )])
                        })
                        .collect();
                    return reply(ctx, interaction, embeds::warn("Confirm Player ID removal", "Each button below removes only the selected ID. Redemption history is preserved."), rows, true).await;
                }
                "rmgo" => {
                    let fid = parts.next().unwrap_or_default();
                    let owned = db::players::for_user(&data.db, guild_id, user_id)
                        .await?
                        .iter()
                        .any(|p| p.fid == fid);
                    if !owned {
                        return reply(
                            ctx,
                            interaction,
                            embeds::denied("one of your linked IDs"),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    db::players::remove(&data.db, fid).await?;
                    return reply(
                        ctx,
                        interaction,
                        embeds::ok(format!(
                            "`{fid}` was unlinked. Redemption history was kept."
                        )),
                        Vec::new(),
                        true,
                    )
                    .await;
                }
                "register" => {}
                _ => return Err(anyhow::anyhow!("unknown DM Player ID action")),
            }
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        &format!("wregmodal:{guild_id}"),
                        "Register my Play ID(s)",
                        vec![
                            CreateActionRow::InputText(
                                components::paragraph("fids", "Player ID(s) — comma-separated")
                                    .placeholder("e.g. 123456789, 987654321")
                                    .max_length(500),
                            ),
                            CreateActionRow::InputText(
                                components::short("state", "State (digits only, all IDs)")
                                    .placeholder("e.g. 3105")
                                    .max_length(6),
                            ),
                        ],
                    ),
                )
                .await?;
            Ok(())
        }
        "deploy" => deploy_component(ctx, data, interaction, action).await,
        // The calculator Toolkit post and hub use `<calc>:home` to open the
        // setup screen (JS `calculator/menu.showCalcHome`). Route those to the
        // calculator setup hub instead of the per-calculator session handlers,
        // which have no `home` action.
        "svscalc" | "buildingcalc" | "chiefgearcalc" | "charmcalc" | "petcalc"
        | "waracademycalc"
            if action == "home" =>
        {
            let guild_id = interaction
                .guild_id
                .map(|id| id.get())
                .ok_or_else(|| anyhow::anyhow!("calculators only work inside a server"))?;
            render_calculator(ctx, data, interaction, guild_id).await
        }
        "svs" => svs_component(ctx, data, interaction, action).await,
        "svscalc" => svscalc_component(ctx, data, interaction, action).await,
        "buildingcalc" => buildingcalc_component(ctx, data, interaction, action).await,
        "chiefgearcalc" => plan_component(ctx, data, interaction, action, 0).await,
        "charmcalc" => plan_component(ctx, data, interaction, action, 1).await,
        "petcalc" => pets_component(ctx, data, interaction, action).await,
        "waracademycalc" => war_academy_component(ctx, data, interaction, action).await,
        "role" => role_component(ctx, data, interaction, action).await,
        "roleassign" => roleassign_component(ctx, data, interaction, action).await,
        "perm" => perm_component(ctx, data, interaction, action).await,
        "ministry" => ministry_component(ctx, data, interaction, action).await,
        "tvc" => tempvoice_component(ctx, data, interaction, action).await,
        "owner" => crate::owner::owner_component(ctx, data, interaction, action).await,
        "branding" => branding_component(ctx, data, interaction, action).await,
        "giveawayrules" => giveawayrules_component(ctx, data, interaction, action).await,
        "help" => {
            if action == "home" {
                let (embed, rows) = panels::help_panel("");
                update_panel(ctx, data, interaction, embed, rows).await
            } else {
                help_component(ctx, interaction, action).await
            }
        }
        other => Err(anyhow::anyhow!("unknown component namespace `{other}`")),
    }
}

// ---------------------------------------------------------------- settings

async fn settings_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("settings only work inside a server"))?;

    let is_admin = permissions::component_is_admin(ctx, data, interaction).await;
    if !is_admin && !permissions::component_can_manage_guild(ctx, data, interaction, guild_id).await
    {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }

    // Per-server claim: first authorised user becomes Server Bot Admin when
    // the guild has none yet (mirrors the legacy claim flow).
    let _ =
        crate::db::subscriptions::claim_server_admin(&data.db, guild_id, interaction.user.id.get())
            .await;

    if let Some(action) = action.strip_prefix("lookup_api") {
        // Whiteout Stats API key management — owner-only, global to the bot.
        if data.cfg.owner_id != Some(interaction.user.id.get()) {
            return reply(
                ctx,
                interaction,
                embeds::denied("Bot Owner"),
                Vec::new(),
                true,
            )
            .await;
        }
        match action {
            "key" => {
                let current = db::wos_credentials::get(&data.db).await.unwrap_or_default();
                let inputs = vec![CreateActionRow::InputText(
                    components::paragraph("api_key", "Whiteout Stats API key")
                        .placeholder("wos_…  or  Authorization: Bearer wos_…")
                        .value(current.api_key.unwrap_or_default())
                        .max_length(500),
                )];
                interaction
                    .create_response(
                        &ctx.http,
                        modal("lookupmodal:apikey", "Whiteout Stats API key", inputs),
                    )
                    .await?;
                return Ok(());
            }
            "test" => {
                interaction
                    .create_response(
                        &ctx.http,
                        CreateInteractionResponse::Defer(
                            CreateInteractionResponseMessage::new().ephemeral(true),
                        ),
                    )
                    .await?;
                let (ok, message) = data.lookup.test_connection().await;
                if db::wos_credentials::is_configured(&data.db).await {
                    let _ = db::wos_credentials::record_test(&data.db, ok, &message).await;
                }
                let embed = if ok {
                    embeds::success("Test passed", message)
                } else {
                    embeds::warn("Test failed", message)
                };
                interaction
                    .edit_response(&ctx.http, EditInteractionResponse::new().embed(embed))
                    .await?;
                return Ok(());
            }
            "disconnect" => {
                interaction
                    .create_response(
                        &ctx.http,
                        CreateInteractionResponse::Defer(
                            CreateInteractionResponseMessage::new().ephemeral(true),
                        ),
                    )
                    .await?;
                db::wos_credentials::clear(&data.db).await?;
                data.lookup.set_api_key(None);
                interaction
                    .edit_response(
                        &ctx.http,
                        EditInteractionResponse::new()
                            .embed(embeds::ok("Whiteout Stats API key disconnected.")),
                    )
                    .await?;
                return Ok(());
            }
            _ => {}
        }
    }

    if action == "close" {
        return update_panel(
            ctx,
            data,
            interaction,
            embeds::ok("Settings closed. Use `/settings` to reopen."),
            Vec::new(),
        )
        .await;
    }

    // Main-menu navigation: Home / Back to Settings restore the main menu.
    if action == "home" || action == "back" {
        let message_id = interaction.message.id.get();
        let toolkit_panel = crate::db::admin_toolkit::find_post(&data.db, message_id)
            .await
            .ok()
            .flatten()
            .filter(|(post_guild, _)| *post_guild == guild_id)
            .map(|(_, tool)| tool)
            .or_else(|| {
                crate::admintoolkit::tool_of(message_id, interaction.user.id.get(), guild_id)
            });
        if let Some(tool) = toolkit_panel {
            // Rebuild the post's own payload — live panels (Leveling, Roles,
            // Forms, ...) must redraw their hub, not the generic action card.
            let (embed, rows) =
                crate::admintoolkit::forum::post_payload(ctx, data, guild_id, &tool).await;
            return update_panel(ctx, data, interaction, embed, rows).await;
        }
        let (mut embed, mut rows) =
            settings_home(ctx, data, guild_id, interaction.user.id.get()).await?;
        if !permissions::component_is_admin(ctx, data, interaction).await
            && !permissions::component_can_manage_guild(ctx, data, interaction, guild_id).await
        {
            rows.clear();
            embed = embed.footer(serenity::CreateEmbedFooter::new(format!(
                "{} • view only (Manage Server required to edit)",
                theme::footer()
            )));
        }
        return update_panel(ctx, data, interaction, embed, rows).await;
    }

    // 🛠️ Discord Tools submenu.
    if action == "discordtools" {
        let (embed, rows) = panels::discord_tools();
        return update_panel(ctx, data, interaction, embed, rows).await;
    }

    // Admin / Permissions menu — Bot Owner or Server Bot Admin only.
    if let Some(_) = action.strip_prefix("permissions:") {
        if !permissions::component_can_manage_permissions(data, interaction, guild_id).await {
            return reply(
                ctx,
                interaction,
                embeds::denied("Bot Owner or Server Bot Admin"),
                Vec::new(),
                true,
            )
            .await;
        }
        let (embed, rows) = admin_panel(ctx, data, guild_id).await?;
        return update_panel(ctx, data, interaction, embed, rows).await;
    }

    // Feature panels all live behind their own handlers (render + mutate).
    let raw_ns = action.split(':').next().unwrap_or("");
    // JavaScript menu action names mapped onto the Rust panel namespaces.
    let ns = match raw_ns {
        "playerid" => "players",
        "logs" => "logging",
        "levels" => "leveling",
        "giftcode" => "gift",
        "polls" => "voting",
        other => other,
    };
    // Sub-actions are everything after the first colon in `settings:<ns>:<sub>`.
    // Deriving this from the raw action keeps mapped aliases (whose canonical
    // name can be longer than the button id) from panicking on string slicing.
    let sub_action = || action.split_once(':').map(|(_, rest)| rest).unwrap_or("");

    // Owner feature toggles — a force-off panel renders a locked embed instead.
    if ns == "owner" {
        // Owner Panel: Bot Owner only, and only on the official bot server (or
        // via /settings in a DM with the bot — the DM hub already scopes to the
        // owner there).
        if !is_effective_owner(data, interaction.user.id.get()).await {
            return reply(
                ctx,
                interaction,
                embeds::denied("Bot Owner"),
                Vec::new(),
                true,
            )
            .await;
        }
        if !db::subscriptions::is_official_guild(&data.db, guild_id).await {
            return reply(
                ctx,
                interaction,
                embeds::warn(
                    "Owner Panel",
                    "The Owner Panel is only available on the **official bot server**, or via `/settings` in a **DM** with the bot.",
                ),
                Vec::new(),
                true,
            )
            .await;
        }
        return crate::owner::owner_component(ctx, data, interaction, "hub").await;
    }
    let gate_keys: &[&str] = match ns {
        "leveling" => &["leveling"],
        "welcome" => &["welcome"],
        "logging" => &["logging"],
        "tempvoice" => &["tempvoice"],
        "voting" | "voting_create" => &["polls"],
        "birthday" => &["birthday"],
        "tickets" => &["tickets"],
        "giveaways" => &["giveaways"],
        "messages" => &["messages_guides"],
        "sneakpeek" => &["sneak_peek"],
        "wos" => &["wos_announcements"],
        "index" => &["server_index"],
        "roles" => &["autorole"],
        "notifications" => &["custom_notifications"],
        "calculator" => &["building_calculator", "all_calculators"],
        "ministry" => &["ministry"],
        "music" => &["music"],
        "gift" | "lookup" => &["gift_redemption"],
        _ => &[],
    };
    if settings_flag_locked(ctx, data, interaction, guild_id, gate_keys).await? {
        return Ok(());
    }

    match ns {
        "voting_create" => {
            return ballot_create_start(ctx, data, interaction, guild_id).await;
        }
        "leveling" => return leveling_component(ctx, data, interaction, sub_action()).await,
        "welcome" => return welcome_component(ctx, data, interaction, sub_action()).await,
        "logging" | "tempvoice" | "voting" | "birthday" | "tickets" | "giveaways" | "messages"
        | "cleanup" | "sneakpeek" | "wos" | "index" | "roles" | "notifications" | "calculator"
        | "admin" | "ministry" | "branding" => {
            return settings_feature_component(ctx, data, interaction, action, ns).await;
        }
        _ => {}
    }

    let (embed, rows) =
        settings_section(ctx, data, guild_id, ns, interaction.user.id.get()).await?;

    update_panel(ctx, data, interaction, embed, rows).await?;

    Ok(())
}

pub(crate) async fn settings_home(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    owner_id: u64,
) -> anyhow::Result<(CreateEmbed, Vec<CreateActionRow>)> {
    let guild_name = ctx
        .cache
        .guild(serenity::GuildId::new(guild_id))
        .map(|guild| guild.name.clone())
        .unwrap_or_else(|| "this server".to_string());
    let players = db::players::stats(&data.db, guild_id).await?;
    let music = db::music::get(&data.db, guild_id).await?;
    let lookup = db::lookup::get(&data.db, guild_id).await?;
    let oracle = db::oracle::state(&data.db).await.unwrap_or_default();

    let view = panels::SettingsContext {
        guild_name,
        player_ids: players.tracked,
        player_limit: db::subscriptions::player_id_limit(&data.db, guild_id)
            .await
            .ok()
            .flatten(),
        music_configured: music
            .as_ref()
            .is_some_and(|row| row.channel_id.is_some() && row.panel_message_id.is_some()),
        lookup_configured: lookup.channel_id.is_some(),
        gift_sync: oracle.last_codes_sync,
        oracle_ready: data.oracle.is_configured().await,
        uptime: data.uptime(),
        latency_ms: 0,
        is_owner: data.cfg.owner_id == Some(owner_id),
        official_guild: db::subscriptions::is_official_guild(&data.db, guild_id).await,
    };
    Ok(panels::settings_hub(&view))
}

async fn settings_section(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    section: &str,
    user_id: u64,
) -> anyhow::Result<(CreateEmbed, Vec<CreateActionRow>)> {
    let back = components::secondary("settings:home", format!("{} Back", icons::BACK));
    let footer = serenity::CreateEmbedFooter::new(theme::footer());

    let (mut embed, buttons) = match section {
        "players" => {
            let stats = db::players::stats(&data.db, guild_id).await?;
            let recent = db::players::page_for_guild(&data.db, guild_id, 5, 0).await?;
            let list = if recent.is_empty() {
                "_No players tracked yet._".to_string()
            } else {
                recent
                    .iter()
                    .map(|row| {
                        format!(
                            "`{}` **{}**{} · `{}`",
                            row.fid,
                            crate::error::truncate(row.label(), 24),
                            row.alliance_abbr
                                .as_deref()
                                .map(|abbr| format!(" [{abbr}]"))
                                .unwrap_or_default(),
                            row.power
                                .map(theme::compact_number)
                                .unwrap_or_else(|| "—".into())
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
            };
            let embed = embeds::brand(format!("{} Players", icons::PLAYER))
                .color(colors::INFO)
                .description("Track WoS player IDs and keep their Oracle profile fresh.")
                .field(
                    "Database",
                    embeds::rows(&[
                        ("Tracked".into(), format!("`{}`", stats.tracked)),
                        ("Enriched".into(), format!("`{}`", stats.enriched)),
                        ("Alliances".into(), format!("`{}`", stats.alliances)),
                        (
                            "Total power".into(),
                            format!("`{}`", theme::compact_number(stats.total_power)),
                        ),
                    ]),
                    true,
                )
                .field("Recently added", list, false)
                .footer(footer.clone());
            (embed, vec![back])
        }
        "music" => {
            let row = db::music::get(&data.db, guild_id).await?;
            let embed = embeds::brand(format!("{} Music", icons::MUSIC))
                .color(colors::BRAND_DEEP)
                .description("Use **Deploy panel here** to post the control panel, then tap the buttons on it.")
                .field(
                    "Configuration",
                    embeds::rows(&[
                        (
                            "Panel channel".into(),
                            row.as_ref()
                                .and_then(|row| row.channel_id())
                                .map(|id| format!("<#{id}>"))
                                .unwrap_or_else(|| "`not deployed`".into()),
                        ),
                        (
                            "Panel message".into(),
                            row.as_ref()
                                .and_then(|row| row.panel_message_id())
                                .map(|id| format!("`{id}`"))
                                .unwrap_or_else(|| "`missing`".into()),
                        ),
                        (
                            "Volume".into(),
                            format!("`{}%`", row.as_ref().map(|row| row.volume()).unwrap_or(80)),
                        ),
                        (
                            "Loop".into(),
                            format!(
                                "`{}`",
                                row.as_ref().map(|row| row.loop_mode().label()).unwrap_or("Off")
                            ),
                        ),
                    ]),
                    false,
                )
                .field(
                    "Lavalink",
                    if data.cfg.music_enabled() {
                        format!(
                            "`{}`",
                            data.music.describe_host().unwrap_or_else(|| "configured".into())
                        )
                    } else {
                        "`not configured` — set `LAVALINK_HOST` and `LAVALINK_PASSWORD`".into()
                    },
                    false,
                )
                .footer(footer.clone());
            (
                embed,
                vec![
                    components::primary(
                        "deploy:music",
                        format!("{} Deploy panel here", icons::ADD),
                    ),
                    components::secondary("settings:music", format!("{} Refresh", icons::REFRESH)),
                    back,
                ],
            )
        }
        "lookup" => {
            let row = db::lookup::get(&data.db, guild_id).await?;
            let creds = db::wos_credentials::get(&data.db).await.unwrap_or_default();
            let masked = creds.api_key.as_deref().map(|key| {
                if key.len() > 10 {
                    format!("`{}…{}`", &key[..6], &key[key.len() - 4..])
                } else {
                    "`••••••`".to_string()
                }
            });
            let test_line = match (creds.last_test_ok, creds.last_test_at) {
                (Some(true), _) => "🟢 last test passed".to_string(),
                (Some(false), _) => format!(
                    "🔴 last test failed{}",
                    creds
                        .last_test_message
                        .as_deref()
                        .map(|message| format!(" — `{}`", crate::error::truncate(message, 80)))
                        .unwrap_or_default()
                ),
                _ => "⚪ not tested yet".to_string(),
            };
            let key_block = match &masked {
                Some(masked) => format!("API key: {masked}\n{test_line}"),
                None => "API key: `none` — public site only\n_Optional: connect a key for the official API._".to_string(),
            };
            let embed = embeds::brand(format!("{} Lookup", icons::LOOKUP))
                .color(colors::TEAL)
                .description(
                    "Player, alliance and state lookups powered by Whiteout Stats and Oracle data.",
                )
                .field(
                    "Public panel",
                    embeds::rows(&[
                        (
                            "Channel".into(),
                            row.channel()
                                .map(|id| format!("<#{id}>"))
                                .unwrap_or_else(|| "`not deployed`".into()),
                        ),
                        (
                            "Player message".into(),
                            row.player_panel()
                                .map(|id| format!("`{id}`"))
                                .unwrap_or_else(|| "`missing`".into()),
                        ),
                    ]),
                    false,
                )
                .field(
                    "Source",
                    format!("`{}`\n{key_block}", data.cfg.wos_site),
                    false,
                )
                .footer(footer.clone());

            let mut buttons = vec![
                components::primary("deploy:lookup", format!("{} Deploy panel here", icons::ADD)),
                components::secondary("settings:lookup", format!("{} Refresh", icons::REFRESH)),
            ];
            // Owner-only: Whiteout Stats API key management (global to the bot).
            if data.cfg.owner_id == Some(user_id) {
                buttons.push(components::success(
                    "settings:lookup_apikey",
                    if creds.api_key.is_some() {
                        "🔑 Update API key"
                    } else {
                        "🔑 Connect API key"
                    },
                ));
                buttons.push(components::secondary("settings:lookup_apitest", "🧪 Test"));
                if creds.api_key.is_some() {
                    buttons.push(components::danger(
                        "settings:lookup_apidisconnect",
                        "🔌 Disconnect",
                    ));
                }
            }
            buttons.push(back);
            (embed, buttons)
        }
        "gift" => {
            let stats = db::giftcodes::stats(&data.db).await?;
            let oracle = db::oracle::state(&data.db).await.unwrap_or_default();
            let channel = db::settings::get_u64(
                &data.db,
                guild_id,
                db::settings::keys::GIFT_ANNOUNCE_CHANNEL,
            )
            .await?;
            let embed = embeds::brand(format!("{} Gift codes", icons::GIFT))
                .color(colors::GOLD)
                .description("Sync codes from Oracle and announce new ones automatically.")
                .field(
                    "Codes",
                    embeds::rows(&[
                        ("Total".into(), format!("`{}`", stats.total)),
                        ("Active".into(), format!("`{}`", stats.active)),
                        ("VIP".into(), format!("`{}`", stats.vip)),
                        ("Last 24h".into(), format!("`{}`", stats.today)),
                    ]),
                    true,
                )
                .field(
                    "Sync",
                    embeds::rows(&[
                        (
                            "Announce channel".into(),
                            channel
                                .map(|id| format!("<#{id}>"))
                                .unwrap_or_else(|| "`not set` — tap **Announce channel**".into()),
                        ),
                        (
                            "Last sync".into(),
                            oracle
                                .last_codes_sync
                                .map(embeds::db_relative)
                                .unwrap_or_else(|| "`never`".into()),
                        ),
                    ]),
                    true,
                )
                .footer(footer.clone());
            (
                embed,
                vec![
                    components::primary(
                        "deploy:gift_channel",
                        format!("{} Announce channel", icons::EDIT),
                    ),
                    components::secondary("gift:sync", format!("{} Sync now", icons::REFRESH)),
                    back,
                ],
            )
        }
        "admin" => return admin_panel(ctx, data, guild_id).await,
        other => {
            let embed = embeds::warn("Unknown settings page", format!("`{other}`"));
            (embed, vec![back])
        }
    };

    embed = embed.footer(footer);
    Ok((embed, components::rows(buttons)))
}

// ------------------------------------------------------------- leveling

pub(crate) async fn leveling_view_for(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    user_id: u64,
) -> anyhow::Result<panels::LevelingView> {
    let settings = db::leveling::settings(&data.db, guild_id).await?;
    let xp = db::leveling::get_user(&data.db, guild_id, user_id)
        .await
        .map(|row| row.xp)
        .unwrap_or(0);
    let ranked = db::leveling::count_ranked(&data.db, guild_id)
        .await
        .unwrap_or(0);
    let cleanup = db::welcome::leveling_cleanup_settings(&data.db, guild_id).await?;
    let reward_count = db::leveling::list_rewards(&data.db, guild_id)
        .await
        .map(|rewards| rewards.len())
        .unwrap_or(0);
    let bot_can_manage_roles = ctx
        .cache
        .guild(serenity::GuildId::new(guild_id))
        .and_then(|guild| {
            guild
                .members
                .get(&ctx.cache.current_user().id)
                .map(|member| guild.member_permissions(member))
        })
        .is_some_and(|permissions| permissions.contains(serenity::Permissions::MANAGE_ROLES));
    let panel_deployed = db::settings::get_u64(
        &data.db,
        guild_id,
        db::settings::keys::LEVELING_PANEL_MESSAGE,
    )
    .await
    .unwrap_or(None)
    .is_some();

    Ok(panels::LevelingView {
        enabled: settings.enabled(),
        xp_min: settings.xp_min,
        xp_max: settings.xp_max,
        cooldown_sec: settings.cooldown_sec,
        voice_xp: settings.voice_xp,
        announce_mode: settings.announce_mode.clone(),
        stack_rewards: settings.stack_rewards(),
        reward_count,
        level: crate::leveling::level_of(xp),
        total_ranked: ranked,
        cleanup_enabled: cleanup.enabled(),
        cleanup_delay_minutes: cleanup.delay_minutes(),
        bot_can_manage_roles,
        announce_channel: settings.announce_channel(),
        ignored_channel_ids: settings.ignored_channels(),
        panel_deployed,
        notice: None,
    })
}

/// Shared hub payload builder, also used by the live Toolkit post and by
/// modals that return to the hub after saving.
pub(crate) async fn leveling_payload(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    user_id: u64,
    notice: Option<String>,
) -> anyhow::Result<(CreateEmbed, Vec<CreateActionRow>)> {
    let mut view = leveling_view_for(ctx, data, guild_id, user_id).await?;
    view.notice = notice;
    Ok(panels::leveling_panel(&view))
}

async fn render_leveling(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    render_leveling_notice(ctx, data, interaction, guild_id, None).await
}

async fn render_leveling_notice(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    notice: Option<String>,
) -> anyhow::Result<()> {
    let (embed, rows) =
        leveling_payload(ctx, data, guild_id, interaction.user.id.get(), notice).await?;
    update_panel(ctx, data, interaction, embed, rows).await
}

// ---------------------------------------------- public rank / leaderboard

const LEVELING_PAGE_SIZE: i64 = 10;

fn format_xp(n: i64) -> String {
    let digits = n.to_string();
    let mut out = String::with_capacity(digits.len() + digits.len() / 3);
    for (index, ch) in digits.chars().enumerate() {
        if index > 0 && (digits.len() - index) % 3 == 0 {
            out.push(',');
        }
        out.push(ch);
    }
    out
}

fn level_progress_bar(fraction: f64) -> String {
    let filled = (fraction.clamp(0.0, 1.0) * 14.0).round() as usize;
    format!("{}{}", "█".repeat(filled), "░".repeat(14 - filled))
}

/// `(display name, avatar url, is bot)` from cache, guild display name first.
fn leveling_member(
    ctx: &serenity::Context,
    guild_id: u64,
    user_id: u64,
) -> (String, Option<String>, bool) {
    let guild = ctx.cache.guild(serenity::GuildId::new(guild_id));
    let member = guild
        .as_ref()
        .and_then(|guild| guild.members.get(&serenity::UserId::new(user_id)));
    let cached = ctx.cache.user(user_id);
    let name = member
        .map(|member| member.display_name().to_string())
        .or_else(|| cached.as_ref().map(|user| user.name.clone()))
        .unwrap_or_else(|| format!("User {user_id}"));
    let icon = member
        .and_then(|member| member.avatar_url())
        .or_else(|| cached.as_ref().and_then(|user| user.avatar_url()));
    let bot = cached.as_ref().is_some_and(|user| user.bot);
    (name, icon, bot)
}

async fn leveling_rank_embed(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    user_id: u64,
) -> anyhow::Result<CreateEmbed> {
    let (name, icon, bot) = leveling_member(ctx, guild_id, user_id);
    if bot {
        return Ok(embeds::warn("Rank", "Bots don't earn XP."));
    }
    let row = db::leveling::get_user(&data.db, guild_id, user_id).await?;
    let (level, current, needed) = crate::leveling::progress(row.xp);
    let rank = if row.xp > 0 {
        format!(
            "#{}",
            db::leveling::get_rank(&data.db, guild_id, row.xp).await?
        )
    } else {
        "unranked".to_string()
    };
    let next = db::leveling::list_rewards(&data.db, guild_id)
        .await?
        .into_iter()
        .find(|reward| reward.level > level);

    let mut embed = CreateEmbed::new()
        .color(colors::INFO)
        .author(serenity::CreateEmbedAuthor::new(name).icon_url(icon.unwrap_or_default()))
        .field("Level", level.to_string(), true)
        .field("Rank", rank, true)
        .field("Total XP", format_xp(row.xp), true)
        .field(
            format!("Progress to level {}", level + 1),
            format!(
                "{}  {} / {} XP",
                level_progress_bar(if needed > 0 {
                    current as f64 / needed as f64
                } else {
                    0.0
                }),
                format_xp(current),
                format_xp(needed)
            ),
            false,
        );
    if let Some(reward) = next {
        embed = embed.field(
            "Next reward",
            format!("<@&{}> at level {}", reward.role_id, reward.level),
            false,
        );
    }
    Ok(embed.footer(serenity::CreateEmbedFooter::new(theme::footer())))
}

async fn leveling_leaderboard_payload(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    page: i64,
) -> anyhow::Result<(CreateEmbed, Vec<CreateActionRow>)> {
    let total = db::leveling::count_ranked(&data.db, guild_id).await?;
    let pages = (total / LEVELING_PAGE_SIZE + i64::from(total % LEVELING_PAGE_SIZE > 0)).max(1);
    let page = page.clamp(0, pages - 1);
    let rows = db::leveling::top(
        &data.db,
        guild_id,
        LEVELING_PAGE_SIZE,
        page * LEVELING_PAGE_SIZE,
    )
    .await?;
    let medals = ["🥇", "🥈", "🥉"];
    let lines: Vec<String> = rows
        .iter()
        .enumerate()
        .map(|(index, (user_id, xp))| {
            let position = page * LEVELING_PAGE_SIZE + index as i64;
            let place = medals
                .get(position as usize)
                .map(|medal| medal.to_string())
                .unwrap_or_else(|| format!("**{}.**", position + 1));
            format!(
                "{} <@{}> — Level **{}** • {} XP",
                place,
                user_id,
                crate::leveling::level_of(*xp),
                format_xp(*xp)
            )
        })
        .collect();
    let guild_name = ctx
        .cache
        .guild(serenity::GuildId::new(guild_id))
        .map(|guild| guild.name.clone())
        .unwrap_or_else(|| "this server".to_string());
    let embed = CreateEmbed::new()
        .color(colors::INFO)
        .title(format!("🏆 {guild_name} Leaderboard"))
        .description(if lines.is_empty() {
            "Nobody has earned XP yet — start chatting!".to_string()
        } else {
            lines.join("\n")
        })
        .footer(serenity::CreateEmbedFooter::new(format!(
            "Page {} of {}",
            page + 1,
            pages
        )));
    let buttons = vec![components::row(vec![
        components::secondary(format!("lvl:lb:{}", page - 1), "◀ Prev").disabled(page == 0),
        components::secondary(format!("lvl:lb:{}", page + 1), "Next ▶").disabled(page >= pages - 1),
    ])];
    Ok((embed, buttons))
}

async fn leveling_public_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("rank and leaderboard are server-only"))?;
    let settings = db::leveling::settings(&data.db, guild_id).await?;
    if !settings.enabled() {
        return reply_public(
            ctx,
            interaction,
            embeds::warn(
                "Leveling is off",
                "The levelling system is turned off on this server.",
            ),
            Vec::new(),
            true,
        )
        .await;
    }

    if action == "rank" || action == "rank_select" {
        let user_id = if action == "rank_select" {
            match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::UserSelect { values } => {
                    values.first().map(|id| id.get())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("pick a member"))?
        } else {
            interaction.user.id.get()
        };
        let embed = leveling_rank_embed(ctx, data, guild_id, user_id).await?;
        return reply_public(ctx, interaction, embed, Vec::new(), true).await;
    }

    if let Some(raw_page) = action.strip_prefix("lb:") {
        let page = raw_page.parse::<i64>().unwrap_or(0);
        let (embed, rows) = leveling_leaderboard_payload(ctx, data, guild_id, page).await?;
        let panel_message = db::settings::get_u64(
            &data.db,
            guild_id,
            db::settings::keys::LEVELING_PANEL_MESSAGE,
        )
        .await
        .unwrap_or(None);
        if panel_message == Some(interaction.message.id.get()) {
            // First click came from the shared public panel — open a private
            // leaderboard so other members' views are never overwritten.
            return reply_public(ctx, interaction, embed, rows, true).await;
        }
        // Later clicks come from that private response; page it in place.
        interaction
            .create_response(
                &ctx.http,
                serenity::CreateInteractionResponse::UpdateMessage(
                    serenity::CreateInteractionResponseMessage::new()
                        .embed(embed)
                        .components(rows)
                        .allowed_mentions(serenity::CreateAllowedMentions::new()),
                ),
            )
            .await?;
        return Ok(());
    }

    Err(anyhow::anyhow!("unknown rank action `{action}`"))
}

async fn reply_public(
    ctx: &serenity::Context,
    interaction: &ComponentInteraction,
    embed: CreateEmbed,
    rows: Vec<CreateActionRow>,
    ephemeral: bool,
) -> anyhow::Result<()> {
    interaction
        .create_response(
            &ctx.http,
            serenity::CreateInteractionResponse::Message(
                serenity::CreateInteractionResponseMessage::new()
                    .embed(embed)
                    .components(rows)
                    .ephemeral(ephemeral)
                    .allowed_mentions(serenity::CreateAllowedMentions::new()),
            ),
        )
        .await?;
    Ok(())
}

async fn leveling_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        let embed = embeds::denied("Manage Server");
        if let Err(err) = reply(ctx, interaction, embed.clone(), Vec::new(), true).await {
            tracing::debug!(%err, "leveling denial reply failed; editing response");
            let _ = interaction
                .edit_response(&ctx.http, EditInteractionResponse::new().embed(embed))
                .await;
        }
        return Ok(());
    }
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("leveling settings only work inside a server"))?;

    if action.is_empty() || action == "refresh" {
        return render_leveling(ctx, data, interaction, guild_id).await;
    }

    // Toolkit shortcuts: the JavaScript panel opens the hub with a hint rather
    // than jumping straight into a sub-screen.
    if action == "hint_rewards" {
        return render_leveling_notice(
            ctx,
            data,
            interaction,
            guild_id,
            Some("Open **Level Rewards** from this menu.".to_string()),
        )
        .await;
    }
    if action == "hint_announce" {
        return render_leveling_notice(
            ctx,
            data,
            interaction,
            guild_id,
            Some("Open **Announcements** from this menu.".to_string()),
        )
        .await;
    }
    // Toolkit "Reset XP" is already confirmed by the Toolkit prompt, which
    // acknowledges the interaction with "⏳ Working…", so answer in place.
    if action == "reset_all_confirmed" {
        let removed = db::leveling::reset_guild(&data.db, guild_id).await?;
        tracing::info!(guild_id, removed, "leveling XP reset for guild");
        crate::admintoolkit::schedule_post_refresh(
            ctx.clone(),
            data.clone(),
            guild_id,
            "leveling".to_string(),
        );
        interaction
            .edit_response(
                &ctx.http,
                EditInteractionResponse::new()
                    .content("✅ All leveling XP for this server was reset."),
            )
            .await?;
        return Ok(());
    }

    let sub = action.trim_start_matches(':');
    match sub {
        "cleanup" => {
            let settings = db::welcome::leveling_cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::leveling_cleanup_panel(&settings);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "deploy_panel" => deploy_component(ctx, data, interaction, "leveling").await,
        "cleanup_back" => render_leveling(ctx, data, interaction, guild_id).await,
        "cleanup_toggle" => {
            let current = db::welcome::leveling_cleanup_settings(&data.db, guild_id).await?;
            db::welcome::set_leveling_cleanup_settings(
                &data.db,
                guild_id,
                !current.enabled(),
                current.delay_minutes(),
            )
            .await?;
            let updated = db::welcome::leveling_cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::leveling_cleanup_panel(&updated);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "cleanup_delay" => {
            let minutes = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().and_then(|value| value.parse::<i64>().ok())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a cleanup delay"))?;
            if ![30, 60, 360, 720, 1440, 4320, 10080].contains(&minutes) {
                anyhow::bail!("unsupported cleanup delay");
            }
            db::welcome::set_leveling_cleanup_settings(&data.db, guild_id, true, minutes).await?;
            let updated = db::welcome::leveling_cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::leveling_cleanup_panel(&updated);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "cleanup_custom" => {
            let current = db::welcome::leveling_cleanup_settings(&data.db, guild_id).await?;
            let inputs = vec![CreateActionRow::InputText(
                components::short("minutes", "Delete after minutes (1–43200)")
                    .value(current.delay_minutes().to_string())
                    .max_length(6),
            )];
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "settings:leveling_cleanup_modal",
                        "Custom Cleanup Delay",
                        inputs,
                    ),
                )
                .await?;
            Ok(())
        }
        "toggle" => {
            let enabled = db::leveling::settings(&data.db, guild_id).await?.enabled();
            db::leveling::set_enabled(&data.db, guild_id, !enabled).await?;
            render_leveling(ctx, data, interaction, guild_id).await
        }
        "xp" => {
            let settings = db::leveling::settings(&data.db, guild_id).await?;
            let inputs = vec![
                CreateActionRow::InputText(
                    components::short("min", "Min XP per message")
                        .value(settings.xp_min.to_string())
                        .max_length(4),
                ),
                CreateActionRow::InputText(
                    components::short("max", "Max XP per message")
                        .value(settings.xp_max.to_string())
                        .max_length(4),
                ),
                CreateActionRow::InputText(
                    components::short("cooldown", "Cooldown between XP gains (seconds)")
                        .value(settings.cooldown_sec.to_string())
                        .max_length(4),
                ),
                CreateActionRow::InputText(
                    components::short("voice", "Voice XP per minute (0 = off)")
                        .value(settings.voice_xp.to_string())
                        .max_length(3),
                ),
            ];
            interaction
                .create_response(
                    &ctx.http,
                    modal("settings:leveling_xp_modal", "XP Settings", inputs),
                )
                .await?;
            Ok(())
        }
        "announce" => {
            let settings = db::leveling::settings(&data.db, guild_id).await?;
            let next = match settings.announce_mode.as_str() {
                "same" => "channel",
                "channel" => "off",
                _ => "same",
            };
            db::leveling::set_announce_mode(&data.db, guild_id, next).await?;
            render_leveling(ctx, data, interaction, guild_id).await
        }
        "announce_channel" => {
            let settings = db::leveling::settings(&data.db, guild_id).await?;
            let select = serenity::CreateSelectMenu::new(
                "settings:leveling:set_announce_channel",
                serenity::CreateSelectMenuKind::Channel {
                    channel_types: Some(vec![
                        serenity::ChannelType::Text,
                        serenity::ChannelType::News,
                    ]),
                    default_channels: settings
                        .announce_channel()
                        .map(|id| vec![serenity::ChannelId::new(id)]),
                },
            )
            .placeholder("Select a text or announcement channel…")
            .min_values(1)
            .max_values(1);
            reply(ctx, interaction, embeds::brand("📌 Level-up Announcement Channel").description("Choose where level-up messages are sent when Announce is set to **Set channel**. Leaving this unset falls back to the channel where the level was earned."), vec![CreateActionRow::SelectMenu(select), CreateActionRow::Buttons(vec![components::secondary("settings:leveling:refresh", "Back")])], true).await
        }
        "set_announce_channel" => {
            let channel_id = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::ChannelSelect { values } => {
                    values.first().map(|id| id.get())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a text channel"))?;
            let channel = ctx
                .http
                .get_channel(serenity::ChannelId::new(channel_id))
                .await?;
            if !matches!(channel, serenity::Channel::Guild(ref channel) if channel.guild_id.get() == guild_id && matches!(channel.kind, serenity::ChannelType::Text | serenity::ChannelType::News))
            {
                anyhow::bail!("choose a text or announcement channel in this server");
            }
            db::leveling::set_announce_channel(&data.db, guild_id, Some(channel_id)).await?;
            render_leveling(ctx, data, interaction, guild_id).await
        }
        "ignored" => {
            let settings = db::leveling::settings(&data.db, guild_id).await?;
            let select = serenity::CreateSelectMenu::new(
                "settings:leveling:set_ignored",
                serenity::CreateSelectMenuKind::Channel {
                    channel_types: Some(vec![
                        serenity::ChannelType::Text,
                        serenity::ChannelType::News,
                        serenity::ChannelType::Voice,
                        serenity::ChannelType::Stage,
                        serenity::ChannelType::Forum,
                        serenity::ChannelType::Category,
                    ]),
                    default_channels: Some(
                        settings
                            .ignored_channels()
                            .into_iter()
                            .map(serenity::ChannelId::new)
                            .collect(),
                    ),
                },
            )
            .placeholder("Select up to 25 ignored channels/categories…")
            .min_values(0)
            .max_values(25);
            reply(ctx, interaction, embeds::brand("🚫 Ignored XP Channels").description("No XP is earned in these channels. Ignoring a category also ignores its channels. Deselect all to clear."), vec![CreateActionRow::SelectMenu(select), CreateActionRow::Buttons(vec![components::secondary("settings:leveling:refresh", "Back")])], true).await
        }
        "set_ignored" => {
            let ids = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::ChannelSelect { values } => {
                    values.iter().map(|id| id.get()).collect::<Vec<_>>()
                }
                _ => Vec::new(),
            };
            if ids.len() > 25 {
                anyhow::bail!("select no more than 25 channels");
            }
            for id in &ids {
                let channel = ctx.http.get_channel(serenity::ChannelId::new(*id)).await?;
                if !matches!(channel, serenity::Channel::Guild(ref channel) if channel.guild_id.get() == guild_id && matches!(channel.kind, serenity::ChannelType::Text | serenity::ChannelType::News | serenity::ChannelType::Voice | serenity::ChannelType::Stage | serenity::ChannelType::Forum | serenity::ChannelType::Category))
                {
                    anyhow::bail!("one or more selected channels are not valid guild channels");
                }
            }
            db::leveling::set_ignored(&data.db, guild_id, &ids).await?;
            render_leveling(ctx, data, interaction, guild_id).await
        }
        "stack" => {
            let settings = db::leveling::settings(&data.db, guild_id).await?;
            db::leveling::set_stack_rewards(&data.db, guild_id, !settings.stack_rewards()).await?;
            render_leveling_rewards(ctx, data, interaction, guild_id).await
        }
        "message" => {
            let settings = db::leveling::settings(&data.db, guild_id).await?;
            let inputs = vec![CreateActionRow::InputText(
                components::paragraph(
                    "announce_message",
                    "Level-up message ({user}, {level}, {xp})",
                )
                .value(settings.announce_message.clone())
                .max_length(500),
            )];
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "settings:leveling_message_modal",
                        "Announcement message",
                        inputs,
                    ),
                )
                .await?;
            Ok(())
        }
        "rewards" => render_leveling_rewards(ctx, data, interaction, guild_id).await,
        "reward_add" => {
            let role_id = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::RoleSelect { values } => {
                    values.first().map(|id| id.get())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("select a role"))?;
            let role = ctx
                .cache
                .guild(serenity::GuildId::new(guild_id))
                .and_then(|guild| guild.roles.get(&serenity::RoleId::new(role_id)).cloned())
                .ok_or_else(|| anyhow::anyhow!("role not found in this server"))?;
            if role.id.get() == guild_id || role.managed {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Role unavailable",
                        "That role cannot be used as a level reward.",
                    ),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let inputs = vec![CreateActionRow::InputText(
                components::short("level", "Level required (1–500)")
                    .value("5")
                    .max_length(3),
            )];
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        &format!("settings:leveling_reward_modal:{role_id}"),
                        "Level Reward",
                        inputs,
                    ),
                )
                .await?;
            Ok(())
        }
        "reward_remove" => {
            let role_id = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().and_then(|id| id.parse::<u64>().ok())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("select a reward role to remove"))?;
            db::leveling::remove_reward(&data.db, guild_id, role_id).await?;
            render_leveling_rewards(ctx, data, interaction, guild_id).await
        }
        "reset" => {
            let embed = embeds::brand(format!("{} Reset XP", icons::TRASH))
                .description("Pick a member to reset their XP, or wipe everyone. Reward roles already granted will not be removed.");
            let user_select = serenity::CreateSelectMenu::new(
                "settings:leveling:reset_user",
                serenity::CreateSelectMenuKind::User {
                    default_users: None,
                },
            )
            .placeholder("Reset one member…")
            .min_values(1)
            .max_values(1);
            let rows = vec![
                CreateActionRow::SelectMenu(user_select),
                CreateActionRow::Buttons(vec![
                    components::danger("settings:leveling:reset_all", "Reset Everyone"),
                    components::secondary("settings:leveling:refresh", "Back"),
                ]),
            ];
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "reset_user" => {
            let user_id = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::UserSelect { values } => {
                    values.first().map(|id| id.get())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("pick a member to reset"))?;
            db::leveling::reset_user(&data.db, guild_id, user_id).await?;
            render_leveling_notice(
                ctx,
                data,
                interaction,
                guild_id,
                Some(format!("✅ Reset <@{user_id}>.")),
            )
            .await
        }
        "reset_all" => {
            let removed = db::leveling::reset_guild(&data.db, guild_id).await?;
            tracing::info!(guild_id, removed, "leveling XP reset for guild");
            render_leveling_notice(
                ctx,
                data,
                interaction,
                guild_id,
                Some("✅ Everyone's XP was reset.".to_string()),
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown leveling action `{other}`")),
    }
}

async fn render_leveling_rewards(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let (embed, rows) = leveling_rewards_payload(ctx, data, guild_id).await?;
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn leveling_rewards_payload(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
) -> anyhow::Result<(CreateEmbed, Vec<CreateActionRow>)> {
    let settings = db::leveling::settings(&data.db, guild_id).await?;
    let rewards = db::leveling::list_rewards(&data.db, guild_id).await?;
    let mut lines = rewards
        .iter()
        .take(20)
        .map(|reward| format!("Level **{}** → <@&{}>", reward.level, reward.role_id))
        .collect::<Vec<_>>();
    if rewards.len() > 20 {
        lines.push(format!("…and {} more", rewards.len() - 20));
    }
    if lines.is_empty() {
        lines.push("_No rewards yet._".to_string());
    }
    lines.push(format!(
        "\n**Mode:** {}",
        if settings.stack_rewards() {
            "Stack (keep all earned roles)"
        } else {
            "Replace (keep only the highest role)"
        }
    ));
    let embed = embeds::brand(format!("{} Role Rewards", icons::CROWN))
        .color(colors::GOLD)
        .description(lines.join("\n"))
        .footer(serenity::CreateEmbedFooter::new(theme::footer()));
    let add_role = serenity::CreateSelectMenu::new(
        "settings:leveling:reward_add",
        serenity::CreateSelectMenuKind::Role {
            default_roles: None,
        },
    )
    .placeholder("+ Add a reward role…")
    .min_values(1)
    .max_values(1);
    let mut rows = vec![CreateActionRow::SelectMenu(add_role)];
    if !rewards.is_empty() {
        let options = rewards
            .iter()
            .take(25)
            .filter_map(|reward| {
                let role_id = reward.role_id.parse::<u64>().ok()?;
                let name = ctx
                    .cache
                    .guild(serenity::GuildId::new(guild_id))
                    .and_then(|guild| {
                        guild
                            .roles
                            .get(&serenity::RoleId::new(role_id))
                            .map(|role| role.name.clone())
                    })
                    .unwrap_or_else(|| reward.role_id.clone());
                Some(serenity::CreateSelectMenuOption::new(
                    format!("Level {}: {name}", reward.level)
                        .chars()
                        .take(100)
                        .collect::<String>(),
                    role_id.to_string(),
                ))
            })
            .collect::<Vec<_>>();
        if !options.is_empty() {
            rows.push(CreateActionRow::SelectMenu(
                serenity::CreateSelectMenu::new(
                    "settings:leveling:reward_remove",
                    serenity::CreateSelectMenuKind::String { options },
                )
                .placeholder("Remove a reward…")
                .min_values(1)
                .max_values(1),
            ));
        }
    }
    rows.push(CreateActionRow::Buttons(vec![
        components::secondary(
            "settings:leveling:stack",
            if settings.stack_rewards() {
                "Mode: Stack"
            } else {
                "Mode: Replace"
            },
        ),
        components::secondary("settings:leveling:refresh", "Back"),
    ]));
    Ok((embed, rows))
}

// ------------------------------------------------------------- welcome

async fn render_welcome(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let settings = db::welcome::welcome(&data.db, guild_id).await?;
    let autorole = db::welcome::autorole(&data.db, guild_id).await?;
    let joindm = db::welcome::join_dm(&data.db, guild_id).await?;
    let cleanup = db::welcome::cleanup_settings(&data.db, guild_id).await?;
    let member_count = ctx
        .cache
        .guild(serenity::GuildId::new(guild_id))
        .map(|guild| guild.members.len() as u64)
        .unwrap_or(0);

    let view = panels::WelcomeView {
        channel: settings.channel(),
        avatar_mode: settings.avatar_mode.clone(),
        autorole_enabled: autorole.enabled(),
        member_roles: autorole.member_roles().len(),
        join_dm: joindm.join_dm_enabled(),
        reminder_interval: joindm.interval_days(),
        member_count: Some(member_count),
        cleanup_enabled: cleanup.enabled(),
        cleanup_delay_minutes: cleanup.delay_minutes(),
    };
    let (embed, rows) = panels::welcome_panel(&view);
    update_panel(ctx, data, interaction, embed, rows).await
}

/// Build the welcome preview embed with the clicking member as the sample,
/// matching JS `editor.previewEmbed` / `events.buildWelcomeEmbed`.
async fn welcome_preview_embed(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    user_id: u64,
) -> anyhow::Result<CreateEmbed> {
    let settings = db::welcome::welcome(&data.db, guild_id).await?;
    let guild = ctx.cache.guild(serenity::GuildId::new(guild_id));
    let server = guild
        .as_ref()
        .map(|guild| guild.name.clone())
        .unwrap_or_else(|| "this server".to_string());
    let member_count = guild
        .as_ref()
        .map(|guild| guild.members.len() as u64)
        .unwrap_or(0);
    let member = guild
        .as_ref()
        .and_then(|guild| guild.members.get(&serenity::UserId::new(user_id)));
    let cached = ctx.cache.user(user_id);
    let display_name = member
        .map(|member| member.display_name().to_string())
        .or_else(|| cached.as_ref().map(|user| user.name.clone()))
        .unwrap_or_else(|| "there".to_string());
    let username = cached
        .as_ref()
        .map(|user| user.name.clone())
        .unwrap_or_default();

    let rendered = settings.render(
        &format!("<@{user_id}>"),
        &display_name,
        &username,
        &server,
        member_count,
    );
    let mut embed = serenity::CreateEmbed::new()
        .title(rendered.title)
        .description(rendered.description)
        .color(rendered.color as u32)
        .footer(serenity::CreateEmbedFooter::new(theme::footer()));
    if rendered.avatar_mode == "member" {
        let avatar = member
            .and_then(|member| member.avatar_url())
            .or_else(|| cached.as_ref().and_then(|user| user.avatar_url()));
        if let Some(url) = avatar {
            embed = embed.thumbnail(url);
        }
    }
    Ok(embed)
}

/// Info + live preview embeds and the editor rows, shared by the component and
/// the color modal so both redraw the same screen.
async fn welcome_editor_payload(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
    user_id: u64,
) -> anyhow::Result<(Vec<CreateEmbed>, Vec<CreateActionRow>)> {
    let avatar_mode = db::welcome::welcome(&data.db, guild_id)
        .await
        .map(|settings| settings.avatar_mode)
        .unwrap_or_default();
    let (info, rows) = panels::welcome_editor_panel(&avatar_mode);
    let preview = welcome_preview_embed(ctx, data, guild_id, user_id).await?;
    Ok((vec![info, preview], rows))
}

async fn welcome_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("welcome settings only work inside a server"))?;

    if action.is_empty() || action == "refresh" {
        return render_welcome(ctx, data, interaction, guild_id).await;
    }

    let sub = action.trim_start_matches(':');
    match sub {
        "cleanup" | "cleanup_back" => {
            let settings = db::welcome::cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::welcome_cleanup_panel(&settings);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "cleanup_toggle" => {
            let settings = db::welcome::cleanup_settings(&data.db, guild_id).await?;
            db::welcome::set_cleanup_settings(
                &data.db,
                guild_id,
                !settings.enabled(),
                settings.delay_minutes(),
            )
            .await?;
            let settings = db::welcome::cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::welcome_cleanup_panel(&settings);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "cleanup_delay" => {
            let minutes = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values
                    .first()
                    .and_then(|value| value.parse::<i64>().ok())
                    .unwrap_or(1440),
                _ => 1440,
            };
            db::welcome::set_cleanup_settings(&data.db, guild_id, true, minutes).await?;
            let settings = db::welcome::cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::welcome_cleanup_panel(&settings);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "cleanup_custom" => {
            let settings = db::welcome::cleanup_settings(&data.db, guild_id).await?;
            let inputs = vec![CreateActionRow::InputText(
                components::short("minutes", "Delete after minutes (1–43200)")
                    .value(settings.delay_minutes().to_string()),
            )];
            send_modal(
                ctx,
                interaction,
                "settings:welcome_cleanup_modal",
                "Welcome Cleanup Delay",
                inputs,
            )
            .await
        }
        "channel" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Channel id or `none` to disable",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("settings:welcome_channel_modal", "Welcome channel", inputs),
                )
                .await?;
            Ok(())
        }
        "editor" => {
            let (embeds, rows) =
                welcome_editor_payload(ctx, data, guild_id, interaction.user.id.get()).await?;
            update_panel_embeds(ctx, data, interaction, embeds, rows).await
        }
        "color" => {
            let current = db::welcome::welcome(&data.db, guild_id)
                .await
                .map(|settings| settings.embed_color.unwrap_or(0x5865F2))
                .unwrap_or(0x5865F2);
            let inputs = vec![CreateActionRow::InputText(
                components::short("color", "Color (hex, e.g. 5865f2)")
                    .value(format!("{current:x}"))
                    .max_length(7),
            )];
            send_modal(
                ctx,
                interaction,
                "settings:welcome_color_modal",
                "Edit Color",
                inputs,
            )
            .await
        }
        "title" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "title",
                "Title ({mention}, {user}, {tag}, {server}, {membercount})",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("settings:welcome_title_modal", "Welcome title", inputs),
                )
                .await?;
            Ok(())
        }
        "description" => {
            let inputs = vec![CreateActionRow::InputText(components::paragraph(
                "description",
                "Description ({mention}, {user}, {tag}, {server}, {membercount})",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "settings:welcome_description_modal",
                        "Welcome description",
                        inputs,
                    ),
                )
                .await?;
            Ok(())
        }
        "avatar" => {
            let current = db::welcome::welcome(&data.db, guild_id)
                .await
                .map(|row| row.avatar_mode)
                .unwrap_or_else(|_| "off".to_string());
            let next = match current.as_str() {
                "off" => "member",
                "member" => "server",
                _ => "off",
            };
            db::welcome::set_welcome_field(
                &data.db,
                guild_id,
                db::welcome::WelcomeField::AvatarMode,
                next,
            )
            .await?;
            render_welcome(ctx, data, interaction, guild_id).await
        }
        "autorole" => {
            let enabled = db::welcome::autorole(&data.db, guild_id)
                .await
                .map(|row| row.enabled())
                .unwrap_or(true);
            db::welcome::set_autorole_enabled(&data.db, guild_id, !enabled).await?;
            render_welcome(ctx, data, interaction, guild_id).await
        }
        "joindm" => {
            let enabled = db::welcome::join_dm(&data.db, guild_id)
                .await
                .map(|row| row.join_dm_enabled())
                .unwrap_or(true);
            db::welcome::set_join_dm(&data.db, guild_id, !enabled).await?;
            render_welcome(ctx, data, interaction, guild_id).await
        }
        "preview" => {
            let embed =
                welcome_preview_embed(ctx, data, guild_id, interaction.user.id.get()).await?;
            // JS Toolkit "Test" audits the preview; normal hub previews do not.
            let from_toolkit = crate::admintoolkit::tool_of(
                interaction.message.id.get(),
                interaction.user.id.get(),
                guild_id,
            )
            .as_deref()
                == Some("welcome")
                || crate::db::admin_toolkit::find_post(&data.db, interaction.message.id.get())
                    .await
                    .ok()
                    .flatten()
                    .is_some_and(|(post_guild, tool)| post_guild == guild_id && tool == "welcome");
            if from_toolkit {
                crate::admintoolkit::log_audit(
                    ctx,
                    data,
                    guild_id,
                    interaction.user.id.get(),
                    Some("welcome"),
                    "open",
                    Some("Previewed welcome message"),
                )
                .await;
            }
            interaction
                .create_response(
                    &ctx.http,
                    serenity::CreateInteractionResponse::Message(
                        serenity::CreateInteractionResponseMessage::new()
                            .content("Preview of the welcome message (nothing was posted):")
                            .embed(embed)
                            .ephemeral(true),
                    ),
                )
                .await?;
            Ok(())
        }
        other => Err(anyhow::anyhow!("unknown welcome action `{other}`")),
    }
}

// ---------------------------------------------------- generic settings panels

/// Locked-feature gate — returns true when any `keys` is force-disabled on
/// this server (Bot Owner override via server_feature_flags).
async fn settings_flag_locked(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    keys: &[&str],
) -> anyhow::Result<bool> {
    for key in keys {
        if !db::subscriptions::is_feature_enabled(&data.db, guild_id, key).await {
            let embed = embeds::warn(
                "Feature disabled",
                format!(
                    "**{}** is disabled on this server.\n\nThe Bot Owner can re-enable it from **Owner Panel → Features**.",
                    key.replace('_', " ")
                ),
            );
            // Most clicks are unacknowledged, but confirmed Toolkit actions
            // pre-acknowledge with "⏳ Working…"; edit that response instead of
            // failing on a second acknowledgement.
            if let Err(err) = reply(ctx, interaction, embed.clone(), Vec::new(), true).await {
                tracing::debug!(%err, "feature-disabled reply failed; editing response");
                let _ = interaction
                    .edit_response(&ctx.http, EditInteractionResponse::new().embed(embed))
                    .await;
            }
            return Ok(true);
        }
    }
    Ok(false)
}

async fn settings_feature_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
    ns: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("settings only work inside a server"))?;

    // Everything after `settings:<ns>:` is the sub-action. Deriving it from
    // the colon boundary keeps mapped aliases (e.g. `settings:logs` →
    // `logging`) from slicing past the end of the button id.
    let sub = action.split_once(':').map(|(_, rest)| rest).unwrap_or("");
    match ns {
        "logging" => logging_panel_action(ctx, data, interaction, sub, guild_id).await,
        "tempvoice" => tempvoice_panel_action(ctx, data, interaction, sub, guild_id).await,
        "voting" => voting_panel_action(ctx, data, interaction, sub, guild_id).await,
        "birthday" => birthday_panel_action(ctx, data, interaction, sub, guild_id).await,
        // Tickets now uses the JS-compatible `ticket:*` admin hub. Any old
        // `settings:tickets:*` deep link simply opens that hub.
        "tickets" => crate::tickets::show_hub(ctx, data, interaction, guild_id).await,
        "giveaways" => giveaways_panel_action(ctx, data, interaction, sub, guild_id).await,
        "messages" => messages_panel_action(ctx, data, interaction, sub, guild_id).await,
        "cleanup" => cleanup_panel_action(ctx, data, interaction, sub, guild_id).await,
        "sneakpeek" => sneakpeek_panel_action(ctx, data, interaction, sub, guild_id).await,
        "wos" => wos_panel_action(ctx, data, interaction, sub, guild_id).await,
        "index" => index_panel_action(ctx, data, interaction, sub, guild_id).await,
        "roles" => roles_panel_action(ctx, data, interaction, sub, guild_id).await,
        "notifications" => notifications_panel_action(ctx, data, interaction, sub, guild_id).await,
        "calculator" => calculator_panel_action(ctx, data, interaction, sub, guild_id).await,
        "ministry" => return ministry_settings_page(ctx, data, interaction, guild_id).await,
        "admin" => return admin_panel(ctx, data, guild_id).await.map(|_| ()),
        "branding" => return branding_settings_page(ctx, data, interaction, guild_id).await,
        other => Err(anyhow::anyhow!("unknown settings panel `{other}`")),
    }
}

