async fn render_birthday_editor(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let settings = db::birthdays::settings(&data.db, guild_id).await?;
    let server = ctx
        .cache
        .guild(guild_id)
        .map(|g| g.name.clone())
        .unwrap_or_else(|| "this server".into());
    let (title, description, color) = db::birthdays::render(
        &settings,
        &format!("<@{}>", interaction.user.id.get()),
        &interaction.user.name,
        &interaction.user.tag(),
        &server,
        100,
    )
    .await;
    let mut preview = serenity::CreateEmbed::new()
        .title(title)
        .description(description)
        .color(color);
    if matches!(settings.avatar_mode.as_str(), "thumbnail" | "both") {
        preview = preview.thumbnail(interaction.user.face());
    }
    if matches!(settings.avatar_mode.as_str(), "banner" | "both") {
        preview = preview.image(interaction.user.face());
    }
    let info = embeds::brand("✏️ Edit Birthday Message")
        .description("Customize the announcement shown when a birthday comes up. Placeholders: `{mention}`, `{user}`, `{tag}`, `{server}`, `{membercount}`. Preview uses your account as a sample.");
    let rows = vec![
        CreateActionRow::Buttons(vec![
            components::secondary("settings:birthday:edit_title", "Title"),
            components::secondary("settings:birthday:edit_description", "Description"),
            components::secondary("settings:birthday:edit_color", "Color"),
        ]),
        CreateActionRow::Buttons(vec![
            components::primary(
                "settings:birthday:avatar_mode",
                format!("Avatar: {}", settings.avatar_mode),
            ),
            components::secondary("settings:birthday:refresh", "Back"),
        ]),
    ];
    interaction
        .create_response(
            &ctx.http,
            CreateInteractionResponse::Message(
                CreateInteractionResponseMessage::new()
                    .embeds(vec![info, preview])
                    .components(rows)
                    .ephemeral(true),
            ),
        )
        .await?;
    Ok(())
}

async fn render_birthday_list(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    page: usize,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    const PAGE_SIZE: usize = 25;
    let birthdays = db::birthdays::list(&data.db, guild_id).await?;
    let pages = birthdays.len().div_ceil(PAGE_SIZE).max(1);
    let page = page.min(pages - 1);
    let slice = birthdays
        .iter()
        .skip(page * PAGE_SIZE)
        .take(PAGE_SIZE)
        .collect::<Vec<_>>();
    let embed =
        embeds::brand("📋 View/Edit Members' Birthdays").description(if birthdays.is_empty() {
            "No birthdays are stored for this server yet.".to_string()
        } else {
            format!(
                "{} stored birthday(s). Select a member to view, edit, or delete their birthday.",
                birthdays.len()
            )
        });
    let mut rows = Vec::new();
    if !slice.is_empty() {
        let mut options = Vec::with_capacity(slice.len());
        for birthday in slice {
            let user_id = birthday.user_id.parse::<u64>().unwrap_or_default();
            let label = match ctx.http.get_user(serenity::UserId::new(user_id)).await {
                Ok(user) => user.name,
                Err(_) => format!("Member {user_id}"),
            };
            options.push(
                serenity::CreateSelectMenuOption::new(
                    label.chars().take(100).collect::<String>(),
                    user_id.to_string(),
                )
                .description(db::birthdays::format_day_month(
                    birthday.day,
                    birthday.month,
                )),
            );
        }
        let select = serenity::CreateSelectMenu::new(
            format!("settings:birthday:browse_select:{page}"),
            serenity::CreateSelectMenuKind::String { options },
        )
        .placeholder("Select a member")
        .min_values(1)
        .max_values(1);
        rows.push(CreateActionRow::SelectMenu(select));
    }
    if pages > 1 {
        rows.push(CreateActionRow::Buttons(vec![
            components::secondary(
                format!("settings:birthday:browse:{}", page.saturating_sub(1)),
                "◀ Prev",
            ),
            components::secondary(
                format!("settings:birthday:browse:{}", (page + 1).min(pages - 1)),
                "Next ▶",
            ),
        ]));
    }
    rows.push(CreateActionRow::Buttons(vec![components::secondary(
        "settings:birthday:refresh",
        "Back",
    )]));
    reply(ctx, interaction, embed, rows, true).await
}

async fn render_birthday_member(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    user_id: u64,
    page: usize,
    confirm_delete: bool,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let Some(birthday) = db::birthdays::get(&data.db, guild_id, user_id).await? else {
        return render_birthday_list(ctx, data, interaction, guild_id, page).await;
    };
    let user = ctx.http.get_user(serenity::UserId::new(user_id)).await.ok();
    let name = user
        .as_ref()
        .map(|u| u.name.as_str())
        .unwrap_or("Unknown member");
    let (title, description) = if confirm_delete {
        (
            "⚠️ Delete birthday?".to_string(),
            format!("Remove the stored birthday for **{name}**? This cannot be undone."),
        )
    } else {
        (
            format!("🎂 {name}"),
            format!(
                "**Birthday:** {}\n**Set by:** <@{}>\n**Last updated:** {}",
                db::birthdays::format_day_month(birthday.day, birthday.month),
                birthday.set_by,
                birthday.set_at
            ),
        )
    };
    let embed = embeds::brand(title).description(description);
    let rows = if confirm_delete {
        vec![CreateActionRow::Buttons(vec![
            components::danger(
                format!("settings:birthday:delete_confirm:{user_id}:{page}"),
                "Delete birthday",
            ),
            components::secondary(
                format!("settings:birthday:member:{user_id}:{page}"),
                "Cancel",
            ),
        ])]
    } else {
        vec![
            CreateActionRow::Buttons(vec![
                components::primary(
                    format!("settings:birthday:member_edit:{user_id}:{page}"),
                    "Edit",
                ),
                components::danger(
                    format!("settings:birthday:delete:{user_id}:{page}"),
                    "Delete",
                ),
            ]),
            CreateActionRow::Buttons(vec![components::secondary(
                format!("settings:birthday:browse:{page}"),
                "Back to list",
            )]),
        ]
    };
    reply(ctx, interaction, embed, rows, true).await
}

async fn birthday_panel_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    sub: &str,
    guild_id: u64,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    match sub {
        "" | "refresh" => render_birthday(ctx, data, interaction, guild_id).await,
        "channel" => {
            let menu = serenity::CreateSelectMenu::new(
                "settings:birthday:channel_select",
                serenity::CreateSelectMenuKind::Channel {
                    channel_types: Some(vec![
                        serenity::ChannelType::Text,
                        serenity::ChannelType::News,
                    ]),
                    default_channels: None,
                },
            )
            .placeholder("Choose birthday panel and announcement channel")
            .min_values(1)
            .max_values(1);
            reply(ctx, interaction, embeds::brand("🎂 Birthday panel channel").description("The panel will be posted here. Birthday announcements will also use this channel."), vec![CreateActionRow::SelectMenu(menu)], true).await
        }
        "channel_select" => {
            let Some(channel_id) = (match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::ChannelSelect { values } => {
                    values.first().map(|id| id.get())
                }
                _ => None,
            }) else {
                return Err(anyhow::anyhow!("choose a channel"));
            };
            let _channel = match ctx
                .http
                .get_channel(serenity::ChannelId::new(channel_id))
                .await?
            {
                serenity::Channel::Guild(channel)
                    if channel.guild_id.get() == guild_id
                        && matches!(
                            channel.kind,
                            serenity::ChannelType::Text | serenity::ChannelType::News
                        ) =>
                {
                    channel
                }
                _ => {
                    return Err(anyhow::anyhow!(
                        "choose a text or announcement channel in this server"
                    ))
                }
            };
            let embed = embeds::brand("🎂 Birthday Signup")
                .color(colors::VIOLET)
                .description("**Optional & free** — share your **day & month** so the server can celebrate you.\n\n🔒 We only store your day and month, never your birth year.")
                .footer(serenity::CreateEmbedFooter::new(theme::footer()));
            let row = CreateActionRow::Buttons(vec![
                components::primary("bdaypanel:set", "🎂 Add / update my birthday"),
                components::secondary("bdaypanel:translate", "🌐 Translate"),
            ]);
            let message = serenity::ChannelId::new(channel_id)
                .send_message(
                    &ctx.http,
                    serenity::CreateMessage::new()
                        .embed(embed)
                        .components(vec![row]),
                )
                .await?;
            db::birthdays::set_channel(
                &data.db,
                guild_id,
                Some(channel_id),
                Some(message.id.get()),
            )
            .await?;
            render_birthday(ctx, data, interaction, guild_id).await
        }
        "editmsg" => render_birthday_editor(ctx, data, interaction, guild_id).await,
        action if action.starts_with("browse:") => {
            let page = action
                .strip_prefix("browse:")
                .unwrap_or("0")
                .parse::<usize>()
                .unwrap_or(0);
            render_birthday_list(ctx, data, interaction, guild_id, page).await
        }
        action if action.starts_with("browse_select:") => {
            let page = action
                .strip_prefix("browse_select:")
                .unwrap_or("0")
                .parse::<usize>()
                .unwrap_or(0);
            let selected = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values.first(),
                _ => None,
            };
            let Some(user_id) = selected.and_then(|v| v.parse::<u64>().ok()) else {
                return Err(anyhow::anyhow!("choose a member"));
            };
            render_birthday_member(ctx, data, interaction, guild_id, user_id, page, false).await
        }
        action if action.starts_with("member:") => {
            let mut parts = action
                .strip_prefix("member:")
                .unwrap_or_default()
                .split(':');
            let user_id = parts.next().unwrap_or_default().parse::<u64>()?;
            let page = parts.next().unwrap_or("0").parse::<usize>().unwrap_or(0);
            render_birthday_member(ctx, data, interaction, guild_id, user_id, page, false).await
        }
        action if action.starts_with("member_edit:") => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let mut parts = action
                .strip_prefix("member_edit:")
                .unwrap_or_default()
                .split(':');
            let user_id = parts.next().unwrap_or_default().parse::<u64>()?;
            let Some(birthday) = db::birthdays::get(&data.db, guild_id, user_id).await? else {
                return render_birthday_list(ctx, data, interaction, guild_id, 0).await;
            };
            let inputs = vec![
                CreateActionRow::InputText(
                    components::short("day", "Day (1-31)")
                        .value(birthday.day.to_string())
                        .max_length(2),
                ),
                CreateActionRow::InputText(
                    components::short("month", "Month (1-12 or name)")
                        .value(birthday.month.to_string())
                        .max_length(20),
                ),
            ];
            send_modal(
                ctx,
                interaction,
                &format!("settings:birthday_member_modal:{user_id}"),
                "Edit Birthday",
                inputs,
            )
            .await
        }
        action if action.starts_with("delete:") => {
            let mut parts = action
                .strip_prefix("delete:")
                .unwrap_or_default()
                .split(':');
            let user_id = parts.next().unwrap_or_default().parse::<u64>()?;
            let page = parts.next().unwrap_or("0").parse::<usize>().unwrap_or(0);
            render_birthday_member(ctx, data, interaction, guild_id, user_id, page, true).await
        }
        action if action.starts_with("delete_confirm:") => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let mut parts = action
                .strip_prefix("delete_confirm:")
                .unwrap_or_default()
                .split(':');
            let user_id = parts.next().unwrap_or_default().parse::<u64>()?;
            let page = parts.next().unwrap_or("0").parse::<usize>().unwrap_or(0);
            db::birthdays::delete(&data.db, guild_id, user_id).await?;
            render_birthday_list(ctx, data, interaction, guild_id, page).await
        }
        "cleanup" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return Err(anyhow::anyhow!("administrator permission required"));
            }
            let current = db::welcome::birthday_cleanup_settings(&data.db, guild_id).await?;
            let toggle_label = if current.enabled() {
                "Disable"
            } else {
                "Enable"
            };
            let toggle = components::secondary(
                "settings:birthday:cleanup_toggle",
                format!("{toggle_label} auto-delete"),
            );
            let options = [(1440, "1 day"), (10080, "7 days"), (43200, "30 days")]
                .into_iter()
                .map(|(minutes, label)| {
                    serenity::CreateSelectMenuOption::new(label, minutes.to_string())
                })
                .collect();
            let select = serenity::CreateSelectMenu::new(
                "settings:birthday:cleanup_delay",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder(format!(
                "Current delay: {} minutes",
                current.delay_minutes()
            ))
            .min_values(1)
            .max_values(1);
            reply(
                ctx,
                interaction,
                embeds::brand("🧹 Birthday Clean Up")
                    .description("Automatically delete old birthday announcements after the selected delay. The birthday signup panel is kept.")
                    .field("Auto-delete", if current.enabled() { "On" } else { "Off" }, true)
                    .field("Delay", format!("{} minutes", current.delay_minutes()), true),
                vec![
                    CreateActionRow::Buttons(vec![toggle]),
                    CreateActionRow::SelectMenu(select),
                    CreateActionRow::Buttons(vec![components::secondary(
                        "settings:birthday:refresh",
                        "Back",
                    )]),
                ],
                true,
            )
            .await
        }
        "cleanup_toggle" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return Err(anyhow::anyhow!("administrator permission required"));
            }
            let current = db::welcome::birthday_cleanup_settings(&data.db, guild_id).await?;
            db::welcome::set_birthday_cleanup_settings(
                &data.db,
                guild_id,
                !current.enabled(),
                current.delay_minutes(),
            )
            .await?;
            Box::pin(birthday_panel_action(
                ctx,
                data,
                interaction,
                "cleanup",
                guild_id,
            ))
            .await
        }
        "cleanup_delay" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return Err(anyhow::anyhow!("administrator permission required"));
            }
            let selected = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values.first(),
                _ => None,
            };
            let Some(minutes) = selected.and_then(|v| v.parse::<i64>().ok()) else {
                return Err(anyhow::anyhow!("choose a cleanup delay"));
            };
            let current = db::welcome::birthday_cleanup_settings(&data.db, guild_id).await?;
            db::welcome::set_birthday_cleanup_settings(
                &data.db,
                guild_id,
                current.enabled(),
                minutes,
            )
            .await?;
            Box::pin(birthday_panel_action(
                ctx,
                data,
                interaction,
                "cleanup",
                guild_id,
            ))
            .await
        }
        "avatar_mode" => {
            let current = db::birthdays::settings(&data.db, guild_id)
                .await?
                .avatar_mode;
            let next = match current.as_str() {
                "off" => "thumbnail",
                "thumbnail" => "banner",
                "banner" => "both",
                _ => "off",
            };
            db::birthdays::set_avatar_mode(&data.db, guild_id, next).await?;
            render_birthday_editor(ctx, data, interaction, guild_id).await
        }
        action if action.starts_with("edit_") => {
            let field = action.strip_prefix("edit_").unwrap_or_default();
            let settings = db::birthdays::settings(&data.db, guild_id).await?;
            let (custom_id, title, value) = match field {
                "title" => (
                    "settings:birthday_title_modal",
                    "Birthday title",
                    settings
                        .embed_title
                        .unwrap_or_else(|| "🎉 Happy Birthday!".into()),
                ),
                "description" => (
                    "settings:birthday_description_modal",
                    "Birthday description",
                    settings.embed_description.unwrap_or_else(|| {
                        "🎉 {mention} is celebrating their birthday today! Wish them well!".into()
                    }),
                ),
                "color" => (
                    "settings:birthday_color_modal",
                    "Birthday color",
                    format!("{:06x}", settings.embed_color.unwrap_or(0xF47FFF)),
                ),
                _ => return Err(anyhow::anyhow!("unknown birthday editor field")),
            };
            send_modal(
                ctx,
                interaction,
                custom_id,
                title,
                vec![CreateActionRow::InputText(
                    components::paragraph("value", "Text or hex color")
                        .value(value)
                        .max_length(3800),
                )],
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown birthday action `{other}`")),
    }
}

