    if page > 0 {
        nav.push(components::secondary(
            format!(
                "settings:messages:manage_template_page:{group_id}:{}",
                page - 1
            ),
            "◀️ Previous",
        ));
    }
    nav.push(components::secondary(
        "settings:messages:manage",
        "◀️ Groups",
    ));
    if page + 1 < pages {
        nav.push(components::secondary(
            format!(
                "settings:messages:manage_template_page:{group_id}:{}",
                page + 1
            ),
            "Next ▶️",
        ));
    }
    nav.push(components::secondary(
        "settings:messages:refresh",
        "Main Menu",
    ));
