async fn render_tracked_message_list(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    channel_id: u64,
    page: usize,
) -> anyhow::Result<()> {
    let total = db::messages::tracked_message_count(&data.db, guild_id, channel_id).await?;
    let pages = ((total as usize).max(1)).div_ceil(25);
    let page = page.min(pages.saturating_sub(1));
    let messages =
        db::messages::list_tracked_messages(&data.db, guild_id, channel_id, 25, (page * 25) as i64)
            .await?;
    let body = if total == 0 {
        "_No tracked Messages posts in this channel._".to_string()
    } else {
        format!("{total} tracked post(s). Select one to edit or delete.")
    };
    let embed = embeds::brand(format!("✏️ <#{channel_id}>"))
        .color(colors::TEAL)
        .description(body);
    let mut rows = Vec::new();
    if !messages.is_empty() {
        let options = messages
            .iter()
            .map(|message| {
                let label = message
                    .plain_text
                    .as_deref()
                    .unwrap_or("Message")
                    .chars()
                    .take(100)
                    .collect::<String>();
                let description = message
                    .sent_at
                    .as_deref()
                    .map(|date| format!("Sent {date}"))
                    .unwrap_or_else(|| format!("Message {}", message.message_id));
                serenity::CreateSelectMenuOption::new(label, message.id.to_string())
                    .description(description.chars().take(100).collect::<String>())
            })
            .collect();
        rows.push(CreateActionRow::SelectMenu(
            serenity::CreateSelectMenu::new(
                "settings:messages:tracked_select",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Select a sent message")
            .min_values(1)
            .max_values(1),
        ));
    }
    if pages > 1 {
        rows.push(CreateActionRow::Buttons(vec![
            components::secondary(
                format!(
                    "settings:messages:tracked_page:{channel_id}:{}",
                    page.saturating_sub(1)
                ),
                "◀ Prev",
            )
            .disabled(page == 0),
            components::secondary(
                "settings:messages:noop",
                format!("Page {}/{}", page + 1, pages),
            )
            .disabled(true),
            components::secondary(
                format!("settings:messages:tracked_page:{channel_id}:{}", page + 1),
                "Next ▶",
            )
            .disabled(page + 1 >= pages),
        ]));
    }
    rows.push(CreateActionRow::Buttons(vec![components::secondary(
        "settings:messages:edit",
        "◀️ Choose channel",
    )]));
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn render_tracked_message_detail(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    id: i64,
) -> anyhow::Result<()> {
    let tracked = db::messages::get_tracked_message(&data.db, guild_id, id)
        .await?
        .ok_or_else(|| anyhow::anyhow!("tracked message not found"))?;
    let preview = if tracked.is_embed != 0 {
        format!(
            "**{}**\n{}\nColor: `{}`\nImage: {}\nThumbnail: {}",
            tracked.embed_title.as_deref().unwrap_or("Untitled embed"),
            tracked
                .embed_description
                .as_deref()
                .unwrap_or("_No description_"),
            tracked
                .embed_color
                .map(|value| format!("#{value:06x}"))
                .unwrap_or_else(|| "default".to_string()),
            tracked.embed_image_url.as_deref().unwrap_or("—"),
            tracked.embed_thumbnail_url.as_deref().unwrap_or("—"),
        )
    } else {
        tracked
            .plain_text
            .as_deref()
            .unwrap_or("_No content_")
            .to_string()
    };
    let embed = embeds::brand("✉️ Sent Message")
        .color(colors::TEAL)
        .description(format!(
            "Posted in <#{}> at {}.\n\n{}",
            tracked.channel_id,
            tracked.sent_at.as_deref().unwrap_or("unknown time"),
            preview
        ));
    let mut buttons = Vec::new();
    buttons.push(components::primary(
        format!("settings:messages:tracked_edit:{id}"),
        "✏️ Edit",
    ));
    buttons.push(components::danger(
        format!("settings:messages:tracked_delete:{id}"),
        "🗑️ Delete",
    ));
    buttons.push(components::secondary(
        format!(
            "settings:messages:tracked_select_back:{}",
            tracked.channel_id
        ),
        "◀️ Back to list",
    ));
    update_panel(
        ctx,
        data,
        interaction,
        embed,
        vec![CreateActionRow::Buttons(buttons)],
    )
    .await
}

async fn delete_tracked_message(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    id: i64,
) -> anyhow::Result<()> {
    let Some(tracked) = db::messages::get_tracked_message(&data.db, guild_id, id).await? else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Not found", "This tracked message is already gone."),
            Vec::new(),
            true,
        )
        .await;
    };
    if let (Ok(channel), Ok(message)) = (
        tracked.channel_id.parse::<u64>(),
        tracked.message_id.parse::<u64>(),
    ) {
        if let Err(err) = serenity::ChannelId::new(channel)
            .delete_message(&ctx.http, serenity::MessageId::new(message))
            .await
        {
            tracing::debug!(error = %err, channel, message, "tracked Messages post delete failed; removing stale tracker row");
        }
    }
    db::messages::delete_tracked_message(&data.db, guild_id, id).await?;
    render_tracked_message_list(
        ctx,
        data,
        interaction,
        guild_id,
        tracked.channel_id.parse()?,
        0,
    )
    .await
}

