// ---------------------------------------------------------- sneakpeek panel

async fn render_sneakpeek(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let settings = db::sneak_peek::settings(&data.db, guild_id).await?;
    let state = db::sneak_peek::state(&data.db).await.unwrap_or_default();
    let view = panels::SneakPeekView {
        channel: settings.channel(),
        last_article: state.last_url,
        last_checked: state.checked_at,
    };
    let (embed, rows) = panels::sneakpeek_panel(&view);
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn sneakpeek_panel_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    sub: &str,
    guild_id: u64,
) -> anyhow::Result<()> {
    match sub {
        "" | "refresh" => render_sneakpeek(ctx, data, interaction, guild_id).await,
        "channel" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Channel id (or `none`)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:sneakpeek_channel_modal",
                "Sneak Peek channel",
                inputs,
            )
            .await
        }
        "check" => {
            let destinations = db::sneak_peek::destinations(&data.db).await?;
            if destinations.is_empty() {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn("Not configured", "Set a Sneak Peek channel first."),
                    Vec::new(),
                    true,
                )
                .await;
            }
            match crate::sneakpeek::fetch_latest_url().await {
                Ok(Some(url)) => {
                    let state = db::sneak_peek::state(&data.db).await.unwrap_or_default();
                    let status = if state.last_url.as_deref() == Some(url.as_str()) {
                        "No new article since the last check."
                    } else {
                        "New article found — it will be posted by the background poller within ~20 minutes."
                    };
                    reply(
                        ctx,
                        interaction,
                        embeds::info("Sneak Peek", format!("{status}\nLatest: {url}")),
                        Vec::new(),
                        true,
                    )
                    .await
                }
                Ok(None) => {
                    reply(
                        ctx,
                        interaction,
                        embeds::warn(
                            "No article",
                            "No sneak-peek article found on the wiki right now.",
                        ),
                        Vec::new(),
                        true,
                    )
                    .await
                }
                Err(err) => {
                    reply(
                        ctx,
                        interaction,
                        embeds::error("Check failed", format!("`{}`", crate::error::public(&err))),
                        Vec::new(),
                        true,
                    )
                    .await
                }
            }
        }
        "sendlink" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "url",
                "Wiki article URL (e.g. https://www.whiteoutsurvival.wiki/sneak-peek/080366853en/)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:sneakpeek_sendlink_modal",
                "Post a Sneak Peek",
                inputs,
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown sneakpeek action `{other}`")),
    }
}

// --------------------------------------------------------- server index panel

async fn render_index(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let settings = db::server_index::get(&data.db, guild_id).await?;
    let join_dm = db::welcome::join_dm(&data.db, guild_id).await?;
    let view = panels::ServerIndexView {
        channel: settings.channel(),
        enabled: settings.enabled(),
        include_threads: settings.include_threads(),
        include_voice: settings.include_voice(),
        message_count: settings.message_ids().len(),
        join_dm_enabled: join_dm.join_dm_enabled(),
        reminder_enabled: join_dm.reminders_enabled(),
        reminder_interval_days: join_dm.interval_days(),
    };
    let (embed, rows) = panels::server_index_panel(&view);
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn index_panel_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    sub: &str,
    guild_id: u64,
) -> anyhow::Result<()> {
    match sub {
        "" | "refresh" => render_index(ctx, data, interaction, guild_id).await,
        "channel" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Channel id (or `none` to clear)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:index_channel_modal",
                "Index channel",
                inputs,
            )
            .await
        }
        "toggle" => {
            let settings = db::server_index::get(&data.db, guild_id).await?;
            db::server_index::set_enabled(&data.db, guild_id, !settings.enabled()).await?;
            render_index(ctx, data, interaction, guild_id).await
        }
        "threads" => {
            let settings = db::server_index::get(&data.db, guild_id).await?;
            db::server_index::set_include_threads(&data.db, guild_id, !settings.include_threads())
                .await?;
            render_index(ctx, data, interaction, guild_id).await
        }
        "voice" => {
            let settings = db::server_index::get(&data.db, guild_id).await?;
            db::server_index::set_include_voice(&data.db, guild_id, !settings.include_voice())
                .await?;
            render_index(ctx, data, interaction, guild_id).await
        }
        "joindm" => {
            let settings = db::welcome::join_dm(&data.db, guild_id).await?;
            db::welcome::set_join_dm(&data.db, guild_id, !settings.join_dm_enabled()).await?;
            render_index(ctx, data, interaction, guild_id).await
        }
        "reminder" => {
            let settings = db::welcome::join_dm(&data.db, guild_id).await?;
            db::welcome::set_reminder_enabled(&data.db, guild_id, !settings.reminders_enabled())
                .await?;
            render_index(ctx, data, interaction, guild_id).await
        }
        "rebuild" => {
            interaction
                .create_response(
                    &ctx.http,
                    CreateInteractionResponse::Defer(
                        CreateInteractionResponseMessage::new().ephemeral(true),
                    ),
                )
                .await?;
            let result = crate::serverindex::publish(ctx, data, guild_id, true).await;
            let embed = match result {
                Ok(ids) => embeds::ok(format!("Index rebuilt — {} message(s).", ids.len())),
                Err(err) => embeds::error(
                    "Rebuild failed",
                    format!("`{}`", crate::error::public(&err)),
                ),
            };
            interaction
                .edit_response(&ctx.http, EditInteractionResponse::new().embed(embed))
                .await?;
            Ok(())
        }
        other => Err(anyhow::anyhow!("unknown index action `{other}`")),
    }
}

// --------------------------------------------------------- roles panel

fn role_name(ctx: &serenity::Context, guild_id: u64, role_id: u64) -> String {
    ctx.cache
        .guild(serenity::GuildId::new(guild_id))
        .and_then(|guild| {
            guild
                .roles
                .get(&serenity::RoleId::new(role_id))
                .map(|role| role.name.clone())
        })
        .unwrap_or_else(|| format!("role {role_id}"))
}

async fn render_roles(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let panel = db::roles::panel_settings(&data.db, guild_id)
        .await?
        .unwrap_or_default();
    let catalog = db::roles::catalog_summaries(&data.db, guild_id).await?;
    let grants = db::roles::grant_summaries(&data.db, guild_id).await?;
    let view = panels::RolesPanelView {
        channel: panel.0,
        panel_message_id: panel.1,
        catalog: catalog.into_iter().take(20).collect(),
        grants: grants
            .into_iter()
            .take(20)
            .map(|(role_id, users, roles)| (role_id, users.len(), roles.len()))
            .collect(),
    };
    let (embed, rows) = panels::roles_panel(&view);
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn roles_panel_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    sub: &str,
    guild_id: u64,
) -> anyhow::Result<()> {
    match sub {
        "" | "refresh" => render_roles(ctx, data, interaction, guild_id).await,
        "channel" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Channel id (or `none` to stop)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:roles_channel_modal",
                "Assign Role panel channel",
                inputs,
            )
            .await
        }
        "add" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "role_id",
                "Role id to add to the catalog",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:roles_add_modal",
                "Add role to catalog",
                inputs,
            )
            .await
        }
        "wizard" => {
            let embed = embeds::brand("🧭 Notification Setup Wizard").description("Choose one or more game events, set shared options or times per event, preview the batch, then create the reminders together.");
            let events = [
                "Bear Trap",
                "Crazy Joe",
                "Mercenary Prestige",
                "Foundry Battle",
                "Canyon Clash",
                "Fortress Battle",
                "Frostfire Mine",
                "Castle Battle",
                "SvS",
                "Daily Reset",
                "Chief Order",
            ];
            let options = events
                .into_iter()
                .map(|event| {
                    serenity::CreateSelectMenuOption::new(
                        event,
                        event.to_ascii_lowercase().replace([' ', '-'], "_"),
                    )
                    .description("Scheduled game event reminder")
                })
                .collect();
            let menu = serenity::CreateSelectMenu::new(
                "settings:notifications:wizard_event",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Choose event types (multiple allowed)")
            .min_values(1)
            .max_values(11);
            reply(
                ctx,
                interaction,
                embed,
                vec![CreateActionRow::SelectMenu(menu)],
                true,
            )
            .await
        }
        "wizard_event" => {
            let events = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values.clone(),
                _ => Vec::new(),
            };
            if events.is_empty()
                || events.len() > 11
                || events
                    .iter()
                    .any(|event| !notification_wizard_event_known(event))
            {
                return Err(anyhow::anyhow!("choose one or more supported event types"));
            }
            let event_codes = events
                .iter()
                .filter_map(|event| notification_wizard_event_code(event))
                .collect::<Vec<_>>()
                .join(",");
            let mut event_hint = String::new();
            if events.iter().any(|event| event == "chief_order") {
                event_hint.push_str(
                    " Chief Order selection goes in Repeat as `chief_order=orders:double_time,crunch_rush`.",
                );
            }
            if events.iter().any(|event| event == "mercenary_prestige") {
                event_hint.push_str(
                    " Mercenary schedules go in Times as `mercenary_prestige=bosses:sat@14:30,sun@16:00` (up to five).",
                );
            }
            if events.iter().any(|event| event == "castle_battle") {
                event_hint.push_str(
                    " Castle phases go in Times as `castle_battle=phases:teleport_window,battle_start`.",
                );
            }
            if events.iter().any(|event| event == "svs") {
                event_hint.push_str(
                    " SvS phases go in Times as `svs=phases:borders_open,teleport_window,battle_start`.",
                );
            }
            if events.iter().any(|event| event == "bear_trap") {
                event_hint.push_str(
                    " Bear Trap needs two dated alerts; `DD/MM@HH:MM` rolls to the next future year, or use `DD/MM/YYYY@HH:MM`.",
                );
            }
            let embed = embeds::brand("📌 Select notification channel").description(format!(
                "Choose where reminders for these {} events should be posted. The next step accepts shared values or event=value;event=value. Times may include DD/MM@HH:MM or DD/MM/YYYY@HH:MM.{}",
                events.len(), event_hint
            ));
            let menu = serenity::CreateSelectMenu::new(
                format!("settings:notifications:wizard_channel:{event_codes}"),
                serenity::CreateSelectMenuKind::Channel {
                    channel_types: Some(vec![
                        serenity::ChannelType::Text,
                        serenity::ChannelType::News,
                    ]),
                    default_channels: None,
                },
            )
            .placeholder("Select the notification channel")
            .min_values(1)
            .max_values(1);
            reply(
                ctx,
                interaction,
                embed,
                vec![CreateActionRow::SelectMenu(menu)],
                true,
            )
            .await
        }
        action if action.starts_with("wizard_channel:") => {
            let event_codes = action.strip_prefix("wizard_channel:").unwrap_or_default();
            let events = notification_wizard_decode_events(event_codes)?;
            if events.is_empty() || events.len() > 11 {
                return Err(anyhow::anyhow!("select one or more events first"));
            }
            let channel = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::ChannelSelect { values } => {
                    values.first().copied()
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a text channel"))?;
            // Validate the selected channel before it becomes the batch target.
            let selected = ctx.http.get_channel(channel).await.ok();
            if !matches!(
                selected,
                Some(serenity::Channel::Guild(ref guild_channel))
                    if guild_channel.guild_id.get() == guild_id
                        && matches!(
                            guild_channel.kind,
                            serenity::ChannelType::Text
                                | serenity::ChannelType::News
                                | serenity::ChannelType::PublicThread
                                | serenity::ChannelType::PrivateThread
                                | serenity::ChannelType::NewsThread
                        )
            ) {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Invalid channel",
                        "Choose a text channel in this server that I can post in.",
                    ),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let setup_id = format!(
                "{:x}{:x}",
                chrono::Utc::now().timestamp_micros().unsigned_abs(),
                interaction.user.id.get() & 0xffff
            );
            let mut setup = crate::notifications::wizard::WizardSetup {
                id: setup_id,
                guild_id: guild_id,
                user_id: interaction.user.id.get(),
                channel_id: channel.get(),
                events: events.clone(),
                event_times: std::collections::HashMap::new(),
                event_repeats: std::collections::HashMap::new(),
                configured_events: std::collections::HashSet::new(),
                notification_type: None,
                custom_times: None,
                created: Instant::now(),
            };
            if events.iter().any(|event| event == "daily_reset") {
                setup
                    .event_times
                    .insert("daily_reset".into(), "00:00".into());
                setup.configured_events.insert("daily_reset".into());
            }
            crate::notifications::wizard::insert_setup(setup.clone());
            notification_wizard_setup_edit(ctx, interaction, &setup).await
        }
        action if action.starts_with("wizard_widget_open:") => {
            let (id, event_code) = action
                .strip_prefix("wizard_widget_open:")
                .unwrap_or_default()
                .split_once(':')
                .ok_or_else(|| anyhow::anyhow!("invalid notification wizard widget"))?;
            notification_wizard_widget_open(ctx, data, interaction, id, event_code).await
        }
        action if action.starts_with("wizard_widget_pick:") => {
            let mut parts = action
                .strip_prefix("wizard_widget_pick:")
                .unwrap_or_default()
                .splitn(3, ':');
            let id = parts.next().unwrap_or_default();
            let event_code = parts.next().unwrap_or_default();
            let field = parts.next();
            if id.is_empty() || event_code.is_empty() {
                return Err(anyhow::anyhow!("invalid notification wizard selection"));
            }
            notification_wizard_widget_pick(ctx, data, interaction, id, event_code, field).await
        }
        action if action.starts_with("wizard_widget_save:") => {
            let (id, event_code) = action
                .strip_prefix("wizard_widget_save:")
                .unwrap_or_default()
                .split_once(':')
                .ok_or_else(|| anyhow::anyhow!("invalid widget save"))?;
            notification_wizard_widget_save(ctx, data, interaction, id, event_code).await
        }
        action if action.starts_with("wizard_widget_toggle:") => {
            let mut parts = action
                .strip_prefix("wizard_widget_toggle:")
                .unwrap_or_default()
                .splitn(3, ':');
            let id = parts.next().unwrap_or_default();
            let event_code = parts.next().unwrap_or_default();
            let key = parts.next().unwrap_or_default();
            notification_wizard_widget_toggle(ctx, data, interaction, id, event_code, key).await
        }
        action if action.starts_with("wizard_widget_back:") => {
            notification_wizard_widget_back(
                ctx,
                data,
                interaction,
                action
                    .strip_prefix("wizard_widget_back:")
                    .unwrap_or_default(),
            )
            .await
        }
        action if action.starts_with("wizard_merc_action:") => {
            let (id, op) = action
                .strip_prefix("wizard_merc_action:")
                .unwrap_or_default()
                .split_once(':')
                .ok_or_else(|| anyhow::anyhow!("invalid Mercenary action"))?;
            notification_wizard_mercenary_action(ctx, data, interaction, id, op).await
        }
        action if action.starts_with("wizard_bear_repeat:") => {
            let (id, op) = action
                .strip_prefix("wizard_bear_repeat:")
                .unwrap_or_default()
                .split_once(':')
                .ok_or_else(|| anyhow::anyhow!("invalid Bear Trap repeat action"))?;
            notification_wizard_bear_repeat(ctx, data, interaction, id, op).await
        }
        action if action.starts_with("wizard_slots:") => {
            notification_wizard_slots(
                ctx,
                data,
                interaction,
                action.strip_prefix("wizard_slots:").unwrap_or_default(),
            )
            .await
        }
        action if action.starts_with("wizard_slot_set:") => {
            let mut parts = action
                .strip_prefix("wizard_slot_set:")
                .unwrap_or_default()
                .splitn(2, ':');
            let id = parts.next().unwrap_or_default();
            let value = parts.next().unwrap_or_default();
            notification_wizard_slot_set(ctx, data, interaction, id, value).await
        }
        action if action.starts_with("wizard_widget_continue:") => {
            notification_wizard_widget_continue(
                ctx,
                data,
                interaction,
                action
                    .strip_prefix("wizard_widget_continue:")
                    .unwrap_or_default(),
            )
            .await
        }
        action if action.starts_with("wizard_widget_cancel:") => {
            let id = action
                .strip_prefix("wizard_widget_cancel:")
                .unwrap_or_default();
            let guild = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
            crate::notifications::wizard::remove_setup(id, interaction.user.id.get(), guild);
            reply(
                ctx,
                interaction,
                embeds::ok("Notification setup cancelled."),
                Vec::new(),
                true,
            )
            .await
        }
        action if action.starts_with("wizard_create:") => {
            notifications_wizard_create(
                ctx,
                data,
                interaction,
                action.strip_prefix("wizard_create:").unwrap_or_default(),
            )
            .await
        }
        action if action.starts_with("wizard_cancel:") => {
            let id = action.strip_prefix("wizard_cancel:").unwrap_or_default();
            let guild = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
            if !crate::notifications::wizard::remove(id, interaction.user.id.get(), guild) {
                return Err(anyhow::anyhow!(
                    "wizard preview expired or belongs to another administrator"
                ));
            }
            reply(
                ctx,
                interaction,
                embeds::ok("Notification wizard cancelled."),
                Vec::new(),
                true,
            )
            .await
        }
        "remove" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "role_id",
                "Role id to remove (also drops its grants)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:roles_remove_modal",
                "Remove role from catalog",
                inputs,
            )
            .await
        }
        "grant_user" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short("user_id", "User id")),
                CreateActionRow::InputText(components::short(
                    "role_id",
                    "Catalog role id to let them assign",
                )),
            ];
            send_modal(
                ctx,
                interaction,
                "settings:roles_grant_user_modal",
                "Grant user",
                inputs,
            )
            .await
        }
        "grant_role" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short(
                    "granter_role_id",
                    "Discord role id (holders can assign)",
                )),
                CreateActionRow::InputText(components::short(
                    "role_id",
                    "Catalog role id to let them assign",
                )),
            ];
            send_modal(
                ctx,
                interaction,
                "settings:roles_grant_role_modal",
                "Grant role",
                inputs,
            )
            .await
        }
        "revoke_user" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short("user_id", "User id")),
                CreateActionRow::InputText(components::short(
                    "role_id",
                    "Catalog role id to revoke",
                )),
            ];
            send_modal(
                ctx,
                interaction,
                "settings:roles_revoke_user_modal",
                "Revoke user",
                inputs,
            )
            .await
        }
        "revoke_role" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short("granter_role_id", "Discord role id")),
                CreateActionRow::InputText(components::short(
                    "role_id",
                    "Catalog role id to revoke",
                )),
            ];
            send_modal(
                ctx,
                interaction,
                "settings:roles_revoke_role_modal",
                "Revoke role",
                inputs,
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown roles action `{other}`")),
    }
}

// ------------------------------------------------------ notifications panel

async fn render_notifications(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let notifications = db::notifications::list_for_guild(&data.db, guild_id).await?;
    let total = notifications.len() as i64;
    let lines: Vec<String> = notifications
        .iter()
        .take(10)
        .map(crate::notifications::describe)
        .collect();
    let default_slots =
        db::settings::get(&data.db, guild_id, db::settings::keys::NOTIF_DEFAULT_SLOTS)
            .await
            .ok()
            .flatten()
            .and_then(|v| v.parse::<i64>().ok())
            .unwrap_or(2)
            .clamp(1, 5);
    let view = panels::NotificationsView {
        lines,
        default_slots,
        total,
    };
    let (embed, rows) = panels::notifications_panel(&view);
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn render_notification_manager(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    page: usize,
) -> anyhow::Result<()> {
    let notifications = db::notifications::list_for_guild(&data.db, guild_id).await?;
    let pages = notifications.len().max(1).div_ceil(25);
    let page = page.min(pages.saturating_sub(1));
    let lines = notifications
        .iter()
        .skip(page * 25)
        .take(25)
        .map(|notification| {
            format!(
                "• **#{}** {}{} — <#{}> — {}",
                notification.id,
                if notification.enabled() {
                    "🟢 "
                } else {
                    "🔴 "
                },
                notification
                    .description
                    .chars()
                    .take(90)
                    .collect::<String>(),
                notification.channel_id,
                notification
                    .next_notification
                    .as_deref()
                    .unwrap_or("not scheduled")
            )
        })
        .collect::<Vec<_>>();
    let embed = embeds::brand("🔔 Manage Notifications").description(if notifications.is_empty() {
        "_No notifications configured._".to_string()
    } else {
        format!("Page {}/{}\n{}", page + 1, pages, lines.join("\n"))
    });
    let options = notifications
        .iter()
        .skip(page * 25)
        .take(25)
        .map(|item| {
            serenity::CreateSelectMenuOption::new(
                format!("#{} · {}", item.id, item.description)
                    .chars()
                    .take(100)
                    .collect::<String>(),
                item.id.to_string(),
            )
            .description(format!(
                "{} · <#{}>",
                if item.enabled() {
                    "Enabled"
                } else {
                    "Disabled"
                },
                item.channel_id
            ))
        })
        .collect();
    let mut rows = Vec::new();
    if !notifications.is_empty() {
        rows.push(CreateActionRow::SelectMenu(
            serenity::CreateSelectMenu::new(
                "settings:notifications:manage_select",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Choose a notification")
            .min_values(1)
            .max_values(1),
        ));
    }
    let mut nav = Vec::new();
    if page > 0 {
        nav.push(components::secondary(
            format!("settings:notifications:manage_page:{}", page - 1),
            "◀️ Previous",
        ));
    }
    nav.push(components::secondary(
        "settings:notifications:refresh",
        "Main Panel",
    ));
    if page + 1 < pages {
        nav.push(components::secondary(
            format!("settings:notifications:manage_page:{}", page + 1),
            "Next ▶️",
        ));
    }
    rows.push(CreateActionRow::Buttons(nav));
    update_panel(ctx, data, interaction, embed, rows).await
}

const NOTIFICATION_EVENTS: &[(&str, &str)] = &[
    ("bear_trap", "Bear Trap"),
    ("crazy_joe", "Crazy Joe"),
    ("mercenary_prestige", "Mercenary Prestige"),
    ("foundry_battle", "Foundry Battle"),
    ("canyon_clash", "Canyon Clash"),
    ("fortress_battle", "Fortress Battle"),
    ("frostfire_mine", "Frostfire Mine"),
    ("castle_battle", "Castle Battle"),
    ("svs", "SvS"),
    ("daily_reset", "Daily Reset"),
    ("chief_order", "Chief Order"),
];

async fn notification_template_page(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    event: Option<&str>,
) -> anyhow::Result<()> {
    let Some(event) = event else {
        let options = NOTIFICATION_EVENTS
            .iter()
            .map(|(key, name)| serenity::CreateSelectMenuOption::new(*name, *key))
            .collect();
        let menu = serenity::CreateSelectMenu::new(
            "settings:notifications:template_pick",
            serenity::CreateSelectMenuKind::String { options },
        )
        .placeholder("Choose an event template")
        .min_values(1)
        .max_values(1);
        return reply(
            ctx,
            interaction,
            embeds::brand("🎨 Notification event templates").description(
                "Choose an event to preview, edit, or reset its default embed template.",
            ),
            vec![
                CreateActionRow::SelectMenu(menu),
                CreateActionRow::Buttons(vec![components::secondary(
                    "settings:notifications:refresh",
                    "Back",
                )]),
            ],
            true,
        )
        .await;
    };
    let name = NOTIFICATION_EVENTS
        .iter()
        .find(|(key, _)| *key == event)
        .map(|(_, name)| *name)
        .ok_or_else(|| anyhow::anyhow!("unknown notification event"))?;
    let template = db::notifications::event_template(&data.db, event).await?;
    let title = template
        .as_ref()
        .and_then(|t| t.embed_title.as_deref())
        .filter(|s| !s.is_empty())
        .unwrap_or(name);
    let description = template
        .as_ref()
        .and_then(|t| t.embed_description.as_deref())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| notification_event_default(event));
    let preview = description
        .replace("%t", "10 minutes")
        .replace("%e", notification_event_emoji(event))
        .replace("%n", name);
    let embed = embeds::brand(format!("🎨 {name} template")).description(format!(
        "**{}**\n\n{}\n\n{}",
        if template.is_some() {
            "Customized"
        } else {
            "Built-in default"
        },
        title,
        preview
    ));
    let rows = vec![
        CreateActionRow::Buttons(vec![
            components::primary(
                format!("settings:notifications:template_edit:{event}"),
                "Edit title and description",
            ),
            components::danger(
                format!("settings:notifications:template_reset:{event}"),
                "Reset to default",
            ),
        ]),
        CreateActionRow::Buttons(vec![
            components::secondary("settings:notifications:templates", "Back to events"),
            components::secondary("settings:notifications:refresh", "Main panel"),
        ]),
        CreateActionRow::SelectMenu(
            serenity::CreateSelectMenu::new(
                format!("settings:notifications:template_field_pick:{event}"),
                serenity::CreateSelectMenuKind::String {
                    options: [
                        ("color", "Color"),
                        ("footer", "Footer"),
                        ("author", "Author"),
                        ("mention_message", "Mention message"),
                        ("image_url", "Image URL"),
                        ("thumbnail_url", "Thumbnail URL"),
                        ("images", "Extra images"),
                    ]
                    .into_iter()
                    .map(|(key, label)| serenity::CreateSelectMenuOption::new(label, key))
                    .collect(),
                },
            )
            .placeholder("Edit other embed fields")
            .min_values(1)
            .max_values(1),
        ),
    ];
    reply(ctx, interaction, embed, rows, true).await
}

async fn notifications_panel_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    sub: &str,
    guild_id: u64,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    match sub {
        "" | "refresh" => render_notifications(ctx, data, interaction, guild_id).await,
        "add" => {
            let menu = serenity::CreateSelectMenu::new(
                "settings:notifications:add_channel",
                serenity::CreateSelectMenuKind::Channel {
                    channel_types: Some(vec![
                        serenity::ChannelType::Text,
                        serenity::ChannelType::News,
                    ]),
                    default_channels: None,
                },
            )
            .placeholder("Choose where notifications will be posted")
            .min_values(1)
            .max_values(1);
            reply(
                ctx,
                interaction,
                embeds::brand("📌 Notification channel")
                    .description("Select the channel that should receive this reminder."),
                vec![CreateActionRow::SelectMenu(menu)],
                true,
            )
            .await
        }
        "add_channel" => {
            let channel = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::ChannelSelect { values } => {
                    values.first().copied()
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a notification channel"))?;
            let selected = ctx.http.get_channel(channel).await?;
            if !matches!(selected, serenity::Channel::Guild(ref g) if g.guild_id.get() == guild_id && matches!(g.kind, serenity::ChannelType::Text | serenity::ChannelType::News))
            {
                return Err(anyhow::anyhow!(
                    "choose a text or announcement channel in this server"
                ));
            }
            reply(
                ctx,
                interaction,
                embeds::brand("✉️ Notification message type").description(
                    "Choose whether this reminder should be sent as a plain message or an embed.",
                ),
                vec![CreateActionRow::Buttons(vec![
                    components::primary(
                        format!("settings:notifications:add_type:{}:plain", channel.get()),
                        "Plain message",
                    ),
                    components::secondary(
                        format!("settings:notifications:add_type:{}:embed", channel.get()),
                        "Embed message",
                    ),
                ])],
                true,
            )
            .await
        }
        action if action.starts_with("add_type:") => {
            let rest = action.strip_prefix("add_type:").unwrap_or_default();
            let (raw_channel, message_type) = rest
                .split_once(':')
                .ok_or_else(|| anyhow::anyhow!("choose a message type"))?;
            let channel_id = raw_channel.parse::<u64>()?;
            if !matches!(message_type, "plain" | "embed") {
                return Err(anyhow::anyhow!("choose plain or embed message"));
            }
            reply(ctx, interaction, embeds::brand("⏱️ Reminder schedule")
                .description("Choose the reminder slots before the event. These match the existing five schedule presets."), vec![
                    CreateActionRow::Buttons(vec![
                        components::secondary(format!("settings:notifications:add_slots:{channel_id}:{message_type}:1"), "30m, 10m, 5m, at time"),
                        components::secondary(format!("settings:notifications:add_slots:{channel_id}:{message_type}:2"), "10m, 5m, at time"),
                        components::secondary(format!("settings:notifications:add_slots:{channel_id}:{message_type}:3"), "5m, at time"),
                        components::secondary(format!("settings:notifications:add_slots:{channel_id}:{message_type}:4"), "5m only"),
                        components::secondary(format!("settings:notifications:add_slots:{channel_id}:{message_type}:5"), "At event time"),
                    ]),
                    CreateActionRow::Buttons(vec![components::primary(format!("settings:notifications:add_slots:{channel_id}:{message_type}:custom"), "Custom minute offsets")]),
                ], true).await
        }
        action if action.starts_with("add_slots:") => {
            let mut parts = action
                .strip_prefix("add_slots:")
                .unwrap_or_default()
                .splitn(3, ':');
            let channel_id = parts.next().unwrap_or_default().parse::<u64>()?;
            let kind = parts.next().unwrap_or_default();
            let slots_raw = parts.next().unwrap_or_default();
            let slots = if slots_raw == "custom" {
                6
            } else {
                slots_raw.parse::<i64>()?
            };
            if !matches!(kind, "plain" | "embed") || !(1..=6).contains(&slots) {
                return Err(anyhow::anyhow!("invalid reminder preset"));
            }
            reply(ctx, interaction, embeds::brand("🔔 Notification mention").description("Choose no mention, @here, @everyone, a role, or a member."), vec![
                CreateActionRow::Buttons(vec![
                    components::secondary(format!("settings:notifications:add_mention:{channel_id}:{kind}:{slots}:none"), "No mention"),
                    components::secondary(format!("settings:notifications:add_mention:{channel_id}:{kind}:{slots}:here"), "@here"),
                    components::secondary(format!("settings:notifications:add_mention:{channel_id}:{kind}:{slots}:everyone"), "@everyone"),
                ]),
                CreateActionRow::Buttons(vec![
                    components::primary(format!("settings:notifications:add_role:{channel_id}:{kind}:{slots}"), "Choose role"),
                    components::primary(format!("settings:notifications:add_member:{channel_id}:{kind}:{slots}"), "Choose member"),
                ]),
            ], true).await
        }
        action if action.starts_with("add_mention:") => {
            let mut parts = action
                .strip_prefix("add_mention:")
                .unwrap_or_default()
                .splitn(4, ':');
            let channel_id = parts.next().unwrap_or_default().parse::<u64>()?;
            let message_type = parts.next().unwrap_or_default();
            let slots = parts.next().unwrap_or_default().parse::<i64>()?;
            let mention = parts.next().unwrap_or_default();
            if !matches!(message_type, "plain" | "embed")
                || !(1..=6).contains(&slots)
                || !matches!(mention, "none" | "here" | "everyone")
            {
                return Err(anyhow::anyhow!("invalid notification mention choice"));
            }
            notifications_add_details_modal(
                ctx,
                interaction,
                channel_id,
                message_type,
                slots,
                mention,
            )
            .await
        }
        action if action.starts_with("add_role:") || action.starts_with("add_member:") => {
            let is_role = action.starts_with("add_role:");
            let rest = action
                .split_once(':')
                .map(|(_, value)| value)
                .unwrap_or_default();
            let rest = rest.splitn(3, ':').collect::<Vec<_>>();
            let channel = *rest.first().unwrap_or(&"");
            let kind = *rest.get(1).unwrap_or(&"");
            let slots = *rest.get(2).unwrap_or(&"");
            let channel_id = channel.parse::<u64>()?;
            if !matches!(kind, "plain" | "embed") || !(1..=6).contains(&slots.parse::<i64>()?) {
                return Err(anyhow::anyhow!("invalid notification type"));
            }
            let (custom_id, select_kind, placeholder) = if is_role {
                (
                    format!("settings:notifications:add_pick_role:{channel_id}:{kind}:{slots}"),
                    serenity::CreateSelectMenuKind::Role {
                        default_roles: None,
                    },
                    "Select a role",
                )
            } else {
                (
                    format!("settings:notifications:add_pick_member:{channel_id}:{kind}:{slots}"),
                    serenity::CreateSelectMenuKind::User {
                        default_users: None,
                    },
                    "Select a member",
                )
            };
            let menu = serenity::CreateSelectMenu::new(custom_id, select_kind)
                .placeholder(placeholder)
                .min_values(1)
                .max_values(1);
            reply(
                ctx,
                interaction,
                embeds::brand("🔔 Choose mention target"),
                vec![CreateActionRow::SelectMenu(menu)],
                true,
            )
            .await
        }
        action
            if action.starts_with("add_pick_role:") || action.starts_with("add_pick_member:") =>
        {
            let is_role = action.starts_with("add_pick_role:");
            let rest = action
                .split_once(':')
                .map(|(_, value)| value)
                .unwrap_or_default();
            let rest = rest.splitn(3, ':').collect::<Vec<_>>();
            let channel = *rest.first().unwrap_or(&"");
            let kind = *rest.get(1).unwrap_or(&"");
            let slots = *rest.get(2).unwrap_or(&"");
            let channel_id = channel.parse::<u64>()?;
            if !matches!(kind, "plain" | "embed") || !(1..=6).contains(&slots.parse::<i64>()?) {
                return Err(anyhow::anyhow!("invalid notification type"));
            }
            let value = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::RoleSelect { values } => {
                    values.first().map(|v| v.get())
                }
                serenity::ComponentInteractionDataKind::UserSelect { values } => {
                    values.first().map(|v| v.get())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a mention target"))?;
            let mention = format!("{}{}", if is_role { "role_" } else { "member_" }, value);
            notifications_add_details_modal(
                ctx,
                interaction,
                channel_id,
                kind,
                slots.parse()?,
                &mention,
            )
            .await
        }
        "manage" => render_notification_manager(ctx, data, interaction, guild_id, 0).await,
        action if action.starts_with("manage_page:") => {
            let page = action
                .split_once(':')
                .and_then(|(_, value)| value.parse::<usize>().ok())
                .unwrap_or(0);
            render_notification_manager(ctx, data, interaction, guild_id, page).await
        }
        "manage_select" => {
            let id = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().and_then(|v| v.parse::<i64>().ok())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a notification"))?;
            let item = db::notifications::list_for_guild(&data.db, guild_id)
                .await?
                .into_iter()
                .find(|item| item.id == id)
                .ok_or_else(|| anyhow::anyhow!("notification not found in this server"))?;
            let repeat_summary = if item.repeat_minutes == Some(-1) {
                let selected = db::notifications::weekdays(&data.db, id).await?;
                let names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
                format!(
                    "Weekly ({})",
                    selected
                        .iter()
                        .filter_map(|day| names.get(*day as usize))
                        .copied()
                        .collect::<Vec<_>>()
                        .join(", ")
                )
            } else if item.repeat_enabled == 1 {
                format!(
                    "Every {} minute(s)",
                    item.repeat_minutes.unwrap_or_default()
                )
            } else {
                "One-shot".to_string()
            };
            let embed = embeds::brand(format!("🔔 Notification #{}", id)).description(format!(
                "**Message:** {}\n**Channel:** <#{}>\n**Next:** {}\n**Repeat:** {}\n**Status:** {}",
                item.description,
                item.channel_id,
                item.next_notification.as_deref().unwrap_or("not scheduled"),
                repeat_summary,
                if item.enabled() {
                    "Enabled"
                } else {
                    "Disabled"
                }
            ));
            let rows = vec![CreateActionRow::Buttons(vec![
                components::primary(
                    format!("settings:notifications:manage_toggle:{id}"),
                    if item.enabled() {
                        "Turn off"
                    } else {
                        "Turn on"
                    },
                ),
                components::danger(
                    format!("settings:notifications:manage_delete:{id}"),
                    "Delete",
                ),
                components::secondary("settings:notifications:manage", "◀️ List"),
            ])];
            reply(ctx, interaction, embed, rows, true).await
        }
        action if action.starts_with("manage_toggle:") || action.starts_with("manage_delete:") => {
            let (kind, raw_id) = action
                .split_once(':')
                .ok_or_else(|| anyhow::anyhow!("invalid notification action"))?;
            let id = raw_id.parse::<i64>()?;
            let item = db::notifications::list_for_guild(&data.db, guild_id)
                .await?
                .into_iter()
                .find(|item| item.id == id)
                .ok_or_else(|| anyhow::anyhow!("notification not found in this server"))?;
            if kind == "manage_toggle" {
                db::notifications::set_enabled(&data.db, id, !item.enabled()).await?;
            } else {
                db::notifications::delete(&data.db, id).await?;
            }
            render_notifications(ctx, data, interaction, guild_id).await
        }
        "slots" => {
            let current =
                db::settings::get(&data.db, guild_id, db::settings::keys::NOTIF_DEFAULT_SLOTS)
                    .await
                    .ok()
                    .flatten()
                    .and_then(|v| v.parse::<i64>().ok())
                    .unwrap_or(2)
                    .clamp(1, 5);
            let next = current % 5 + 1;
            db::settings::set(
                &data.db,
                guild_id,
                db::settings::keys::NOTIF_DEFAULT_SLOTS,
                Some(&next.to_string()),
            )
            .await?;
            render_notifications(ctx, data, interaction, guild_id).await
        }
        "auto_delete" => {
            let settings = db::notifications::guild_settings(&data.db, guild_id).await?;
            let embed = embeds::brand("🔔 Notification deletion settings").description(format!(
                "**Auto-delete:** {}\n**Default delay:** {} minutes\n\nAn individual notification delay overrides this guild default.",
                if settings.delete_enabled { "Enabled" } else { "Disabled" },
                settings.default_delete_delay_minutes
            ));
            reply(
                ctx,
                interaction,
                embed,
                vec![CreateActionRow::Buttons(vec![
                    components::primary(
                        "settings:notifications:auto_delete_toggle",
                        if settings.delete_enabled {
                            "Disable auto-delete"
                        } else {
                            "Enable auto-delete"
                        },
                    ),
                    components::secondary(
                        "settings:notifications:auto_delete_delay",
                        "Set default delay",
                    ),
                    components::secondary("settings:notifications:refresh", "Back"),
                ])],
                true,
            )
            .await
        }
        "templates" => notification_template_page(ctx, data, interaction, None).await,
        "template_pick" => {
            let event = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().map(String::as_str)
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose an event template"))?;
            notification_template_page(ctx, data, interaction, Some(event)).await
        }
        action if action.starts_with("template_edit:") => {
            let event = action.strip_prefix("template_edit:").unwrap_or_default();
            let name = NOTIFICATION_EVENTS
                .iter()
                .find(|(key, _)| *key == event)
                .map(|(_, name)| *name)
                .ok_or_else(|| anyhow::anyhow!("unknown event template"))?;
            let template = db::notifications::event_template(&data.db, event).await?;
            let title = template
                .as_ref()
                .and_then(|t| t.embed_title.as_deref())
                .filter(|v| !v.is_empty())
                .map(str::to_owned)
                .unwrap_or_else(|| name.to_string());
            let description = template
                .as_ref()
                .and_then(|t| t.embed_description.as_deref())
                .filter(|v| !v.is_empty())
                .map(str::to_owned)
                .unwrap_or_else(|| notification_event_default(event).to_string());
            let inputs = vec![
                CreateActionRow::InputText(
                    components::short("title", "Embed title")
                        .value(title)
                        .max_length(256),
                ),
                CreateActionRow::InputText(
                    components::paragraph("description", "Text; placeholders %t, %e, %n")
                        .value(description)
                        .max_length(3800),
                ),
            ];
            let modal_id = format!("settings:notifications_template_modal:{event}");
            send_modal(
                ctx,
                interaction,
                &modal_id,
                "Edit notification template",
                inputs,
            )
            .await
        }
        action if action.starts_with("template_field_pick:") => {
            let event = action
                .strip_prefix("template_field_pick:")
                .unwrap_or_default();
            if !NOTIFICATION_EVENTS.iter().any(|(key, _)| *key == event) {
                return Err(anyhow::anyhow!("unknown event template"));
            }
            let field = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().map(String::as_str)
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a template field"))?;
            let template = db::notifications::event_template(&data.db, event).await?;
            let current = template
                .as_ref()
                .map(|t| match field {
                    "color" => t.embed_color.clone(),
                    "footer" => t.footer.clone(),
                    "author" => t.author.clone(),
                    "mention_message" => t.mention_message.clone(),
                    "image_url" => t.embed_image_url.clone(),
                    "thumbnail_url" => t.embed_thumbnail_url.clone(),
                    "images" => t.embed_images.clone(),
                    _ => None,
                })
                .flatten()
                .unwrap_or_default();
            let (label, paragraph, max) = match field {
                "color" => ("Color (hex, e.g. 3498db)", false, 32),
                "footer" => ("Footer text", false, 2048),
                "author" => ("Author name", false, 256),
                "mention_message" => ("Message content (mention text)", true, 2000),
                "image_url" => ("Image URL", false, 1000),
                "thumbnail_url" => ("Thumbnail URL", false, 1000),
                "images" => ("Extra image URLs, one per line", true, 1500),
                _ => return Err(anyhow::anyhow!("unknown template field")),
            };
            let mut input = if paragraph {
                components::paragraph("value", label)
            } else {
                components::short("value", label)
            };
            input = input.max_length(max).required(false);
            if !current.is_empty() {
                input = input.value(current);
            }
            send_modal(
                ctx,
                interaction,
                &format!("settings:notifications_rich_template_modal:{event}:{field}"),
                "Edit notification field",
                vec![CreateActionRow::InputText(input)],
            )
            .await
        }
        action if action.starts_with("template_reset:") => {
            let event = action.strip_prefix("template_reset:").unwrap_or_default();
            if !NOTIFICATION_EVENTS.iter().any(|(key, _)| *key == event) {
                return Err(anyhow::anyhow!("unknown event template"));
            }
            db::notifications::reset_event_template(&data.db, event).await?;
            notification_template_page(ctx, data, interaction, Some(event)).await
        }
        "auto_delete_toggle" => {
            let settings = db::notifications::guild_settings(&data.db, guild_id).await?;
            db::notifications::set_auto_delete(&data.db, guild_id, !settings.delete_enabled)
                .await?;
            let settings = db::notifications::guild_settings(&data.db, guild_id).await?;
            let embed = embeds::brand("🔔 Notification deletion settings").description(format!(
                "**Auto-delete:** {}\n**Default delay:** {} minutes\n\nAn individual notification delay overrides this guild default.",
                if settings.delete_enabled { "Enabled" } else { "Disabled" },
                settings.default_delete_delay_minutes
            ));
            reply(
                ctx,
                interaction,
                embed,
                vec![CreateActionRow::Buttons(vec![
                    components::primary(
                        "settings:notifications:auto_delete_toggle",
                        if settings.delete_enabled {
                            "Disable auto-delete"
                        } else {
                            "Enable auto-delete"
                        },
                    ),
                    components::secondary(
                        "settings:notifications:auto_delete_delay",
                        "Set default delay",
                    ),
                    components::secondary("settings:notifications:refresh", "Back"),
                ])],
                true,
            )
            .await
        }
        "auto_delete_delay" => {
            let settings = db::notifications::guild_settings(&data.db, guild_id).await?;
            let input = components::short("minutes", "Delay in minutes (1–43,200)")
                .value(settings.default_delete_delay_minutes.to_string());
            send_modal(
                ctx,
                interaction,
                "settings:notifications_delete_delay_modal",
                "Default delete delay",
                vec![CreateActionRow::InputText(input)],
            )
            .await
        }
        "toggle" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "id",
                "Notification id (from the list)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:notifications_toggle_modal",
                "Toggle notification",
                inputs,
            )
            .await
        }
        "delete" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "id",
                "Notification id (from the list)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:notifications_delete_modal",
                "Delete notification",
                inputs,
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown notifications action `{other}`")),
    }
}

fn notification_wizard_setup_embed(
    setup: &crate::notifications::wizard::WizardSetup,
) -> CreateEmbed {
    let mut lines = Vec::new();
    for event in &setup.events {
        let label = event.replace('_', " ");
        let status = if setup.configured_events.contains(event) {
            "✅ Configured"
        } else {
            "⚠️ Required"
        };
        lines.push(format!("• **{label}** — {status}"));
    }
    let slots = match setup.notification_type {
        Some(6) => format!("Custom: {}", setup.custom_times.as_deref().unwrap_or("")),
        Some(1) => "30m, 10m, 5m & event time".to_string(),
        Some(2) => "10m, 5m & event time".to_string(),
        Some(3) => "5m & event time".to_string(),
        Some(4) => "Only 5m".to_string(),
        Some(5) => "Only event time".to_string(),
        _ => "Default (10m, 5m, event time)".to_string(),
    };
    embeds::brand("🧭 Configure notification events")
        .description(format!(
            "**Channel:** <#{}>\n**Reminder Times:** {}\nChoose each event to configure its times, phases, days, or sub-orders. Then continue to set timezone, mentions, and reminder slots.\n\n{}",
            setup.channel_id,
            slots,
            lines.join("\n")
        ))
}

fn notification_wizard_setup_rows(
    setup: &crate::notifications::wizard::WizardSetup,
) -> Vec<CreateActionRow> {
    let buttons = setup
        .events
        .iter()
        .filter_map(|event| {
            let code = notification_wizard_event_code(event)?;
            let label = event.replace('_', " ");
            let button = components::primary(
                format!(
                    "settings:notifications:wizard_widget_open:{}:{code}",
                    setup.id
                ),
                label,
            );
            Some(if setup.configured_events.contains(event) {
                button.style(serenity::ButtonStyle::Success)
            } else {
                button
            })
        })
        .collect::<Vec<_>>();
    let mut rows = buttons
        .chunks(5)
        .map(|chunk| CreateActionRow::Buttons(chunk.to_vec()))
        .collect::<Vec<_>>();
    rows.push(CreateActionRow::Buttons(vec![
        components::secondary(
            format!("settings:notifications:wizard_slots:{}", setup.id),
            "Reminder Times",
        ),
        components::success(
            format!("settings:notifications:wizard_widget_continue:{}", setup.id),
            "Continue to Settings",
        ),
        components::danger(
            format!("settings:notifications:wizard_widget_cancel:{}", setup.id),
            "Cancel",
        ),
    ]));
    rows
}

async fn notification_wizard_slots(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    let current = match setup.notification_type {
        Some(6) => format!(
            "Custom: {} minutes",
            setup.custom_times.as_deref().unwrap_or("")
        ),
        Some(1) => "30m, 10m, 5m & event time".to_string(),
        Some(2) => "10m, 5m & event time".to_string(),
        Some(3) => "5m & event time".to_string(),
        Some(4) => "Only 5m".to_string(),
        Some(5) => "Only event time".to_string(),
        _ => "Default: 10m, 5m & event time".to_string(),
    };
    let rows = vec![
        CreateActionRow::Buttons(vec![
            components::primary(
                format!("settings:notifications:wizard_slot_set:{setup_id}:1"),
                "30m, 10m, 5m & Time",
            ),
            components::primary(
                format!("settings:notifications:wizard_slot_set:{setup_id}:2"),
                "10m, 5m & Time",
            ),
        ]),
        CreateActionRow::Buttons(vec![
            components::primary(
                format!("settings:notifications:wizard_slot_set:{setup_id}:3"),
                "5m & Time",
            ),
            components::primary(
                format!("settings:notifications:wizard_slot_set:{setup_id}:4"),
                "Only 5m",
            ),
            components::primary(
                format!("settings:notifications:wizard_slot_set:{setup_id}:5"),
                "Only Time",
            ),
        ]),
        CreateActionRow::Buttons(vec![
            components::success(
                format!("settings:notifications:wizard_slot_set:{setup_id}:custom"),
                "Custom Times",
            ),
            components::secondary(
                format!("settings:notifications:wizard_widget_back:{setup_id}"),
                "Back",
            ),
        ]),
    ];
    interaction
        .create_response(
            &ctx.http,
            update(
                embeds::brand("⏰ Select Notification Times").description(format!(
                    "Choose reminder offsets before each event.\n**Current:** {current}"
                )),
                rows,
            ),
        )
        .await?;
    Ok(())
}

async fn notification_wizard_slot_set(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
    value: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    if value == "custom" {
        let inputs = vec![CreateActionRow::InputText(
            components::short("times", "Descending minute offsets (e.g. 60-20-15-4-0)")
                .max_length(50),
        )];
        return send_modal(
            ctx,
            interaction,
            &format!("settings:notifications_wizard_custom_times:{setup_id}"),
            "Set Custom Notification Times",
            inputs,
        )
        .await;
    }
    let kind = value.parse::<i64>()?;
    if !(1..=5).contains(&kind) {
        return Err(anyhow::anyhow!("invalid reminder preset"));
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(mut setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    setup.notification_type = Some(kind);
    setup.custom_times = None;
    crate::notifications::wizard::insert_setup(setup.clone());
    notification_wizard_setup_edit(ctx, interaction, &setup).await
}

async fn notification_wizard_custom_times_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
    setup_id: &str,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let raw = trimmed(interaction, "times").unwrap_or_default();
    let values = raw
        .split('-')
        .map(str::trim)
        .map(str::parse::<i64>)
        .collect::<Result<Vec<_>, _>>();
    let valid = values.as_ref().is_ok_and(|v| {
        !v.is_empty() && v.iter().all(|n| *n >= 0) && v.windows(2).all(|p| p[0] > p[1])
    });
    if !valid {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn(
                "Invalid reminder times",
                "Use descending non-negative minute offsets, such as `60-20-15-4-0`.",
            ),
        )
        .await;
    }
    let guild_id = guild_of(interaction)?;
    let Some(mut setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
        )
        .await;
    };
    setup.notification_type = Some(6);
    setup.custom_times = Some(raw);
    crate::notifications::wizard::insert_setup(setup.clone());
    notification_wizard_setup_edit_modal(ctx, interaction, &setup).await
}

