async fn notification_wizard_widget_open(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
    event_code: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    let events = notification_wizard_decode_events(event_code)?;
    let event = events
        .first()
        .ok_or_else(|| anyhow::anyhow!("invalid notification event"))?;
    if !setup.events.contains(event) {
        return Err(anyhow::anyhow!("event is not part of this wizard"));
    }
    if event == "castle_battle" || event == "svs" || event == "chief_order" {
        let (choices, _, description) = notification_wizard_widget_choices(event)
            .ok_or_else(|| anyhow::anyhow!("event has no toggle options"))?;
        let current_raw = if event == "chief_order" {
            setup
                .event_repeats
                .get(event)
                .and_then(|raw| raw.strip_prefix("orders:"))
        } else {
            setup
                .event_times
                .get(event)
                .and_then(|raw| raw.strip_prefix("phases:"))
        }
        .unwrap_or_default();
        let selected = current_raw
            .split(',')
            .collect::<std::collections::HashSet<_>>();
        let toggles = choices
            .iter()
            .map(|(label, key)| {
                let id = format!(
                    "settings:notifications:wizard_widget_toggle:{setup_id}:{event_code}:{key}"
                );
                let button = components::secondary(id, *label);
                if selected.contains(key) {
                    button.style(serenity::ButtonStyle::Success)
                } else {
                    button
                }
            })
            .collect::<Vec<_>>();
        let mut rows = toggles
            .chunks(4)
            .map(|chunk| CreateActionRow::Buttons(chunk.to_vec()))
            .collect::<Vec<_>>();
        rows.push(CreateActionRow::Buttons(vec![
            components::success(
                format!("settings:notifications:wizard_widget_save:{setup_id}:{event_code}"),
                "Save",
            ),
            components::secondary(
                format!("settings:notifications:wizard_widget_back:{setup_id}"),
                "Back",
            ),
        ]));
        interaction
            .create_response(
                &ctx.http,
                update(
                    embeds::brand(format!("Configure {}", event.replace('_', " ")))
                        .description(description),
                    rows,
                ),
            )
            .await?;
        return Ok(());
    }
    if let Some((choices, max_values, description)) = notification_wizard_widget_choices(event) {
        if event == "foundry_battle" || event == "canyon_clash" {
            let make_menu = |field: &str, placeholder: &str, min_values: u8| {
                let selected = setup
                    .event_times
                    .get(&format!("{event}__{field}"))
                    .map(String::as_str)
                    .unwrap_or_default();
                let options = choices
                    .iter()
                    .map(|(label, value)| {
                        serenity::CreateSelectMenuOption::new(*label, *value)
                            .default_selection(*value == selected)
                    })
                    .collect();
                serenity::CreateSelectMenu::new(
                    format!(
                        "settings:notifications:wizard_widget_pick:{setup_id}:{event_code}:{field}"
                    ),
                    serenity::CreateSelectMenuKind::String { options },
                )
                .placeholder(placeholder)
                .min_values(min_values)
                .max_values(1)
            };
            let rows = vec![
                CreateActionRow::SelectMenu(make_menu("legion1", "Legion 1 time", 1)),
                CreateActionRow::SelectMenu(make_menu("legion2", "Legion 2 time (optional)", 0)),
                CreateActionRow::Buttons(vec![
                    components::success(
                        format!(
                            "settings:notifications:wizard_widget_save:{setup_id}:{event_code}"
                        ),
                        "Save",
                    ),
                    components::secondary(
                        format!("settings:notifications:wizard_widget_back:{setup_id}"),
                        "Back",
                    ),
                ]),
            ];
            interaction
                .create_response(
                    &ctx.http,
                    update(
                        embeds::brand(format!("Configure {}", event.replace('_', " ")))
                            .description(description),
                        rows,
                    ),
                )
                .await?;
            return Ok(());
        }
        let selected_raw = if event == "chief_order" {
            setup
                .event_repeats
                .get(event)
                .and_then(|raw| raw.strip_prefix("orders:"))
        } else {
            setup
                .event_times
                .get(event)
                .map(String::as_str)
                .map(|raw| raw.strip_prefix("phases:").unwrap_or(raw))
        }
        .unwrap_or_default();
        let selected = selected_raw
            .split(',')
            .collect::<std::collections::HashSet<_>>();
        let options = choices
            .into_iter()
            .map(|(label, value)| {
                serenity::CreateSelectMenuOption::new(label, value)
                    .default_selection(selected.contains(value))
            })
            .collect();
        let menu = serenity::CreateSelectMenu::new(
            format!("settings:notifications:wizard_widget_pick:{setup_id}:{event_code}"),
            serenity::CreateSelectMenuKind::String { options },
        )
        .placeholder("Select event options")
        .min_values(1)
        .max_values(max_values);
        let mut rows = vec![CreateActionRow::SelectMenu(menu)];
        let requires_confirmation =
            event == "chief_order" || event == "castle_battle" || event == "svs";
        rows.push(CreateActionRow::Buttons(if requires_confirmation {
            vec![
                components::success(
                    format!("settings:notifications:wizard_widget_save:{setup_id}:{event_code}"),
                    "Save",
                ),
                components::secondary(
                    format!("settings:notifications:wizard_widget_back:{setup_id}"),
                    "Back",
                ),
            ]
        } else {
            vec![components::secondary(
                format!("settings:notifications:wizard_widget_back:{setup_id}"),
                "Back",
            )]
        }));
        interaction
            .create_response(
                &ctx.http,
                update(
                    embeds::brand(format!("Configure {}", event.replace('_', " ")))
                        .description(description),
                    rows,
                ),
            )
            .await?;
        return Ok(());
    }
    match event.as_str() {
        "bear_trap" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short("bt1date", "Bear 1 date (DD/MM)")),
                CreateActionRow::InputText(components::short("bt1time", "Bear 1 time (HH:MM)")),
                CreateActionRow::InputText(
                    components::short("bt2date", "Bear 2 date (DD/MM)").required(false),
                ),
                CreateActionRow::InputText(components::short("bt2time", "Bear 2 time (HH:MM)")),
            ];
            send_modal(
                ctx,
                interaction,
                &format!("settings:notifications_widget_modal:{setup_id}:bear"),
                "Set Bear Trap alerts",
                inputs,
            )
            .await
        }
        "crazy_joe" => {
            let inputs = vec![
                CreateActionRow::InputText(
                    components::short("tuesday", "Tuesday time (HH:MM)").max_length(5),
                ),
                CreateActionRow::InputText(
                    components::short("thursday", "Thursday time (HH:MM)")
                        .required(false)
                        .max_length(5),
                ),
            ];
            send_modal(
                ctx,
                interaction,
                &format!("settings:notifications_widget_modal:{setup_id}:crazy_joe"),
                "Set Crazy Joe times",
                inputs,
            )
            .await
        }
        "mercenary_prestige" => notification_wizard_mercenary_hub(ctx, interaction, &setup).await,
        _ => notification_wizard_setup_edit(ctx, interaction, &setup).await,
    }
}

async fn notification_wizard_widget_pick(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
    event_code: &str,
    field: Option<&str>,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(mut setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    let event = notification_wizard_decode_events(event_code)?
        .into_iter()
        .next()
        .ok_or_else(|| anyhow::anyhow!("invalid notification event"))?;
    let selected = match &interaction.data.kind {
        serenity::ComponentInteractionDataKind::StringSelect { values } => values.clone(),
        _ => Vec::new(),
    };
    if selected.is_empty() && field != Some("legion2") {
        return Err(anyhow::anyhow!("select at least one event option"));
    }
    if let Some(field @ ("legion1" | "legion2")) = field {
        let key = format!("{event}__{field}");
        if let Some(value) = selected.first() {
            setup.event_times.insert(key, value.clone());
        } else {
            setup.event_times.remove(&key);
        }
        crate::notifications::wizard::insert_setup(setup);
        interaction
            .create_response(&ctx.http, serenity::CreateInteractionResponse::Acknowledge)
            .await?;
        return Ok(());
    } else if event == "chief_order" {
        setup
            .event_repeats
            .insert(event.clone(), format!("orders:{}", selected.join(",")));
    } else if event == "castle_battle" || event == "svs" {
        setup
            .event_times
            .insert(event.clone(), format!("phases:{}", selected.join(",")));
    } else {
        setup.event_times.insert(event.clone(), selected.join(","));
    }
    if event != "chief_order" && event != "castle_battle" && event != "svs" {
        setup.configured_events.insert(event.clone());
    }
    crate::notifications::wizard::insert_setup(setup.clone());
    if event == "chief_order" || event == "castle_battle" || event == "svs" {
        interaction
            .create_response(&ctx.http, serenity::CreateInteractionResponse::Acknowledge)
            .await?;
        return Ok(());
    }
    notification_wizard_setup_edit(ctx, interaction, &setup).await
}

async fn notification_wizard_widget_save(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
    event_code: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(mut setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    let event = notification_wizard_decode_events(event_code)?
        .into_iter()
        .next()
        .ok_or_else(|| anyhow::anyhow!("invalid event"))?;
    if event == "foundry_battle" || event == "canyon_clash" {
        let Some(first) = setup.event_times.get(&format!("{event}__legion1")).cloned() else {
            return reply(
                ctx,
                interaction,
                embeds::warn("Legion 1 required", "Choose a Legion 1 time before saving."),
                Vec::new(),
                true,
            )
            .await;
        };
        let second = setup.event_times.get(&format!("{event}__legion2")).cloned();
        setup.event_times.insert(
            event.clone(),
            [Some(first), second]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(","),
        );
    } else if event == "chief_order" {
        if setup
            .event_repeats
            .get(&event)
            .and_then(|raw| raw.strip_prefix("orders:"))
            .is_none()
        {
            return reply(
                ctx,
                interaction,
                embeds::warn("Choose an order", "Select at least one Chief Order."),
                Vec::new(),
                true,
            )
            .await;
        }
    } else if event == "bear_trap" {
        if setup.event_repeats.get(&event).is_none() {
            return reply(
                ctx,
                interaction,
                embeds::warn(
                    "Choose repeat days",
                    "Select every two days or choose at least one weekday.",
                ),
                Vec::new(),
                true,
            )
            .await;
        }
    } else if setup
        .event_times
        .get(&event)
        .and_then(|raw| raw.strip_prefix("phases:"))
        .is_none()
    {
        return reply(
            ctx,
            interaction,
            embeds::warn("Choose a phase", "Select at least one event phase."),
            Vec::new(),
            true,
        )
        .await;
    }
    setup.configured_events.insert(event);
    crate::notifications::wizard::insert_setup(setup.clone());
    notification_wizard_setup_edit(ctx, interaction, &setup).await
}

async fn notification_wizard_widget_toggle(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
    event_code: &str,
    option: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(mut setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    let event = notification_wizard_decode_events(event_code)?
        .into_iter()
        .next()
        .ok_or_else(|| anyhow::anyhow!("invalid event"))?;
    let allowed = if event == "bear_trap" {
        ["mon", "tue", "wed", "thu", "fri", "sat", "sun"].contains(&option)
    } else {
        notification_wizard_widget_choices(&event)
            .map(|(options, _, _)| options.into_iter().any(|(_, key)| key == option))
            .unwrap_or(false)
    };
    if !allowed {
        return Err(anyhow::anyhow!("invalid event option"));
    }
    if event == "bear_trap" {
        let values = setup
            .event_repeats
            .get(&event)
            .and_then(|raw| raw.strip_prefix("days:"))
            .unwrap_or_default();
        let mut selected = values
            .split(',')
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .collect::<Vec<_>>();
        if let Some(index) = selected.iter().position(|value| value == option) {
            selected.remove(index);
        } else {
            selected.push(option.to_string());
        }
        selected.sort();
        if selected.is_empty() {
            setup.event_repeats.remove(&event);
        } else {
            setup
                .event_repeats
                .insert(event.clone(), format!("days:{}", selected.join(",")));
        }
    } else if event == "chief_order" {
        let values = setup
            .event_repeats
            .get(&event)
            .and_then(|raw| raw.strip_prefix("orders:"))
            .unwrap_or_default();
        let mut selected = values
            .split(',')
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .collect::<Vec<_>>();
        if let Some(index) = selected.iter().position(|value| value == option) {
            selected.remove(index);
        } else {
            selected.push(option.to_string());
        }
        if selected.is_empty() {
            setup.event_repeats.remove(&event);
        } else {
            setup
                .event_repeats
                .insert(event.clone(), format!("orders:{}", selected.join(",")));
        }
    } else {
        let values = setup
            .event_times
            .get(&event)
            .and_then(|raw| raw.strip_prefix("phases:"))
            .unwrap_or_default();
        let mut selected = values
            .split(',')
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .collect::<Vec<_>>();
        if let Some(index) = selected.iter().position(|value| value == option) {
            selected.remove(index);
        } else {
            selected.push(option.to_string());
        }
        if selected.is_empty() {
            setup.event_times.remove(&event);
        } else {
            setup
                .event_times
                .insert(event.clone(), format!("phases:{}", selected.join(",")));
        }
    }
    setup.configured_events.remove(&event);
    crate::notifications::wizard::insert_setup(setup);
    if event == "bear_trap" {
        let setup =
            crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
                .ok_or_else(|| anyhow::anyhow!("wizard expired"))?;
        return notification_wizard_bear_weekday_screen(ctx, interaction, &setup).await;
    }
    notification_wizard_widget_open(ctx, data, interaction, setup_id, event_code).await
}

