async fn notification_wizard_widget_continue(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    setup_id: &str,
) -> anyhow::Result<()> {
    if !permissions::component_is_admin(ctx, data, interaction).await {
        return reply(
            ctx,
            interaction,
            embeds::denied("Manage Server"),
            Vec::new(),
            true,
        )
        .await;
    }
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or_default();
    let Some(setup) =
        crate::notifications::wizard::get_setup(setup_id, interaction.user.id.get(), guild_id)
    else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Wizard expired", "Start notification setup again."),
            Vec::new(),
            true,
        )
        .await;
    };
    if let Some(missing) = setup
        .events
        .iter()
        .find(|event| !setup.configured_events.contains(*event))
    {
        return reply(
            ctx,
            interaction,
            embeds::warn(
                "Event setup incomplete",
                format!(
                    "Configure `{}` before continuing.",
                    missing.replace('_', " ")
                ),
            ),
            Vec::new(),
            true,
        )
        .await;
    }
    let times = setup
        .events
        .iter()
        .filter_map(|event| {
            setup
                .event_times
                .get(event)
                .map(|value| format!("{event}={value}"))
        })
        .collect::<Vec<_>>()
        .join(";");
    let repeats = setup
        .events
        .iter()
        .filter_map(|event| {
            setup
                .event_repeats
                .get(event)
                .map(|value| format!("{event}={value}"))
        })
        .collect::<Vec<_>>()
        .join(";");
    let event_codes = setup
        .events
        .iter()
        .filter_map(|event| notification_wizard_event_code(event))
        .collect::<Vec<_>>()
        .join(",");
    let mut times_input = components::short("times", "Event times (configured above)")
        .max_length(4000)
        .required(false);
    if !times.is_empty() {
        times_input = times_input.value(times);
    }
    let repeat_value = if repeats.is_empty() {
        "auto".to_string()
    } else {
        repeats
    };
    let inputs = vec![
        CreateActionRow::InputText(times_input),
        CreateActionRow::InputText(
            components::short("timezone", "Timezone (IANA or event=zone)")
                .value("UTC")
                .max_length(4000),
        ),
        CreateActionRow::InputText(
            components::short("mention", "Mention or event=target")
                .value("none")
                .max_length(4000),
        ),
        CreateActionRow::InputText(
            components::short("repeat", "Repeat or event=value")
                .max_length(4000)
                .value(repeat_value),
        ),
        CreateActionRow::InputText(
            components::paragraph("description", "Blank uses event templates; or event=text")
                .required(false)
                .max_length(3500),
        ),
    ];
    let modal_id = format!(
        "settings:notifications_batch_modal:s{}:{event_codes}",
        setup.id
    );
    send_modal(
        ctx,
        interaction,
        &modal_id,
        "Set shared notification settings",
        inputs,
    )
    .await
}

async fn notification_wizard_mercenary_hub(
    ctx: &serenity::Context,
    interaction: &ComponentInteraction,
    setup: &crate::notifications::wizard::WizardSetup,
) -> anyhow::Result<()> {
    let bosses = setup
        .event_times
        .get("mercenary_prestige")
        .and_then(|value| value.strip_prefix("bosses:"))
        .unwrap_or_default();
    let description = if bosses.is_empty() {
        "No bosses scheduled yet. Add up to five day/time slots, or set all bosses at once."
            .to_string()
    } else {
        format!("**Scheduled bosses:**\n{}", bosses.replace(',', "\n"))
    };
    let mut buttons = vec![
        components::primary(
            format!("settings:notifications:wizard_merc_action:{}:add", setup.id),
            "Add Boss",
        ),
        components::secondary(
            format!("settings:notifications:wizard_merc_action:{}:all", setup.id),
            "All At Once",
        ),
    ];
    if !bosses.is_empty() {
        buttons.push(components::danger(
            format!(
                "settings:notifications:wizard_merc_action:{}:remove",
                setup.id
            ),
            "Remove Last",
        ));
        buttons.push(components::success(
            format!(
                "settings:notifications:wizard_merc_action:{}:save",
                setup.id
            ),
            "Continue",
        ));
        buttons.push(components::danger(
            format!(
                "settings:notifications:wizard_merc_action:{}:clear",
                setup.id
            ),
            "Clear All",
        ));
    }
    let rows = vec![
        CreateActionRow::Buttons(buttons),
        CreateActionRow::Buttons(vec![components::secondary(
            format!("settings:notifications:wizard_widget_back:{}", setup.id),
            "Back to events",
        )]),
    ];
    interaction
        .create_response(
            &ctx.http,
            update(
                embeds::brand("🗡️ Configure Mercenary Prestige").description(description),
                rows,
            ),
        )
        .await?;
    Ok(())
}

