// ---------------------------------------------------------- wos relay panel

fn component_is_owner(data: &Data, interaction: &ComponentInteraction) -> bool {
    data.cfg.owner_id == Some(interaction.user.id.get())
}

async fn render_wos(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let destination = db::wos_relay::destination(&data.db, guild_id).await?;
    let hub = db::wos_relay::hub(&data.db).await.unwrap_or_default();
    let sneakpeek = db::sneak_peek::settings(&data.db, guild_id)
        .await
        .ok()
        .and_then(|s| s.channel());
    let view = panels::WosRelayView {
        destination,
        sneakpeek,
        hub_channel: if hub.guild() == Some(guild_id) {
            hub.channel()
        } else {
            None
        },
        hub_configured: hub.channel().is_some(),
        is_owner: component_is_owner(data, interaction),
    };
    let (embed, rows) = panels::wos_relay_panel(&view);
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn wos_panel_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    sub: &str,
    guild_id: u64,
) -> anyhow::Result<()> {
    match sub {
        "" | "refresh" => render_wos(ctx, data, interaction, guild_id).await,
        "cleanup" | "cleanup_toggle" | "cleanup_preset" | "cleanup_custom" => {
            if sub == "cleanup_toggle" {
                let current = db::welcome::wos_cleanup_settings(&data.db, guild_id).await?;
                db::welcome::set_wos_cleanup_settings(
                    &data.db,
                    guild_id,
                    !current.enabled(),
                    current.delay_minutes(),
                )
                .await?;
            } else if sub == "cleanup_custom" {
                return send_modal(
                    ctx,
                    interaction,
                    "settings:wos_cleanup_modal",
                    "Custom WOS Cleanup Delay",
                    vec![CreateActionRow::InputText(
                        components::short("minutes", "Delete after how many minutes?")
                            .max_length(5),
                    )],
                )
                .await;
            } else if sub == "cleanup_preset" {
                let minutes = match &interaction.data.kind {
                    serenity::ComponentInteractionDataKind::StringSelect { values } => {
                        values.first().and_then(|value| value.parse::<i64>().ok())
                    }
                    _ => None,
                }
                .ok_or_else(|| anyhow::anyhow!("choose a cleanup delay"))?;
                if ![30, 60, 360, 720, 1440, 4320, 10080].contains(&minutes) {
                    anyhow::bail!("unsupported cleanup delay");
                }
                db::welcome::set_wos_cleanup_settings(&data.db, guild_id, true, minutes).await?;
            }
            let settings = db::welcome::wos_cleanup_settings(&data.db, guild_id).await?;
            let (embed, rows) = panels::wos_cleanup_panel(&settings);
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "destination" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Channel id (or `none` to clear)",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:wos_destination_modal",
                "WOS Announcements destination",
                inputs,
            )
            .await
        }
        "clear" => {
            db::wos_relay::set_destination(&data.db, guild_id, None).await?;
            render_wos(ctx, data, interaction, guild_id).await
        }
        "hub" => {
            if !component_is_owner(data, interaction) {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Bot Owner"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Hub channel id in this server",
            ))];
            send_modal(
                ctx,
                interaction,
                "settings:wos_hub_modal",
                "Set the hub channel",
                inputs,
            )
            .await
        }
        "clearhub" => {
            if !component_is_owner(data, interaction) {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Bot Owner"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            db::wos_relay::clear_hub(&data.db).await?;
            render_wos(ctx, data, interaction, guild_id).await
        }
        other => Err(anyhow::anyhow!("unknown wos action `{other}`")),
    }
}

// ----------------------------------------------------------- perm / admin

fn resolve_username(ctx: &serenity::Context, guild_id: u64, user_id: u64) -> String {
    let guild = ctx.cache.guild(serenity::GuildId::new(guild_id));
    if let Some(guild) = guild {
        if let Some(member) = guild.members.get(&serenity::UserId::new(user_id)) {
            return member.display_name().to_string();
        }
    }
    format!("User {user_id}")
}

/// The `/settings` → **Admin** page: the DB-backed permissions manager.
pub(crate) async fn admin_panel(
    ctx: &serenity::Context,
    data: &Data,
    guild_id: u64,
) -> anyhow::Result<(CreateEmbed, Vec<CreateActionRow>)> {
    let admins = db::admin::list(&data.db).await?;
    let owner = db::admin::owner_id(&data.db).await?;

    let owner_line = match owner {
        Some(owner_id) => format!("👑 {} (`{owner_id}`)", resolve_username(ctx, guild_id, owner_id)),
        None => "⚠️ **Not yet claimed.** The first admin to click **Claim Bot Owner** below becomes the permanent owner.".to_string(),
    };
    let admin_lines: Vec<String> = admins
        .iter()
        .take(15)
        .map(|entry| {
            let icon = if entry.is_owner { "👑" } else { "🏅" };
            format!(
                "{icon} **{}** — {}",
                resolve_username(ctx, guild_id, entry.id),
                if entry.is_owner { "Bot Owner" } else { "Admin" }
            )
        })
        .collect();
    let total = admins.len();
    let admin_count = admins.iter().filter(|entry| !entry.is_owner).count();

    let embed = embeds::brand(format!("{} Permissions", icons::ADMIN))
        .color(colors::VIOLET)
        .description(concat!(
            "Permissions system controls who can manage notifications and other admins.\n",
            "Use the pickers below to add a new admin, remove one, or transfer ownership.",
        ))
        .field(
            "Tiers",
            "👑 **Bot Owner** — recovery anchor; only one; changed via Transfer Owner\n🏅 **Admin** — full access to notifications and admin management",
            false,
        )
        .field(
            "Current state",
            format!(
                "**Bot Owner:** {owner_line}\n**Total admins:** {total} ({admin_count} Admin{})",
                if admin_count == 1 { "" } else { "s" }
            ),
            false,
        )
        .field(
            format!("Admins ({total})"),
            if admin_lines.is_empty() {
                "_No admins yet — use the picker below to add the first one._".to_string()
            } else {
                admin_lines.join("\n")
            },
            false,
        )
        .footer(serenity::CreateEmbedFooter::new(theme::footer()));

    let mut rows: Vec<CreateActionRow> = Vec::new();

    if owner.is_none() && !admins.is_empty() {
        rows.push(CreateActionRow::Buttons(vec![components::success(
            "perm:claim",
            format!("{} Claim Bot Owner", icons::CROWN),
        )]));
    }

    rows.push(CreateActionRow::SelectMenu(
        serenity::CreateSelectMenu::new(
            "perm:adduser",
            serenity::CreateSelectMenuKind::User {
                default_users: None,
            },
        )
        .placeholder("+ Add admin (pick a user)…")
        .min_values(0)
        .max_values(1),
    ));

    if admins.iter().any(|entry| !entry.is_owner) {
        let options: Vec<serenity::CreateSelectMenuOption> = admins
            .iter()
            .filter(|entry| !entry.is_owner)
            .take(25)
            .map(|entry| {
                let name = resolve_username(ctx, guild_id, entry.id);
                serenity::CreateSelectMenuOption::new(
                    name.chars().take(100).collect::<String>(),
                    entry.id.to_string(),
                )
                .description("Admin — tap to remove")
            })
            .collect();
        rows.push(CreateActionRow::SelectMenu(
            serenity::CreateSelectMenu::new(
                "perm:removeuser",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Remove an admin…")
            .min_values(1)
            .max_values(1),
        ));
    }

    if admins.len() > 1 {
        let options: Vec<serenity::CreateSelectMenuOption> = admins
            .iter()
            .filter(|entry| !entry.is_owner)
            .take(25)
            .map(|entry| {
                let name = resolve_username(ctx, guild_id, entry.id);
                serenity::CreateSelectMenuOption::new(
                    name.chars().take(100).collect::<String>(),
                    entry.id.to_string(),
                )
            })
            .collect();
        rows.push(CreateActionRow::SelectMenu(
            serenity::CreateSelectMenu::new(
                "perm:transferuser",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Transfer Bot Owner to…")
            .min_values(1)
            .max_values(1),
        ));
    }

    rows.push(CreateActionRow::Buttons(vec![
        components::secondary("perm:audit", format!("{} Audit log", icons::LIST)),
        components::secondary("perm:groups:0", "📁 Message Groups"),
        components::secondary("perm:backup", format!("{} Backup DB", icons::SAVE)),
        components::secondary("atkset:home", format!("{} Admin Toolkit", icons::TOOLS)),
        components::secondary("settings:home", format!("{} Back", icons::BACK)),
    ]));

    Ok((embed, rows))
}

async fn is_effective_owner(data: &Data, user_id: u64) -> bool {
    if data.cfg.owner_id == Some(user_id) {
        return true;
    }
    db::admin::is_owner(&data.db, user_id).await
}

async fn refresh_perm_panel(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
) -> anyhow::Result<()> {
    let (embed, rows) = admin_panel(ctx, data, guild_id).await?;
    update_response(ctx, data, interaction, embed, rows).await
}

async fn render_perm_message_groups(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    page: usize,
) -> anyhow::Result<()> {
    let groups = db::messages::list_all_groups(&data.db).await?;
    let page_size = 10usize;
    let pages = groups.len().max(1).div_ceil(page_size);
    let page = page.min(pages.saturating_sub(1));
    let start = page * page_size;
    let end = (start + page_size).min(groups.len());
    let slice = &groups[start..end];
    let mut lines = Vec::new();
    for group in slice {
        let access = if group.visibility == "selected" {
            db::messages::group_access_ids(&data.db, group.id)
                .await?
                .len()
        } else {
            0
        };
        lines.push(format!(
            "{} **{}** — `{}` · creator `{}` · {} selected admin(s)",
            if group.visibility == "owner" {
                "🔒"
            } else if group.visibility == "all" {
                "📁"
            } else {
                "👥"
            },
            group.name,
            group.visibility,
            group.created_by,
            access
        ));
    }
    let description = if lines.is_empty() {
        "_No message groups exist._".to_string()
    } else {
        lines.join("\n")
    };
    let embed = embeds::brand("📁 Message Group Visibility")
        .description(format!("Manage access across all servers.\n\n**Tiers**\n🔒 Owner only · 👥 Selected admins · 📁 All admins\n\n{}", description));
    let mut rows = Vec::new();
    if !slice.is_empty() {
        let options = slice
            .iter()
            .map(|group| {
                serenity::CreateSelectMenuOption::new(
                    group.name.chars().take(100).collect::<String>(),
                    group.id.to_string(),
                )
                .description(format!(
                    "{} · {}",
                    group.visibility,
                    group.guild_id.as_deref().unwrap_or("global")
                ))
            })
            .collect();
        rows.push(CreateActionRow::SelectMenu(
            serenity::CreateSelectMenu::new(
                "perm:groups:open",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Open a group")
            .min_values(1)
            .max_values(1),
        ));
    }
    if pages > 1 {
        rows.push(CreateActionRow::Buttons(vec![
            components::secondary(format!("perm:groups:{}", page.saturating_sub(1)), "◀ Prev")
                .disabled(page == 0),
            components::secondary("perm:groups:noop", format!("Page {}/{pages}", page + 1))
                .disabled(true),
            components::secondary(format!("perm:groups:{}", page + 1), "Next ▶")
                .disabled(page + 1 >= pages),
        ]));
    }
    rows.push(CreateActionRow::Buttons(vec![components::secondary(
        "settings:admin",
        "◀️ Back",
    )]));
    update_panel(ctx, data, interaction, embed, rows).await?;
    let _ = guild_id;
    Ok(())
}

async fn render_perm_message_group_detail(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    group_id: i64,
    page: usize,
) -> anyhow::Result<()> {
    let Some(group) = db::messages::get_group(&data.db, group_id).await? else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Not found", "That message group was deleted."),
            Vec::new(),
            true,
        )
        .await;
    };
    let admins = db::admin::list(&data.db).await?;
    let granted = db::messages::group_access_ids(&data.db, group_id).await?;
    let creator = group.created_by.parse::<u64>().ok();
    let granted_lines = granted
        .iter()
        .map(|id| format!("<@{id}>"))
        .collect::<Vec<_>>();
    let embed = embeds::brand(format!("📁 {}", group.name))
        .description(format!(
            "**Visibility:** `{}`\n**Created by:** `{}`\n**Home guild:** `{}`\n\n**Selected admins:** {}",
            group.visibility,
            group.created_by,
            group.guild_id.as_deref().unwrap_or("global"),
            if granted_lines.is_empty() { "_creator only_".to_string() } else { granted_lines.join(", ") }
        ));
    let mut rows = vec![CreateActionRow::Buttons(vec![
        components::danger(
            format!("perm:groups:setvis:{group_id}:owner:{page}"),
            "🔒 Owner Only",
        )
        .disabled(group.visibility == "owner"),
        components::primary(
            format!("perm:groups:setvis:{group_id}:selected:{page}"),
            "👥 Selected Admins",
        )
        .disabled(group.visibility == "selected"),
        components::success(
            format!("perm:groups:setvis:{group_id}:all:{page}"),
            "📁 All Admins",
        )
        .disabled(group.visibility == "all"),
    ])];
    if group.visibility == "selected" {
        let defaults = granted.iter().copied().map(serenity::UserId::new).collect();
        let max_values = admins
            .iter()
            .filter(|admin| !admin.is_owner && Some(admin.id) != creator)
            .count()
            .min(25) as u8;
        if max_values > 0 {
            rows.push(CreateActionRow::SelectMenu(
                serenity::CreateSelectMenu::new(
                    format!("perm:groups:access:{}:{page}", group.id),
                    serenity::CreateSelectMenuKind::User {
                        default_users: Some(defaults),
                    },
                )
                .placeholder("Set selected admin access")
                .min_values(0)
                .max_values(max_values),
            ));
        }
    }
    rows.push(CreateActionRow::Buttons(vec![components::secondary(
        format!("perm:groups:{page}"),
        "◀️ Back to groups",
    )]));
    update_panel(ctx, data, interaction, embed, rows).await
}

async fn perm_message_groups(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    action: &str,
) -> anyhow::Result<()> {
    let sub = action.strip_prefix(':').unwrap_or(action);
    let parts = sub.split(':').collect::<Vec<_>>();
    match parts.first().copied().unwrap_or("") {
        "open" => {
            let id = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().and_then(|v| v.parse::<i64>().ok())
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("select a message group"))?;
            render_perm_message_group_detail(ctx, data, interaction, id, 0).await
        }
        "setvis" => {
            let id = parts
                .get(1)
                .and_then(|v| v.parse::<i64>().ok())
                .ok_or_else(|| anyhow::anyhow!("invalid group id"))?;
            let visibility = match parts.get(2).copied().unwrap_or("") {
                "owner" => db::messages::Visibility::Owner,
                "selected" => db::messages::Visibility::Selected,
                "all" => db::messages::Visibility::All,
                _ => anyhow::bail!("invalid group visibility"),
            };
            db::messages::set_group_visibility_global(&data.db, id, visibility).await?;
            let page = parts
                .get(3)
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(0);
            render_perm_message_group_detail(ctx, data, interaction, id, page).await
        }
        "access" => {
            let group_id = parts
                .get(1)
                .and_then(|v| v.parse::<i64>().ok())
                .ok_or_else(|| anyhow::anyhow!("invalid group id"))?;
            let selected = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::UserSelect { values } => {
                    values.iter().map(|user| user.get()).collect::<Vec<_>>()
                }
                _ => return Err(anyhow::anyhow!("select the group admins")),
            };
            let group = db::messages::get_group(&data.db, group_id)
                .await?
                .ok_or_else(|| anyhow::anyhow!("group not found"))?;
            let admins = db::admin::list(&data.db).await?;
            let allowed = admins
                .iter()
                .filter(|admin| !admin.is_owner && admin.id.to_string() != group.created_by)
                .map(|admin| admin.id)
                .collect::<std::collections::HashSet<_>>();
            let selected = selected
                .into_iter()
                .filter(|user| allowed.contains(user))
                .collect::<Vec<_>>();
            db::messages::set_group_access_ids(&data.db, group_id, &selected).await?;
            let page = parts
                .get(2)
                .and_then(|v| v.parse::<usize>().ok())
                .unwrap_or(0);
            render_perm_message_group_detail(ctx, data, interaction, group_id, page).await
        }
        "noop" => interaction.defer(&ctx.http).await.map_err(Into::into),
        page => {
            render_perm_message_groups(
                ctx,
                data,
                interaction,
                guild_id,
                page.parse::<usize>().unwrap_or(0),
            )
            .await
        }
    }
}

async fn perm_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("permissions only work inside a server"))?;
    let user_id = interaction.user.id.get();

    if let Some(rest) = action.strip_prefix("groups") {
        if !is_effective_owner(data, user_id).await {
            return reply(
                ctx,
                interaction,
                embeds::denied("Bot Owner"),
                Vec::new(),
                true,
            )
            .await;
        }
        return perm_message_groups(ctx, data, interaction, guild_id, rest).await;
    }

    match action {
        "claim" => {
            let admins = db::admin::list(&data.db).await?;
            if admins.is_empty() {
                return update_response(
                    ctx,
                    data,
                    interaction,
                    embeds::warn(
                        "No admins",
                        "Add an admin first — the first admin becomes the owner.",
                    ),
                    Vec::new(),
                )
                .await;
            }
            if db::admin::claim_owner(&data.db, user_id, user_id).await? {
                refresh_perm_panel(ctx, data, interaction, guild_id).await
            } else {
                update_response(
                    ctx,
                    data,
                    interaction,
                    embeds::warn(
                        "Already claimed",
                        "A bot owner already exists — transfer ownership instead.",
                    ),
                    Vec::new(),
                )
                .await
            }
        }
        "adduser" => {
            let values = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::UserSelect { values } => values.clone(),
                _ => return Err(anyhow::anyhow!("expected a user picker")),
            };
            let Some(target) = values.first() else {
                return refresh_perm_panel(ctx, data, interaction, guild_id).await;
            };
            let became_owner = db::admin::add(&data.db, target.get(), false, user_id).await?;
            let note = if became_owner {
                " added as the first admin — they are now **Bot Owner**."
            } else {
                " added as **Admin**."
            };
            let embed = embeds::ok(format!("<@{}>{note}", target.get()));
            update_response(ctx, data, interaction, embed, Vec::new()).await
        }
        "removeuser" => {
            let values = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values.clone(),
                _ => return Err(anyhow::anyhow!("expected an admin picker")),
            };
            let Some(target) = values.first().and_then(|v| v.parse::<u64>().ok()) else {
                return refresh_perm_panel(ctx, data, interaction, guild_id).await;
            };
            if is_effective_owner(data, target).await {
                return update_response(
                    ctx,
                    data,
                    interaction,
                    embeds::warn(
                        "Protected",
                        "The bot owner can only be changed via **Transfer Bot Owner**.",
                    ),
                    Vec::new(),
                )
                .await;
            }
            let list = db::admin::list(&data.db).await?;
            if !list.iter().any(|entry| entry.id == target) {
                return update_response(
                    ctx,
                    data,
                    interaction,
                    embeds::warn("Not an admin", "That user is not an admin."),
                    Vec::new(),
                )
                .await;
            }
            match db::admin::remove(&data.db, target, user_id).await? {
                Ok(()) => {
                    let embed = embeds::ok(format!("<@{target}> removed from the admin list."));
                    update_response(ctx, data, interaction, embed, Vec::new()).await
                }
                Err(message) => {
                    update_response(
                        ctx,
                        data,
                        interaction,
                        embeds::warn("Not removed", message),
                        Vec::new(),
                    )
                    .await
                }
            }
        }
        "transferuser" => {
            let values = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values.clone(),
                _ => return Err(anyhow::anyhow!("expected an admin picker")),
            };
            let Some(target) = values.first().and_then(|v| v.parse::<u64>().ok()) else {
                return refresh_perm_panel(ctx, data, interaction, guild_id).await;
            };
            let embed = embeds::warn(
                "Transfer Bot Owner?",
                format!(
                    "<@{target}> will become the **Bot Owner**. You will lose ownership.\nThis cannot be undone from this menu."
                ),
            );
            let rows = vec![CreateActionRow::Buttons(vec![
                components::danger(
                    format!("perm:transferconfirm:{target}"),
                    "Transfer ownership",
                ),
                components::secondary("perm:transfercancel", "Cancel"),
            ])];
            update_response(ctx, data, interaction, embed, rows).await
        }
        other if other.starts_with("transferconfirm:") => {
            let target = other
                .trim_start_matches("transferconfirm:")
                .parse::<u64>()
                .map_err(|_| anyhow::anyhow!("malformed transfer id"))?;
            match db::admin::transfer_owner(&data.db, target, user_id).await? {
                Ok(()) => {
                    let embed = embeds::ok(format!("<@{target}> is now the **Bot Owner**."));
                    update_response(ctx, data, interaction, embed, Vec::new()).await
                }
                Err(message) => {
                    update_response(
                        ctx,
                        data,
                        interaction,
                        embeds::warn("Not transferred", message),
                        Vec::new(),
                    )
                    .await
                }
            }
        }
        "transfercancel" => refresh_perm_panel(ctx, data, interaction, guild_id).await,
        "audit" => {
            let entries = db::admin::audit_log(&data.db, 10).await?;
            let body = if entries.is_empty() {
                "_No admin changes recorded yet._".to_string()
            } else {
                entries
                    .iter()
                    .map(|entry| {
                        let target = entry.target_id.as_deref().unwrap_or("—");
                        format!(
                            "`#{}` · `{}` · <@{}> · {}{}",
                            entry.id,
                            entry.action,
                            entry.actor_id,
                            target,
                            if entry.target_id.is_some() {
                                format!(" → <@{target}>")
                            } else {
                                String::new()
                            }
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
            };
            let embed = embeds::brand(format!("{} Audit log", icons::LIST))
                .color(colors::VIOLET)
                .description(format!("{}\n{}", theme::DIVIDER, body))
                .footer(serenity::CreateEmbedFooter::new(theme::footer()));
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        "backup" => {
            if !is_effective_owner(data, user_id).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Bot Owner"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            interaction
                .create_response(
                    &ctx.http,
                    CreateInteractionResponse::Defer(
                        CreateInteractionResponseMessage::new().ephemeral(true),
                    ),
                )
                .await?;

            let path = data.cfg.database_path.clone();
            let (bytes, filename) = crate::backup::archive_database_snapshot(&path).await?;
            const MAX_UPLOAD: usize = 10 * 1024 * 1024;
            if bytes.len() > MAX_UPLOAD {
                interaction
                    .edit_response(
                        &ctx.http,
                        EditInteractionResponse::new().content(format!(
                            "Backup is {:.1} MB — too large to upload here. Pull the database file from the server instead.",
                            bytes.len() as f64 / 1_048_576.0
                        )),
                    )
                    .await?;
                return Ok(());
            }
            let size_mb = bytes.len() as f64 / 1_048_576.0;
            interaction
                .create_followup(
                    &ctx.http,
                    serenity::CreateInteractionResponseFollowup::new()
                        .content(format!("Here's your database backup ({size_mb:.1} MB)."))
                        .ephemeral(true)
                        .add_file(serenity::CreateAttachment::bytes(bytes, filename)),
                )
                .await?;
            Ok(())
        }
        other => Err(anyhow::anyhow!("unknown permissions action `{other}`")),
    }
}

// ------------------------------------------------------------ role flow

fn member_role_ids(interaction: &ComponentInteraction) -> Vec<u64> {
    crate::roles::actor_role_ids(interaction)
}

async fn start_assign_flow(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    guild_id: u64,
    update_existing: bool,
) -> anyhow::Result<()> {
    let actor = interaction.user.id.get();
    let is_admin = permissions::component_is_admin(ctx, data, interaction).await;
    let actor_roles = member_role_ids(interaction);
    let assignable =
        crate::roles::access_for(data, guild_id, actor, &actor_roles, is_admin).await?;

    if assignable.is_empty() {
        let embed = embeds::denied("a role from the catalog");
        if update_existing {
            return update_response(ctx, data, interaction, embed, Vec::new()).await;
        }
        return reply(ctx, interaction, embed, Vec::new(), true).await;
    }

    let sid = crate::roles::new_session(guild_id, actor);
    let embed = embeds::brand("🏷️ Assign Role — Step 1/3")
        .color(colors::BRAND)
        .description("Select one or more members to update (up to 25).")
        .footer(serenity::CreateEmbedFooter::new(theme::footer()));
    let select = serenity::CreateSelectMenu::new(
        format!("roleassign:{sid}:pickuser"),
        serenity::CreateSelectMenuKind::User {
            default_users: None,
        },
    )
    .placeholder("Select members…")
    .min_values(1)
    .max_values(25);
    let rows = vec![CreateActionRow::SelectMenu(select)];
    if update_existing {
        update_response(ctx, data, interaction, embed, rows).await
    } else {
        reply(ctx, interaction, embed, rows, true).await
    }
}

async fn update_response(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    embed: serenity::CreateEmbed,
    components: Vec<CreateActionRow>,
) -> anyhow::Result<()> {
    let is_post = db::admin_toolkit::find_post(&data.db, interaction.message.id.get())
        .await
        .ok()
        .flatten()
        .is_some();
    if is_post {
        interaction
            .create_response(&ctx.http, message(embed, components, true))
            .await?;
        if let Ok(response) = interaction.get_response(&ctx.http).await {
            crate::admintoolkit::track_ephemeral(response.id.get());
        }
        return Ok(());
    }
    interaction
        .create_response(
            &ctx.http,
            CreateInteractionResponse::UpdateMessage(
                CreateInteractionResponseMessage::new()
                    .embed(embed)
                    .components(components),
            ),
        )
        .await?;
    Ok(())
}

// ------------------------------------------------------------------ music

fn panel_response(view: panels::NowPlayingView) -> (CreateEmbed, Vec<CreateActionRow>) {
    panels::music(&view)
}

async fn music_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("music controls only work inside a server"))?;

    if action == "queue" {
        let state = data.music.state(guild_id).await.unwrap_or_default();
        let mut lines = Vec::new();
        if let Some(current) = state.current.as_ref() {
            lines.push(format!(
                "{} **Now** · {} `{}`",
                icons::PLAY,
                crate::error::truncate(current.title(), 60),
                theme::duration(current.length())
            ));
        }
        for (index, track) in state.queue.iter().take(15).enumerate() {
            lines.push(format!(
                "`{:>2}.` {} `{}`",
                index + 1,
                crate::error::truncate(track.title(), 60),
                theme::duration(track.length())
            ));
        }
        let body = if lines.is_empty() {
            "_The queue is empty._".to_string()
        } else {
            lines.join("\n")
        };
        let embed = panels::paged_list(
            &format!("{} Queue", icons::QUEUE),
            0,
            1,
            format!("{}\n{}", theme::DIVIDER, body),
        );
        return reply(ctx, interaction, embed, Vec::new(), true).await;
    }

    // Playback controls are only for people sitting in the bot's voice channel.
    let bot_id = ctx.cache.current_user().id;
    let (user_vc, bot_vc) = ctx
        .cache
        .guild(serenity::GuildId::new(guild_id))
        .map(|guild| {
            (
                guild
                    .voice_states
                    .get(&interaction.user.id)
                    .and_then(|s| s.channel_id),
                guild.voice_states.get(&bot_id).and_then(|s| s.channel_id),
            )
        })
        .unwrap_or((None, None));
    if bot_vc.is_some() && user_vc != bot_vc {
        return reply(
            ctx,
            interaction,
            embeds::warn(
                "Join the voice channel",
                "You need to be in the same voice channel as the bot to use these controls.",
            ),
            Vec::new(),
            true,
        )
        .await;
    }

    let state = data.music.state(guild_id).await.unwrap_or_default();
    match action {
        "pause" => {
            data.music.set_paused(guild_id, true).await?;
        }
        "resume" => {
            data.music.set_paused(guild_id, false).await?;
        }
        "skip" => {
            data.music.advance(guild_id).await;
        }
        "stop" => {
            data.music.stop(ctx, guild_id).await?;
        }
        "previous" => {
            if !data.music.restart_current(guild_id).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::info("Nothing to restart", "There is no current track."),
                    Vec::new(),
                    true,
                )
                .await;
            }
        }
        "shuffle" => {
            data.music.shuffle(guild_id).await;
        }
        "loop" => {
            let next = state.loop_mode.next();
            data.music.set_loop_state(guild_id, next).await;
            db::music::set_loop(&data.db, guild_id, next).await?;
        }
        "volup" | "voldown" => {
            if state.current.is_none() {
                return reply(
                    ctx,
                    interaction,
                    embeds::info(
                        "Nothing is playing",
                        "Start a track from the Music panel first.",
                    ),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let current = if state.volume == 0 { 80 } else { state.volume };
            let next = if action == "volup" {
                (current + 10).min(200)
            } else {
                current.saturating_sub(10)
            };
            data.music.set_volume(guild_id, next).await?;
            db::music::set_volume(&data.db, guild_id, next).await?;
        }
        other => return Err(anyhow::anyhow!("unknown music action `{other}`")),
    }

    let view = data.music.view(guild_id).await;
    let (embed, rows) = panel_response(view);
    update_panel(ctx, data, interaction, embed, rows).await
}

// ------------------------------------------------------------------ lookup

/// Build a private Lookup view response for a session tab.
/// Player sessions use Components V2 (same layout as the JS bot).
/// Alliance / State still use the embed path until those panels are ported.
async fn lookup_view_edit(
    ctx: &serenity::Context,
    data: &Data,
    session: &crate::lookup::sessions::LookupSession,
    tab: &str,
) -> anyhow::Result<crate::ui::v2::V2Edit> {
    use crate::lookup::sessions::Kind;

    match session.kind {
        Kind::Player => {
            let card_png = match tab {
                "overview" => {
                    let overview = overview_from_raw(&session.raw);
                    crate::cards::render_player_overview_card(&overview)
                        .await
                        .ok()
                }
                "standings" => {
                    let kid = session.state;
                    let rows: Vec<crate::cards::StandingRow> = session
                        .raw
                        .get("boards")
                        .or_else(|| session.raw.get("leaderboards"))
                        .and_then(|v| v.as_array())
                        .map(|arr| {
                            arr.iter()
                                .filter_map(|b| {
                                    let board = b
                                        .get("name")
                                        .or_else(|| b.get("key"))
                                        .and_then(|v| v.as_str())
                                        .unwrap_or("Board")
                                        .to_string();
                                    let rank = b
                                        .get("rank")
                                        .and_then(|v| v.as_i64())
                                        .map(|r| format!("#{r}"))
                                        .unwrap_or_else(|| "—".into());
                                    let score = b
                                        .get("score")
                                        .or_else(|| b.get("value"))
                                        .map(|v| match v {
                                            serde_json::Value::Number(n) => n.to_string(),
                                            serde_json::Value::String(s) => s.clone(),
                                            _ => "—".into(),
                                        })
                                        .unwrap_or_else(|| "—".into());
                                    Some(crate::cards::StandingRow {
                                        board,
                                        score,
                                        rank,
                                    })
                                })
                                .collect()
                        })
                        .unwrap_or_default();
                    crate::cards::render_standings_card(&session.name, kid, &rows).ok()
                }
                "heroes" => {
                    let loadout = session
                        .raw
                        .get("oracleLoadout")
                        .or_else(|| session.raw.get("loadout"))
                        .unwrap_or(&session.raw);
                    let gear_private = session
                        .raw
                        .get("gearPrivacy")
                        .or_else(|| session.raw.get("gear_privacy"))
                        .and_then(|v| v.as_bool())
                        .unwrap_or(false);
                    if !gear_private {
                        let cards = crate::cards::render_loadout_cards(loadout, &data.cfg.oracle_site)
                            .await;
                        if let Some(bytes) = cards.chief {
                            Some(bytes)
                        } else if let Some(heroes) =
                            session.raw.get("heroes").and_then(|v| v.as_array())
                        {
                            crate::cards::render_arena_lineup(heroes, &data.cfg.oracle_site)
                                .await
                                .ok()
                                .flatten()
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                }
                "progression" => {
                    let hist = session.raw.get("history").or_else(|| session.raw.get("snapshots"));
                    let rows: Vec<&serde_json::Value> = hist.and_then(|v| v.as_array()).map(|a| a.iter().collect()).or_else(|| hist.and_then(|v| v.get("history")).and_then(|v| v.as_array()).map(|a| a.iter().collect())).unwrap_or_default();
                    let mut power_series = Vec::new();
                    let mut kill_series = Vec::new();
                    for row in rows {
                        let t = row.get("ts").or_else(|| row.get("observed_at")).or_else(|| row.get("timestamp")).or_else(|| row.get("at")).and_then(|v| v.as_i64());
                        if let Some(p) = row.get("power").or_else(|| row.get("total_power")).and_then(|v| v.as_f64().or_else(|| v.as_i64().map(|n| n as f64))) {
                            power_series.push(crate::cards::SeriesPoint { v: p, t });
                        }
                        if let Some(k) = row.get("kills").or_else(|| row.get("total_kills")).and_then(|v| v.as_f64().or_else(|| v.as_i64().map(|n| n as f64))) {
                            kill_series.push(crate::cards::SeriesPoint { v: k, t });
                        }
                    }
                    if power_series.is_empty() && kill_series.is_empty() { None } else {
                        let as_of = power_series.last().and_then(|p| p.t).or_else(|| kill_series.last().and_then(|p| p.t)).map(|t| t.to_string());
                        let card = crate::cards::ProgressionCard {
                            name: session.name.clone(),
                            range_label: None,
                            power_snaps: Some(power_series.len() as i64),
                            kill_snaps: Some(kill_series.len() as i64),
                            power_series,
                            kill_series,
                            milestones: Vec::new(),
                            as_of,
                        };
                        crate::cards::render_progression_card(&card).ok()
                    }
                }
                "crowns" => {
                    let crowns_obj = session.raw.get("crowns").cloned().unwrap_or(serde_json::Value::Null);
                    let thrones = crowns_obj.get("thrones").and_then(|v| v.as_array()).cloned().unwrap_or_default().into_iter().filter_map(|t| {
                        let st = t.get("state").or_else(|| t.get("kid")).map(|v| v.as_i64().map(|n| n.to_string()).or_else(|| v.as_str().map(str::to_string)).unwrap_or_default()).unwrap_or_default();
                        Some(crate::cards::ThroneEntry { state: st, badge: t.get("home").and_then(|v| v.as_bool()).filter(|b| *b).map(|_| "HOME".to_string()), terms: t.get("terms").and_then(|v| v.as_i64()).map(|n| format!("{n} term{}", if n==1 {""} else {"s"})), when: t.get("since").or_else(|| t.get("when")).and_then(|v| v.as_str()).map(str::to_string) })
                    }).collect::<Vec<_>>();
                    let reigns = crowns_obj.get("reigns").and_then(|v| v.as_array()).cloned().unwrap_or_default().into_iter().filter_map(|t| {
                        Some(crate::cards::ReignEntry { date: t.get("date").or_else(|| t.get("day")).and_then(|v| v.as_str()).unwrap_or("").to_string(), kind: t.get("kind").or_else(|| t.get("type")).and_then(|v| v.as_str()).unwrap_or("Reign").to_string(), state: format!("State {}", t.get("kid").or_else(|| t.get("state")).and_then(|v| v.as_i64()).unwrap_or(0)), delta: t.get("delta").and_then(|v| v.as_str()).map(str::to_string) })
                    }).collect::<Vec<_>>();
                    let card = crate::cards::CrownsCard {
                        name: session.name.clone(),
                        crowns: crowns_obj.get("count").and_then(|v| v.as_i64()).or_else(|| session.raw.get("crowns").and_then(|v| v.as_i64())),
                        terms: crowns_obj.get("terms").and_then(|v| v.as_i64()),
                        conquests: crowns_obj.get("conquests").and_then(|v| v.as_i64()),
                        states_ruled: crowns_obj.get("states_ruled").and_then(|v| v.as_i64()),
                        thrones,
                        reigns,
                        as_of: session.raw.get("updatedAt").and_then(|u| u.get("detail")).and_then(|v| v.as_i64()).map(|t| t.to_string()),
                    };
                    crate::cards::render_crowns_card(&card).ok()
                }
                _ => None,
            };
            return Ok(crate::lookup::panels::edit_player_v2(
                session,
                tab,
                session.notice.as_deref(),
                card_png,
            ));
        }
        Kind::Alliance => {
            let card_png = if tab == "overview" {
                let tag = session
                    .alliance
                    .clone()
                    .unwrap_or_else(|| "???".into());
                let name = session.name.clone();
                let members_n = session
                    .raw
                    .get("member_count")
                    .or_else(|| session.raw.get("members_count"))
                    .and_then(|v| v.as_i64())
                    .or_else(|| {
                        session
                            .raw
                            .get("members")
                            .or_else(|| session.raw.get("roster"))
                            .and_then(|v| v.as_array())
                            .map(|a| a.len() as i64)
                    });
                let roster: Vec<(String, Option<i64>, Option<String>)> = session
                    .raw
                    .get("members")
                    .or_else(|| session.raw.get("roster"))
                    .and_then(|v| v.as_array())
                    .map(|arr| {
                        arr.iter()
                            .take(6)
                            .map(|m| {
                                let n = m
                                    .get("name")
                                    .or_else(|| m.get("nick_name"))
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("?")
                                    .to_string();
                                let p = m.get("power").and_then(|v| v.as_i64());
                                let r = m
                                    .get("role")
                                    .and_then(|v| v.as_str())
                                    .map(str::to_string);
                                (n, p, r)
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let card = crate::cards::AllianceOverview {
                    tag,
                    name,
                    state_id: session.state,
                    leader: session
                        .raw
                        .get("leader")
                        .or_else(|| session.raw.get("r5"))
                        .and_then(|v| v.as_str())
                        .map(str::to_string),
                    leader_role: None,
                    power: session
                        .raw
                        .get("power")
                        .or_else(|| session.raw.get("total_power"))
                        .and_then(|v| v.as_i64()),
                    power_rank: session.raw.get("power_rank").and_then(|v| v.as_i64()),
                    kills: session
                        .raw
                        .get("kills")
                        .or_else(|| session.raw.get("total_kills"))
                        .and_then(|v| v.as_i64()),
                    kills_rank: session.raw.get("kills_rank").and_then(|v| v.as_i64()),
                    members: members_n,
                    member_max: session.raw.get("member_max").and_then(|v| v.as_i64()),
                    rank: session.raw.get("rank").and_then(|v| v.as_i64()),
                    level: session.raw.get("level").and_then(|v| v.as_i64()),
                    labyrinth: session.raw.get("labyrinth").and_then(|v| v.as_i64()),
                    lab_rank: session.raw.get("lab_rank").and_then(|v| v.as_i64()),
                    notice: session.notice.clone(),
                    roster,
                };
                crate::cards::render_alliance_overview_card(&card).ok()
            } else {
                None
            };
            return Ok(crate::lookup::panels::edit_alliance_v2(
                session,
                tab,
                session.notice.as_deref(),
                card_png,
            ));
        }
        Kind::State => {
            let raw = &session.raw;
            let kid = session.state.unwrap_or_else(|| raw.get("kid").and_then(|v| v.as_i64()).unwrap_or(0));
            let card_png = match tab {
                "overview" => {
                    let card = crate::cards::StateOverview {
                        kid,
                        players: raw.get("player_count").or_else(|| raw.get("players")).and_then(|v| v.as_i64()),
                        alliances: raw.get("alliance_count").or_else(|| raw.get("alliances")).and_then(|v| v.as_i64()),
                        power: raw.get("power").or_else(|| raw.get("total_power")).and_then(|v| v.as_i64()),
                        avg_power: raw.get("avg_power").and_then(|v| v.as_i64()),
                        top_power: raw.get("top_power").and_then(|v| v.as_i64()),
                        active_7d: raw.get("active_7d").and_then(|v| v.as_i64()),
                        health_grade: raw.get("health_grade").and_then(|v| v.as_str()).map(str::to_string),
                        health_blurb: raw.get("health_blurb").and_then(|v| v.as_str()).map(str::to_string),
                        health_components: None,
                    };
                    crate::cards::render_state_overview_card(&card).ok()
                }
                "svs" | "battle" => {
                    let opp = raw.get("matchup").and_then(|m| m.get("opponent")).or_else(|| raw.get("opponent"));
                    let them_kid = opp.and_then(|o| o.get("kid").or_else(|| o.get("state")).and_then(|v| v.as_i64()));
                    let rows = raw.get("matchup").and_then(|m| m.get("compare")).and_then(|v| v.as_array()).cloned().unwrap_or_default().into_iter().filter_map(|c| {
                        Some(crate::cards::StateVsRow {
                            label: c.get("label").or_else(|| c.get("field")).and_then(|v| v.as_str()).unwrap_or("—").to_string(),
                            us: c.get("us").map(|v| v.as_i64().map(|n| n.to_string()).or_else(|| v.as_str().map(str::to_string)).unwrap_or_else(|| v.to_string())),
                            them: c.get("them").map(|v| v.as_i64().map(|n| n.to_string()).or_else(|| v.as_str().map(str::to_string)).unwrap_or_else(|| v.to_string())),
                        })
                    }).collect::<Vec<_>>();
                    let card = crate::cards::StateVsCard {
                        season: raw.get("season").and_then(|v| v.as_i64()),
                        us: crate::cards::StateVsSide { kid: Some(kid), label: Some(format!("State {kid}")) },
                        them: crate::cards::StateVsSide { kid: them_kid, label: them_kid.map(|k| format!("State {k}")) },
                        rows,
                    };
                    crate::cards::render_state_vs_card(&card).ok()
                }
                "history" => {
                    let entries = raw.get("matchup_history").or_else(|| raw.get("history")).and_then(|v| v.as_array()).cloned().unwrap_or_default();
                    let rows = entries.iter().map(|e| crate::cards::MatchupRow {
                        date_label: e.get("date").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                        opponent_kid: e.get("opponent_kid").or_else(|| e.get("them_kid")).or_else(|| e.get("right_kid")).and_then(|v| v.as_i64()),
                        prep: e.get("prep").and_then(|v| v.as_str()).map(str::to_string),
                        castle: e.get("castle").and_then(|v| v.as_str()).map(str::to_string),
                        king_name: e.get("king_name").and_then(|v| v.as_str()).map(str::to_string),
                        king_tag: e.get("king_tag").and_then(|v| v.as_str()).map(str::to_string),
                        king_role: e.get("king_role").and_then(|v| v.as_str()).map(str::to_string),
                        high_king: e.get("high_king").and_then(|v| v.as_bool()).unwrap_or(false),
                    }).collect::<Vec<_>>();
                    let card = crate::cards::MatchupHistoryCard {
                        title: format!("State {kid} — Matchup history"),
                        castles_taken: raw.get("castles_taken").or_else(|| raw.get("taken")).and_then(|v| v.as_i64()),
                        castles_lost: raw.get("castles_lost").or_else(|| raw.get("lost")).and_then(|v| v.as_i64()),
                        rows,
                        as_of: None,
                    };
                    crate::cards::render_matchup_history_card(&card).ok()
                }
                "prep" => {
                    let days = raw.get("prep_days").or_else(|| raw.get("prep_points")).and_then(|v| v.as_array()).cloned().unwrap_or_default();
                    let mapped = days.iter().filter_map(|p| {
                        Some(crate::cards::PrepDay {
                            day: p.get("day").and_then(|v| v.as_i64()).unwrap_or(0),
                            home: p.get("home").or_else(|| p.get("us")).and_then(|v| v.as_f64()).unwrap_or(0.0),
                            away: p.get("away").or_else(|| p.get("them")).and_then(|v| v.as_f64()).unwrap_or(0.0),
                        })
                    }).collect::<Vec<_>>();
                    let opp_kid = raw.get("matchup").and_then(|m| m.get("opponent")).and_then(|o| o.get("kid")).and_then(|v| v.as_i64());
                    let card = crate::cards::PrepPointsCard {
                        us_kid: kid,
                        them_kid: opp_kid,
                        prep_us: raw.get("prep_us").and_then(|v| v.as_f64()),
                        prep_them: raw.get("prep_them").and_then(|v| v.as_f64()),
                        days: mapped,
                        as_of: None,
                    };
                    crate::cards::render_prep_points_card(&card).ok()
                }
                "appointments" => {
                    let ministers = raw.get("ministers").and_then(|v| v.as_array()).cloned().unwrap_or_default();
                    let offenders = raw.get("offenders").and_then(|v| v.as_array()).cloned().unwrap_or_default();
                    let map_seat = |m: &serde_json::Value| crate::cards::AppointmentSeat {
                        role: m.get("role").or_else(|| m.get("title")).and_then(|v| v.as_str()).unwrap_or("?").to_string(),
                        vacant: m.get("vacant").and_then(|v| v.as_bool()).unwrap_or_else(|| m.get("name").and_then(|v| v.as_str()).is_none()),
                        name: m.get("name").and_then(|v| v.as_str()).map(str::to_string),
                        alliance_tag: m.get("alliance_tag").or_else(|| m.get("abbr")).and_then(|v| v.as_str()).map(str::to_string),
                    };
                    let card = crate::cards::AppointmentsCard {
                        state_id: kid,
                        ministers: ministers.iter().map(map_seat).collect(),
                        offenders: offenders.iter().map(map_seat).collect(),
                        as_of: None,
                    };
                    crate::cards::render_appointments_card(&card).ok()
                }
                "map" => {
                    let map_src = raw.get("map").unwrap_or(raw);
                    let cities = map_src.get("cities").and_then(|v| v.as_array()).cloned().unwrap_or_default();
                    if cities.is_empty() { None } else {
                        let mut cities_out = Vec::new();
                        for c in cities.iter().take(50000) {
                            let x = c.get("x").and_then(|v| v.as_f64()).or_else(|| c.get("x").and_then(|v| v.as_i64()).map(|n| n as f64));
                            let y = c.get("y").and_then(|v| v.as_f64()).or_else(|| c.get("y").and_then(|v| v.as_i64()).map(|n| n as f64));
                            if let (Some(x), Some(y)) = (x,y) {
                                cities_out.push(crate::cards::MapCity { x, y, alliance_id: c.get("aid").or_else(|| c.get("alliance_id")).and_then(|v| v.as_i64().map(|n| n.to_string()).or_else(|| v.as_str().map(str::to_string))), label: c.get("nick_name").or_else(|| c.get("name")).and_then(|v| v.as_str()).map(str::to_string) });
                            }
                        }
                        let card = crate::cards::MapCard { title: format!("State {kid}"), subtitle: "Location data".into(), cities: cities_out, alliances: Vec::new(), highlight: None, focus_alliance_id: None, as_of: None };
                        crate::cards::render_map_card(&card).ok()
                    }
                }
                _ => None,
            };
            return Ok(crate::lookup::panels::edit_state_v2(
                session,
                tab,
                session.notice.as_deref(),
                card_png,
            ));
        }
    }
}

async fn lookup_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("lookup only works inside a server"))?;
    match action {
        "player_search" | "player:search" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "player_id",
                "Player ID or name",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("lookup:player:modal", "Search Player", inputs),
                )
                .await?;
            Ok(())
        }
        "alliance_search" | "alliance:search" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short("state_id", "State number")),
                CreateActionRow::InputText(
                    components::short("query", "Alliance tag or name (optional)").required(false),
                ),
            ];
            interaction
                .create_response(
                    &ctx.http,
                    modal("lookup:alliance:modal", "Search Alliance", inputs),
                )
                .await?;
            Ok(())
        }
        "state_search" | "state:search" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "state_id",
                "State number",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("lookup:state:modal", "Search State", inputs),
                )
                .await?;
            Ok(())
        }
        "leaderboard" => {
            let rows = db::players::page_for_guild(&data.db, guild_id, 10, 0).await?;
            let body = if rows.is_empty() {
                "_No tracked players yet._".to_string()
            } else {
                rows.iter()
                    .enumerate()
                    .map(|(index, row)| {
                        let medal = match index {
                            0 => icons::CROWN,
                            1 => icons::MEDAL,
                            2 => icons::BOLT,
                            _ => "▫️",
                        };
                        format!(
                            "{medal} `{:>2}.` **{}** · `{}`",
                            index + 1,
                            crate::error::truncate(row.label(), 28),
                            row.power
                                .map(theme::compact_number)
                                .unwrap_or_else(|| "—".into())
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
            };
            let embed = panels::paged_list(
                &format!("{} Power leaderboard", icons::CROWN),
                0,
                1,
                format!("{}\n{}", theme::DIVIDER, body),
            );
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        "refresh" => {
            let (embed, rows) = panels::lookup_public_panel();
            update_panel(ctx, data, interaction, embed, rows).await
        }
        other
            if other.starts_with("player:")
                || other.starts_with("alliance:")
                || other.starts_with("state:") =>
        {
            if other == "state:alliance:search" {
                let inputs = vec![
                    CreateActionRow::InputText(components::short("state_id", "State number")),
                    CreateActionRow::InputText(
                        components::short("query", "Alliance tag or name (optional)")
                            .required(false),
                    ),
                ];
                return interaction
                    .create_response(
                        &ctx.http,
                        modal("lookup:alliance:modal", "Search Alliance", inputs),
                    )
                    .await
                    .map_err(Into::into);
            }
            lookup_session_action(ctx, data, interaction, other).await
        }
        other => Err(anyhow::anyhow!("unknown lookup action `{other}`")),
    }
}

/// Handle tab switches and sub-views on a private Lookup result message.
async fn lookup_session_action(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    use crate::lookup::sessions::{self, Kind};
    let (kind, rest) = if let Some(rest) = action.strip_prefix("player:") {
        (Kind::Player, rest)
    } else if let Some(rest) = action.strip_prefix("alliance:") {
        (Kind::Alliance, rest)
    } else {
        (Kind::State, action.strip_prefix("state:").unwrap_or(action))
    };
    let user = interaction.user.id.get();
    let Some(mut session) = sessions::get(user, guild_id_of(interaction)) else {
        return reply(
            ctx,
            interaction,
            embeds::warn("Lookup expired", "Press **Search** to start a new lookup."),
            Vec::new(),
            true,
        )
        .await;
    };
    let value = match &interaction.data.kind {
        serenity::ComponentInteractionDataKind::StringSelect { values } => {
            values.first().cloned().unwrap_or_default()
        }
        _ => String::new(),
    };
    if kind == Kind::State && rest == "alliance" && !value.is_empty() {
        interaction.defer(&ctx.http).await?;
        let tag = crate::wos::normalize_alliance_tag(&value)
            .unwrap_or_else(|| value.trim().to_uppercase());
        let profile = data
            .lookup
            .alliance(&tag, session.state)
            .await
            .map_err(|err| anyhow::anyhow!("{}", crate::error::public(&err)))?;
        let selected_session = crate::lookup::sessions::LookupSession {
            kind: Kind::Alliance,
            raw: profile.raw.clone(),
            name: format!(
                "[{}] {}",
                profile.abbr,
                profile.name.as_deref().unwrap_or("Alliance")
            ),
            state: profile.state.or(session.state),
            fid: None,
            alliance: Some(profile.abbr),
            tab: "overview".into(),
            notice: None,
            choices: Vec::new(),
            board: None,
            page: 0,
            map_token: None,
            created: std::time::Instant::now(),
        };
        sessions::set(user, guild_id_of(interaction), selected_session.clone());
        let edit = match selected_session.kind {
            sessions::Kind::Player => {
                let card_png = {
                    let overview = overview_from_raw(&selected_session.raw);
                    crate::cards::render_player_overview_card(&overview).await.ok()
                };
                crate::lookup::panels::edit_player_v2(
                    &selected_session,
                    "overview",
                    selected_session.notice.as_deref(),
                    card_png,
                )
            }
            sessions::Kind::Alliance => crate::lookup::panels::edit_alliance_v2(
                &selected_session,
                "overview",
                selected_session.notice.as_deref(),
                None,
            ),
            sessions::Kind::State => crate::lookup::panels::edit_state_v2(
                &selected_session,
                "overview",
                selected_session.notice.as_deref(),
                None,
            ),
        };
        edit.apply(&ctx.http, interaction).await?;
        return Ok(());
    }
    if (rest == "player" || rest == "member") && !value.is_empty() {
        interaction.defer(&ctx.http).await?;
        let fid = value.trim().to_string();
        let profile = data
            .lookup
            .player(&fid)
            .await
            .map_err(|err| anyhow::anyhow!("{}", crate::error::public(&err)))?;
        let selected_session = crate::lookup::sessions::LookupSession {
            kind: Kind::Player,
            raw: profile.raw.clone(),
            name: profile.name.clone().unwrap_or_else(|| fid.clone()),
            state: profile.state,
            fid: profile.fid.clone().or(Some(fid)),
            alliance: profile.alliance_abbr.clone(),
            tab: "overview".into(),
            notice: None,
            choices: Vec::new(),
            board: None,
            page: 0,
            map_token: None,
            created: std::time::Instant::now(),
        };
        sessions::set(user, guild_id_of(interaction), selected_session.clone());
        let card_png = {
            let overview = overview_from_raw(&selected_session.raw);
            crate::cards::render_player_overview_card(&overview).await.ok()
        };
        let edit = crate::lookup::panels::edit_player_v2(
            &selected_session,
            "overview",
            selected_session.notice.as_deref(),
            card_png,
        );
        edit.apply(&ctx.http, interaction).await?;
        return Ok(());
    }
    if (rest == "candidate" || rest == "pick") && !value.is_empty() {
        interaction.defer(&ctx.http).await?;
        let selected_index = value
            .strip_prefix("candidate:")
            .and_then(|index| index.parse::<usize>().ok())
            .or_else(|| {
                // JS pick sends the actual value (fid/tag); resolve against choices
                session.choices.iter().position(|row| {
                    ["fid", "uid", "player_id", "id", "tag", "abbr", "alliance_abbr"]
                        .iter()
                        .any(|k| {
                            row.get(*k)
                                .and_then(|v| {
                                    v.as_str()
                                        .map(str::to_owned)
                                        .or_else(|| v.as_i64().map(|n| n.to_string()))
                                })
                                .is_some_and(|v| v.eq_ignore_ascii_case(value.trim()))
                        })
                })
            })
            .ok_or_else(|| anyhow::anyhow!("that Lookup result is no longer available"))?;
        let selected = session
            .choices
            .get(selected_index)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("that Lookup result is no longer available"))?;
        let selected_session = match kind {
            Kind::Player => {
                let fid = ["fid", "uid", "player_id", "id"]
                    .iter()
                    .find_map(|key| {
                        selected.get(*key).and_then(|v| {
                            v.as_str()
                                .map(str::to_owned)
                                .or_else(|| v.as_i64().map(|n| n.to_string()))
                        })
                    })
                    .ok_or_else(|| anyhow::anyhow!("that Player result has no player ID"))?;
                let profile = data
                    .lookup
                    .player(&fid)
                    .await
                    .map_err(|err| anyhow::anyhow!("{}", crate::error::public(&err)))?;
                crate::lookup::sessions::LookupSession {
                    kind,
                    raw: profile.raw.clone(),
                    name: profile.name.clone().unwrap_or_else(|| fid.clone()),
                    state: profile.state,
                    fid: profile.fid.clone().or(Some(fid)),
                    alliance: profile.alliance_abbr.clone(),
                    tab: "overview".into(),
                    notice: None,
                    choices: Vec::new(),
                    board: None,
                    page: 0,
                    map_token: None,
                    created: std::time::Instant::now(),
                }
            }
            Kind::Alliance => {
                let raw_tag = ["tag", "abbr", "alliance_abbr"]
                    .iter()
                    .find_map(|key| selected.get(*key).and_then(serde_json::Value::as_str))
                    .ok_or_else(|| anyhow::anyhow!("that Alliance result has no alliance tag"))?;
                let tag = crate::wos::normalize_alliance_tag(raw_tag)
                    .unwrap_or_else(|| raw_tag.trim().to_uppercase());
                // The search result is already a usable profile. A second detail
                // lookup can 404 (stale search index, renamed tag, kid mismatch),
                // so fall back to the selected row instead of failing the click.
                let profile = match data.lookup.alliance(&tag, session.state).await {
                    Ok(profile) => profile,
                    Err(err) => {
                        tracing::debug!(error = %err, %tag, "alliance detail lookup failed; using selected search result");
                        crate::lookup::AllianceProfile::from_value(&tag, &selected)
                    }
                };
                crate::lookup::sessions::LookupSession {
                    kind,
                    raw: profile.raw.clone(),
                    name: format!(
                        "[{}] {}",
                        profile.abbr,
                        profile.name.as_deref().unwrap_or("Alliance")
                    ),
                    state: profile.state.or(session.state),
                    fid: None,
                    alliance: Some(profile.abbr),
                    tab: "overview".into(),
                    notice: None,
                    choices: Vec::new(),
                    board: None,
                    page: 0,
                    map_token: None,
                    created: std::time::Instant::now(),
                }
            }
            Kind::State => return Err(anyhow::anyhow!("unexpected state result picker")),
        };
        sessions::set(user, guild_id_of(interaction), selected_session.clone());
        let edit = match selected_session.kind {
            sessions::Kind::Player => {
                let card_png = {
                    let overview = overview_from_raw(&selected_session.raw);
                    crate::cards::render_player_overview_card(&overview).await.ok()
                };
                crate::lookup::panels::edit_player_v2(
                    &selected_session,
                    "overview",
                    selected_session.notice.as_deref(),
                    card_png,
                )
            }
            sessions::Kind::Alliance => crate::lookup::panels::edit_alliance_v2(
                &selected_session,
                "overview",
                selected_session.notice.as_deref(),
                None,
            ),
            sessions::Kind::State => crate::lookup::panels::edit_state_v2(
                &selected_session,
                "overview",
                selected_session.notice.as_deref(),
                None,
            ),
        };
        edit.apply(&ctx.http, interaction).await?;
        return Ok(());
    }
    if rest.starts_with("pg:p:") || rest.starts_with("page:p:") {
        let tail = rest
            .strip_prefix("pg:p:")
            .or_else(|| rest.strip_prefix("page:p:"))
            .unwrap_or("");
        let parts: Vec<&str> = tail.split(':').collect();
        // JS: p:<target>:<tag>, old Rust: p:<tag>:<target>, simple: p:prev|next
        if let Some(n) = parts.first().and_then(|v| v.parse::<usize>().ok()) {
            session.page = n;
        } else if let Some(n) = parts.get(1).and_then(|v| v.parse::<usize>().ok()) {
            session.page = n;
        } else {
            session.page = match parts.first().copied().unwrap_or("") {
                "prev" => session.page.saturating_sub(1),
                "next" => session.page.saturating_add(1),
                "first" => 0,
                "last" => usize::MAX / 4, // clamped during render
                _ => session.page,
            };
        }
    }
    if rest.starts_with("tl:pg:p:") {
        let tail = rest.strip_prefix("tl:pg:p:").unwrap_or("");
        let parts: Vec<&str> = tail.split(':').collect();
        if let Some(n) = parts.first().and_then(|v| v.parse::<usize>().ok()) {
            session.page = n;
        } else if let Some(n) = parts.get(1).and_then(|v| v.parse::<usize>().ok()) {
            session.page = n;
        } else {
            session.page = match parts.first().copied().unwrap_or("") {
                "prev" => session.page.saturating_sub(1),
                "next" => session.page.saturating_add(1),
                "first" => 0,
                "last" => usize::MAX / 4,
                _ => session.page,
            };
        }
    }
    if rest == "board" || rest == "sort" || rest == "board:state" || rest == "board:global" {
        // board: rankings board key; sort: alliance members sort key (power|furnace|role|name)
        if !value.is_empty() {
            session.board = Some(value.clone());
            session.page = 0;
        }
    }
    let mut already_deferred = false;
    if rest == "go:state" {
        if let Some(state_id) = session.state {
            if !already_deferred {
                interaction.defer(&ctx.http).await?;
                already_deferred = true;
            }
            if let Ok(profile) = data.lookup.state(state_id).await {
                let state_session = crate::lookup::sessions::LookupSession {
                    kind: Kind::State,
                    raw: profile.raw.clone(),
                    name: format!("State #{state_id}"),
                    state: Some(state_id),
                    fid: None,
                    alliance: None,
                    tab: "overview".into(),
                    notice: None,
                    choices: Vec::new(),
                    board: None,
                    page: 0,
                    map_token: None,
                    created: std::time::Instant::now(),
                };
                sessions::set(user, guild_id_of(interaction), state_session.clone());
                let edit = crate::lookup::panels::edit_state_v2(
                    &state_session,
                    "overview",
                    state_session.notice.as_deref(),
                    None,
                );
                edit.apply(&ctx.http, interaction).await?;
                return Ok(());
            }
        }
    }
    if rest == "go:alliance" {
        if let Some(tag) = session.alliance.clone() {
            if !already_deferred {
                interaction.defer(&ctx.http).await?;
                already_deferred = true;
            }
            let tag = crate::wos::normalize_alliance_tag(&tag).unwrap_or_else(|| tag.to_uppercase());
            let profile = data
                .lookup
                .alliance(&tag, session.state)
                .await
                .ok();
            if let Some(profile) = profile {
                let alliance_session = crate::lookup::sessions::LookupSession {
                    kind: Kind::Alliance,
                    raw: profile.raw.clone(),
                    name: format!(
                        "[{}] {}",
                        profile.abbr,
                        profile.name.as_deref().unwrap_or("Alliance")
                    ),
                    state: profile.state.or(session.state),
                    fid: None,
                    alliance: Some(profile.abbr),
                    tab: "overview".into(),
                    notice: None,
                    choices: Vec::new(),
                    board: None,
                    page: 0,
                    map_token: None,
                    created: std::time::Instant::now(),
                };
                sessions::set(user, guild_id_of(interaction), alliance_session.clone());
                let edit = crate::lookup::panels::edit_alliance_v2(
                    &alliance_session,
                    "overview",
                    alliance_session.notice.as_deref(),
                    None,
                );
                edit.apply(&ctx.http, interaction).await?;
                return Ok(());
            }
        }
    }

    let tab = if let Some(tab) = rest.strip_prefix("tab:") {
        if tab == "joined" { "members".to_string() } else { tab.to_string() }
    } else if rest == "tab" {
        value
    } else {
        match rest {
            "go:map" => "map".to_string(),
            "go:trail" => "trail".to_string(),
            "go:appointments" => "appointments".to_string(),
            "go:battle" | "battle" => "svs".to_string(),
            "go:prep" | "prep" => "prep".to_string(),
            "go:history" | "history" => "history".to_string(),
            "go:president" => "overview".to_string(),
            "map:back" | "overview:back" | "tl:back" | "svs:back" | "prep:back" | "history:back" => {
                "overview".to_string()
            }
            "map:refresh" => {
                if let Some(state) = session.state {
                    interaction.defer(&ctx.http).await?;
                    already_deferred = true;
                    session.notice = Some("Requesting the state map refresh…".to_string());
                    sessions::set(user, guild_id_of(interaction), session.clone());
                    let token = session
                        .map_token
                        .clone()
                        .unwrap_or_else(|| format!("t_bot_{:x}", rand::random::<u64>()));
                    session.map_token = Some(token.clone());
                    let status = data.lookup.map_update_status(state, &token).await.ok();
                    let active = |v: &serde_json::Value| {
                        lookup_response_data(v)
                            .get("job")
                            .and_then(|j| j.get("status"))
                            .and_then(serde_json::Value::as_str)
                            .is_some_and(|s| matches!(s, "queued" | "running"))
                    };
                    let paused = status
                        .as_ref()
                        .map(lookup_response_data)
                        .and_then(|v| v.get("updates_paused"))
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(false);
                    let existing = status.as_ref().is_some_and(active);
                    let cooldown = status
                        .as_ref()
                        .map(lookup_response_data)
                        .and_then(|v| v.get("cooldown_remaining_sec"))
                        .and_then(serde_json::Value::as_i64)
                        .unwrap_or(0);
                    if status.is_none() {
                        session.notice =
                            Some("The map service is not responding right now.".into());
                    } else if paused {
                        session.notice = Some("Map updates are paused right now.".into());
                    } else if !existing
                        && (cooldown > 0
                            || status
                                .as_ref()
                                .map(lookup_response_data)
                                .and_then(|v| v.get("update_available"))
                                .and_then(serde_json::Value::as_bool)
                                == Some(false))
                    {
                        session.notice = Some(if cooldown > 0 {
                            format!("The map was updated recently — try again in {cooldown}s.")
                        } else {
                            "The map was updated recently — try again later.".into()
                        });
                    } else {
                        let before = status
                            .as_ref()
                            .map(lookup_response_data)
                            .and_then(|v| v.get("last_finished_at"))
                            .and_then(serde_json::Value::as_i64)
                            .unwrap_or(0);
                        if !existing {
                            match data.lookup.request_map_update(state, &token).await {
                                Ok(response) => {
                                    let response = lookup_response_data(&response);
                                    if let Some(new_token) = response
                                        .get("request_token")
                                        .and_then(serde_json::Value::as_str)
                                    {
                                        session.map_token = Some(new_token.to_string());
                                    }
                                    if let Some(error) =
                                        response.get("error").and_then(serde_json::Value::as_str)
                                    {
                                        session.notice = Some(
                                            response
                                                .get("message")
                                                .and_then(serde_json::Value::as_str)
                                                .unwrap_or(error)
                                                .to_string(),
                                        );
                                    } else if response
                                        .get("ok")
                                        .and_then(serde_json::Value::as_bool)
                                        == Some(false)
                                    {
                                        session.notice = Some(
                                            response
                                                .get("detail")
                                                .and_then(serde_json::Value::as_str)
                                                .unwrap_or("The map update could not be started.")
                                                .to_string(),
                                        );
                                    }
                                }
                                Err(err) => {
                                    session.notice = Some(format!(
                                        "Map refresh request failed: {}",
                                        crate::error::public(&err)
                                    ))
                                }
                            }
                        }
                        if session
                            .notice
                            .as_deref()
                            .is_none_or(|n| n == "Requesting the state map refresh…")
                        {
                            let deadline =
                                tokio::time::Instant::now() + std::time::Duration::from_secs(40);
                            let mut finished = false;
                            while tokio::time::Instant::now() < deadline {
                                tokio::time::sleep(std::time::Duration::from_millis(2500)).await;
                                if let Ok(next) = data
                                    .lookup
                                    .map_update_status(
                                        state,
                                        session.map_token.as_deref().unwrap_or(&token),
                                    )
                                    .await
                                {
                                    let next = lookup_response_data(&next);
                                    let job = next
                                        .get("job")
                                        .and_then(|j| j.get("status"))
                                        .and_then(serde_json::Value::as_str)
                                        .unwrap_or("");
                                    let finished_at = next
                                        .get("last_finished_at")
                                        .and_then(serde_json::Value::as_i64)
                                        .unwrap_or(0);
                                    if !matches!(job, "queued" | "running")
                                        && (existing || finished_at > before || job == "done")
                                    {
                                        finished = true;
                                        break;
                                    }
                                }
                            }
                            if finished {
                                data.lookup.invalidate_state_map(state);
                                session.notice = Some("Map refresh finished; showing the latest available location data.".into());
                            } else {
                                session.notice = Some("The map is still updating or its status could not be confirmed. Try again shortly.".into());
                            }
                        }
                    }
                }
                "map".to_string()
            }
            "tl:refresh" => "troopLevel".to_string(),
            "go:state" | "go:alliance" | "player" | "alliance" | "sort" | "pg" | "tl:pg" => {
                session.tab.clone()
            }
            "board" => "boards".to_string(),
            other if other.starts_with("pg:p:") || other.starts_with("tl:pg:p:") => {
                session.tab.clone()
            }
            _ => session.tab.clone(),
        }
    };
    let tab = if sessions::tabs(kind).iter().any(|(key, _)| *key == tab)
        || matches!(
            tab.as_str(),
            "map" | "trail" | "history" | "battle" | "prep" | "note" | "appointments"
        )
    {
        tab
    } else {
        "overview".to_string()
    };
    session.tab = tab.clone();
    sessions::set(user, guild_id_of(interaction), session.clone());
    if !already_deferred {
        interaction.defer(&ctx.http).await?;
    }
    let edit = lookup_view_edit(ctx, data, &session, &tab).await?;
    edit.apply(&ctx.http, interaction).await?;
    Ok(())
}

fn guild_id_of(interaction: &ComponentInteraction) -> u64 {
    interaction.guild_id.map(|id| id.get()).unwrap_or(0)
}

fn lookup_response_data(value: &serde_json::Value) -> &serde_json::Value {
    value.get("data").unwrap_or(value)
}

// ------------------------------------------------------------------ oracle

// ------------------------------------------------------------- giveaway

async fn giveaway_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let mut parts = action.split(':');
    let kind = parts.next().unwrap_or("");
    let id: i64 = parts
        .next()
        .ok_or_else(|| anyhow::anyhow!("missing giveaway id"))?
        .parse()?;
    let guild_id = interaction.guild_id.map(|id| id.get()).unwrap_or(0);
    match kind {
        "enter" => {
            let giveaway = db::giveaways::get(&data.db, id)
                .await?
                .ok_or_else(|| anyhow::anyhow!("no giveaway with id {id}"))?;
            if giveaway.guild_id != guild_id.to_string() {
                return Err(anyhow::anyhow!("giveaway belongs to another server"));
            }
            if !giveaway.is_active() {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn("Giveaway ended", format!("Giveaway #{id} is over.")),
                    Vec::new(),
                    true,
                )
                .await;
            }
            if giveaway.ends_at <= db::now() * 1000 {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn("Giveaway ended", format!("Giveaway #{id} is over.")),
                    Vec::new(),
                    true,
                )
                .await;
            }
            if let Some(role_id) = giveaway.required_role_id() {
                let has_role = interaction
                    .member
                    .as_ref()
                    .map(|member| member.roles.iter().any(|id| id.get() == role_id))
                    .unwrap_or(false);
                if !has_role {
                    return reply(
                        ctx,
                        interaction,
                        embeds::error(
                            "Not eligible",
                            format!("You need <@&{role_id}> to enter this giveaway."),
                        ),
                        Vec::new(),
                        true,
                    )
                    .await;
                }
            }
            let Some(member) = interaction.member.as_ref() else {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn("Not in the server", "You must be a member to enter."),
                    Vec::new(),
                    true,
                )
                .await;
            };
            if let Some(member) = interaction.member.as_ref() {
                if let Err(reason) =
                    crate::commands::giveaways::check_eligibility(data, &giveaway, member).await
                {
                    return reply(
                        ctx,
                        interaction,
                        embeds::error("Not eligible", reason),
                        Vec::new(),
                        true,
                    )
                    .await;
                }
            }
            let added = db::giveaways::add_entry(&data.db, id, interaction.user.id.get()).await?;
            if added {
                crate::commands::giveaways::schedule_entry_refresh(ctx.clone(), data.clone(), id);
                let rules = giveaway.rules();
                let weight = crate::commands::giveaways::weight_of(
                    data,
                    &giveaway,
                    &rules,
                    Some(member),
                    interaction.user.id.get(),
                )
                .await;
                let bonus = if weight > 1 {
                    format!(" You hold **{weight} entries** thanks to bonuses.")
                } else {
                    String::new()
                };
                reply(
                    ctx,
                    interaction,
                    embeds::ok(format!("✅ You're in!{bonus} Good luck 🍀")),
                    Vec::new(),
                    true,
                )
                .await
            } else {
                reply(
                    ctx,
                    interaction,
                    embeds::info(
                        "Already entered",
                        format!("You're already entered. Want to leave giveaway #{id}?"),
                    ),
                    vec![components::row(vec![components::danger(
                        format!("giveaway:leave:{id}"),
                        "Leave Giveaway",
                    )])],
                    true,
                )
                .await
            }
        }
        "leave" => {
            let giveaway = db::giveaways::get(&data.db, id)
                .await?
                .ok_or_else(|| anyhow::anyhow!("no giveaway with id {id}"))?;
            if giveaway.guild_id != guild_id.to_string() {
                return Err(anyhow::anyhow!("giveaway belongs to another server"));
            }
            if !giveaway.is_active() || giveaway.ends_at <= db::now() * 1000 {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn("Giveaway ended", format!("Giveaway #{id} is over.")),
                    Vec::new(),
                    true,
                )
                .await;
            }
            db::giveaways::remove_entry(&data.db, id, interaction.user.id.get()).await?;
            crate::commands::giveaways::schedule_entry_refresh(ctx.clone(), data.clone(), id);
            reply(
                ctx,
                interaction,
                embeds::ok(format!("You left giveaway #{id}.")),
                Vec::new(),
                true,
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown giveaway action `{other}`")),
    }
}

// ------------------------------------------------------------- player ids

async fn playerid_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("Player IDs only work inside a server"))?;
    let user_id = interaction.user.id.get();

    match action {
        "deploy" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let inputs = vec![CreateActionRow::InputText(components::short(
                "channel",
                "Public text or announcement channel ID",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("player:deploy_modal", "Deploy Player ID panel", inputs),
                )
                .await?;
            Ok(())
        }
        "register" => {
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "player:register_modal",
                        "Register my Play ID(s)",
                        vec![
                            CreateActionRow::InputText(
                                components::paragraph("fids", "Player ID(s) — comma-separated")
                                    .placeholder("e.g. 123456789, 987654321")
                                    .max_length(500),
                            ),
                            CreateActionRow::InputText(
                                components::short("state", "State (digits only, all IDs)")
                                    .placeholder("e.g. 3105")
                                    .max_length(6),
                            ),
                        ],
                    ),
                )
                .await?;
            Ok(())
        }
        "nickname" => {
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "player:nickname_modal",
                        "Set My In-Game Nickname",
                        vec![
                            CreateActionRow::InputText(
                                components::short("alliance", "Alliance Tag (3 letters)")
                                    .max_length(3),
                            ),
                            CreateActionRow::InputText(
                                components::short("name", "Player Name").max_length(32),
                            ),
                            CreateActionRow::InputText(
                                components::short("rank", "Rank (R1–R5)").max_length(2),
                            ),
                        ],
                    ),
                )
                .await?;
            Ok(())
        }
        "remove" => {
            let players = db::players::for_user(&data.db, guild_id, user_id).await?;
            let options: Vec<serenity::CreateSelectMenuOption> = players
                .iter()
                .map(|player| {
                    serenity::CreateSelectMenuOption::new(
                        format!("{} · {}", player.fid, player.label())
                            .chars()
                            .take(100)
                            .collect::<String>(),
                        player.fid.clone(),
                    )
                })
                .collect();
            if options.is_empty() {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn(
                        "No linked IDs",
                        "You have no Player IDs registered in this server.",
                    ),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let menu = serenity::CreateSelectMenu::new(
                "player:remove_select",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Pick IDs to remove…")
            .min_values(1)
            .max_values(25);
            reply(
                ctx,
                interaction,
                embeds::info(
                    "Remove my ID",
                    "Select the Player IDs you added. Redemption history is kept.",
                ),
                vec![CreateActionRow::SelectMenu(menu)],
                true,
            )
            .await
        }
        "remove_select" => {
            let fids = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values.clone(),
                _ => Vec::new(),
            };
            let owned: Vec<String> = db::players::for_user(&data.db, guild_id, user_id)
                .await?
                .into_iter()
                .map(|player| player.fid)
                .collect();
            let valid: Vec<String> = fids.into_iter().filter(|fid| owned.contains(fid)).collect();
            if valid.is_empty() {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("one of your linked IDs"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let mut rows = Vec::new();
            for fid in valid.iter().take(5) {
                rows.push(CreateActionRow::Buttons(vec![
                    components::danger(format!("player:rmgo:{fid}"), format!("🗑️ Remove {fid}")),
                    components::secondary("player:remove", "Cancel"),
                ]));
            }
            reply(
                ctx,
                interaction,
                embeds::warn(
                    "Confirm removal",
                    format!(
                        "Remove {} selected ID(s)? Past redemption history is kept.",
                        valid.len()
                    ),
                ),
                rows,
                true,
            )
            .await
        }
        other if other.starts_with("rmgo:") => {
            let fid = other["rmgo:".len()..].to_string();
            let owned = db::players::for_user(&data.db, guild_id, user_id)
                .await?
                .iter()
                .any(|player| player.fid == fid);
            if !owned {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("one of your linked IDs"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            db::players::remove(&data.db, &fid).await?;
            reply(
                ctx,
                interaction,
                embeds::ok(format!(
                    "`{fid}` was unlinked. Redemption history was kept."
                )),
                Vec::new(),
                true,
            )
            .await
        }
        "codes" => {
            let players = db::players::for_user(&data.db, guild_id, user_id).await?;
            let mut lines = Vec::new();
            for player in &players {
                let rows = db::giftcodes::statuses_for_code(&data.db, &player.fid).await?;
                if rows.is_empty() {
                    continue;
                }
                lines.push(format!(
                    "🪪 `{}` — {}",
                    player.fid,
                    rows.iter()
                        .map(|(code, status)| format!("`{code}`: {status}"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ));
            }
            let embed = embeds::brand("🎁 My Gift Codes")
                .color(colors::GOLD)
                .description(if lines.is_empty() {
                    "_No codes redeemed yet._".to_string()
                } else {
                    lines.join("\n")
                })
                .footer(serenity::CreateEmbedFooter::new(theme::footer()));
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        "translate" => {
            let lang = db::translate::get_user_lang(&data.db, Some(guild_id), user_id).await;
            let (embed, rows) =
                crate::playerid::translated_menu(data, guild_id, user_id, &lang).await;
            reply(ctx, interaction, embed, rows, true).await
        }
        "tr_lang" => {
            let lang = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().cloned().unwrap_or_else(|| "en".to_string())
                }
                _ => "en".to_string(),
            };
            let lang = if crate::translate::is_supported_lang(&lang) {
                lang
            } else {
                "en".to_string()
            };
            let _ = db::translate::set_user_lang(&data.db, Some(guild_id), user_id, &lang).await;
            interaction.defer(&ctx.http).await?;
            let (embed, rows) =
                crate::playerid::translated_menu(data, guild_id, user_id, &lang).await;
            interaction
                .edit_response(
                    &ctx.http,
                    EditInteractionResponse::new().embed(embed).components(rows),
                )
                .await?;
            Ok(())
        }
        "list" | "add" | "remove_admin" | "claims" | "limits" | "rolecap" | "usercap"
        | "overcap" | "export" | "refresh" | "oracle_import" | "refresh_roster"
        | "roster_schedule" | "oracle_roster" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            match action {
                "roster_schedule" => {
                    let hours = db::settings::get(
                        &data.db,
                        guild_id,
                        db::settings::keys::PLAYER_ROSTER_REFRESH_HOURS,
                    )
                    .await?
                    .unwrap_or_else(|| "0".into());
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                "player:roster_schedule_modal",
                                "Scheduled roster refresh",
                                vec![CreateActionRow::InputText(
                                    components::short(
                                        "hours",
                                        "Hours between refreshes (0 disables)",
                                    )
                                    .value(hours),
                                )],
                            ),
                        )
                        .await?;
                    Ok(())
                }
                "oracle_import" => {
                    if !data.oracle.is_configured().await {
                        return reply(
                            ctx,
                            interaction,
                            embeds::warn(
                                "Oracle not connected",
                                "Ask the Bot Owner to connect or refresh the Oracle session.",
                            ),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                "player:oracle_import_modal",
                                "Oracle Lookup / Import",
                                vec![CreateActionRow::InputText(
                                    components::paragraph(
                                        "fids",
                                        "Player IDs, separated by commas or spaces",
                                    )
                                    .max_length(2000),
                                )],
                            ),
                        )
                        .await?;
                    Ok(())
                }
                "oracle_roster" => {
                    if !data.oracle.is_configured().await {
                        return reply(
                            ctx,
                            interaction,
                            embeds::warn(
                                "Oracle not connected",
                                "Ask the Bot Owner to connect or refresh the Oracle session.",
                            ),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    let inputs = vec![
                        CreateActionRow::InputText(
                            components::short("state", "State number (kid)").max_length(8),
                        ),
                        CreateActionRow::InputText(
                            components::short(
                                "alliance",
                                "Alliance tag or ID (blank imports state roster)",
                            )
                            .required(false)
                            .max_length(32),
                        ),
                    ];
                    interaction
                        .create_response(
                            &ctx.http,
                            modal("player:oracle_roster_modal", "Import Oracle roster", inputs),
                        )
                        .await?;
                    Ok(())
                }
                "refresh_roster" => {
                    if !data.oracle.is_configured().await {
                        return reply(
                            ctx,
                            interaction,
                            embeds::warn(
                                "Oracle not connected",
                                "Ask the Bot Owner to connect or refresh the Oracle session.",
                            ),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    let players = db::players::list_for_guild(&data.db, guild_id).await?;
                    if players.is_empty() {
                        return reply(
                            ctx,
                            interaction,
                            embeds::info(
                                "Roster is empty",
                                "There are no Player IDs in this server to refresh.",
                            ),
                            Vec::new(),
                            true,
                        )
                        .await;
                    }
                    interaction
                        .create_response(
                            &ctx.http,
                            CreateInteractionResponse::Defer(
                                CreateInteractionResponseMessage::new().ephemeral(true),
                            ),
                        )
                        .await?;
                    let total = players.len();
                    let mut updated = 0usize;
                    let mut failed = Vec::new();
                    for (index, player) in players.iter().enumerate() {
                        match data.oracle.fetch_player(&player.fid).await {
                            Ok(value) => {
                                let enrichment = crate::oracle::enrichment_from_player(&value);
                                if db::players::apply_enrichment(&data.db, &player.fid, &enrichment)
                                    .await
                                    .is_ok()
                                {
                                    updated += 1;
                                } else {
                                    failed.push(player.fid.clone());
                                }
                            }
                            Err(_) => failed.push(player.fid.clone()),
                        }
                        if index % 3 == 0 || index + 1 == total {
                            let content = format!("Refreshing roster… **{}/{}** checked · **{updated}** updated · **{}** failed", index + 1, total, failed.len());
                            let _ = interaction
                                .edit_response(
                                    &ctx.http,
                                    EditInteractionResponse::new().content(content),
                                )
                                .await;
                        }
                        if index + 1 < total {
                            tokio::time::sleep(std::time::Duration::from_millis(400)).await;
                        }
                    }
                    let sample = failed
                        .iter()
                        .take(10)
                        .map(|fid| format!("`{fid}`"))
                        .collect::<Vec<_>>()
                        .join(", ");
                    let suffix = if sample.is_empty() {
                        String::new()
                    } else {
                        format!("\nFailed FIDs: {sample}")
                    };
                    db::settings::set(
                        &data.db,
                        guild_id,
                        db::settings::keys::PLAYER_ROSTER_LAST_REFRESH,
                        Some(&db::now().to_string()),
                    )
                    .await?;
                    interaction.edit_response(&ctx.http, EditInteractionResponse::new().content(format!("Roster refresh complete: **{updated}** updated · **{}** failed · **{total}** checked.{suffix}", failed.len()))).await?;
                    Ok(())
                }
                "add" => {
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                "player:add_modal",
                                "Batch add Player IDs",
                                vec![
                                    CreateActionRow::InputText(
                                        components::paragraph("fids", "Player IDs").max_length(500),
                                    ),
                                    CreateActionRow::InputText(
                                        components::short("state", "State (digits)").max_length(6),
                                    ),
                                ],
                            ),
                        )
                        .await?;
                    Ok(())
                }
                "claims" => {
                    let claims =
                        db::player_limits::list_pending_for_guild(&data.db, guild_id).await?;
                    let body = if claims.is_empty() {
                        "_No pending claims._".to_string()
                    } else {
                        claims
                            .iter()
                            .map(|claim| {
                                format!(
                                    "`{}` → <@{}> (current owner <@{}>)",
                                    claim.fid,
                                    claim.requesting_user_id,
                                    claim.current_owner_id.as_deref().unwrap_or("none")
                                )
                            })
                            .collect::<Vec<_>>()
                            .join("\n")
                    };
                    let mut rows: Vec<CreateActionRow> = Vec::new();
                    for claim in claims.iter().take(5) {
                        rows.push(CreateActionRow::Buttons(vec![
                            components::success(
                                format!("player:claim_approve:{}", claim.id),
                                format!("✅ Approve {}", claim.fid),
                            ),
                            components::danger(
                                format!("player:claim_deny:{}", claim.id),
                                format!("⛔ Deny {}", claim.fid),
                            ),
                        ]));
                    }
                    let embed = embeds::brand("⏳ Pending ID claims")
                        .color(colors::WARNING)
                        .description(body)
                        .footer(serenity::CreateEmbedFooter::new(theme::footer()));
                    reply(ctx, interaction, embed, rows, true).await
                }
                "limits" => {
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                "player:limits_modal",
                                "Player ID caps",
                                vec![
                                    CreateActionRow::InputText(
                                        components::short("base", "Base cap").max_length(3),
                                    ),
                                    CreateActionRow::InputText(
                                        components::short("booster", "Server Booster cap")
                                            .max_length(3),
                                    ),
                                ],
                            ),
                        )
                        .await?;
                    Ok(())
                }
                "rolecap" => {
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                "player:rolecap_modal",
                                "Role ID cap",
                                vec![
                                    CreateActionRow::InputText(
                                        components::short("role", "Role ID").max_length(20),
                                    ),
                                    CreateActionRow::InputText(
                                        components::short("cap", "Cap (0 removes)").max_length(3),
                                    ),
                                ],
                            ),
                        )
                        .await?;
                    Ok(())
                }
                "usercap" => {
                    interaction
                        .create_response(
                            &ctx.http,
                            modal(
                                "player:usercap_modal",
                                "User ID cap override",
                                vec![
                                    CreateActionRow::InputText(
                                        components::short("user", "User ID").max_length(20),
                                    ),
                                    CreateActionRow::InputText(
                                        components::short("cap", "Cap (0 removes)").max_length(3),
                                    ),
                                ],
                            ),
                        )
                        .await?;
                    Ok(())
                }
                "overcap" => {
                    let mut lines = Vec::new();
                    let members: Vec<u64> = ctx
                        .cache
                        .guild(serenity::GuildId::new(guild_id))
                        .map(|guild| {
                            guild
                                .members
                                .values()
                                .take(200)
                                .map(|member| member.user.id.get())
                                .collect()
                        })
                        .unwrap_or_default();
                    for user in members {
                        let used = db::players::count_by_user(&data.db, user).await?;
                        if used == 0 {
                            continue;
                        }
                        let limit =
                            crate::playerid::effective_limit(ctx, data, guild_id, user).await;
                        if used > limit.cap {
                            lines.push(format!("<@{user}> — {}/{}", used, limit.cap));
                        }
                    }
                    let embed = embeds::brand("⚠️ Members over their ID cap")
                        .description(if lines.is_empty() {
                            "_Nobody is over their cap._".to_string()
                        } else {
                            lines.join("\n")
                        })
                        .footer(serenity::CreateEmbedFooter::new(theme::footer()));
                    reply(ctx, interaction, embed, Vec::new(), true).await
                }
                "refresh" => {
                    let (embed, rows) =
                        crate::ui::panels::settings_hub(&crate::ui::panels::SettingsContext {
                            guild_name: "this server".to_string(),
                            player_ids: db::players::stats(&data.db, guild_id).await?.tracked,
                            player_limit: db::subscriptions::player_id_limit(&data.db, guild_id)
                                .await
                                .ok()
                                .flatten(),
                            music_configured: false,
                            lookup_configured: false,
                            gift_sync: None,
                            oracle_ready: false,
                            uptime: data.uptime(),
                            latency_ms: 0,
                            is_owner: false,
                            official_guild: false,
                        });
                    update_panel(ctx, data, interaction, embed, rows).await
                }
                "export" => {
                    let players = db::players::list_for_guild(&data.db, guild_id).await?;
                    let body = players
                        .iter()
                        .map(|p| {
                            format!(
                                "{},{}",
                                p.fid,
                                p.state.map(|s| s.to_string()).unwrap_or_default()
                            )
                        })
                        .collect::<Vec<_>>()
                        .join("\r\n");
                    let csv = format!("fid,state\r\n{body}\r\n");
                    interaction
                        .create_response(
                            &ctx.http,
                            CreateInteractionResponse::Message(
                                CreateInteractionResponseMessage::new()
                                    .content(format!(
                                        "Player ID export · {} record(s)",
                                        players.len()
                                    ))
                                    .add_file(serenity::CreateAttachment::bytes(
                                        csv.into_bytes(),
                                        format!("player_ids_{guild_id}.csv"),
                                    ))
                                    .ephemeral(true),
                            ),
                        )
                        .await?;
                    Ok(())
                }
                _ => {
                    reply(
                        ctx,
                        interaction,
                        embeds::warn(
                            "Player removal",
                            "Use the Remove my ID button for self-service removal.",
                        ),
                        Vec::new(),
                        true,
                    )
                    .await
                }
            }
        }
        other if other.starts_with("claim_approve:") || other.starts_with("claim_deny:") => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let (approve, id_str) = if let Some(rest) = other.strip_prefix("claim_approve:") {
                (true, rest)
            } else {
                (false, other["claim_deny:".len()..].as_ref())
            };
            let id: i64 = id_str.parse()?;
            let claim = db::player_limits::get_claim(&data.db, id).await?;
            let Some(claim) = claim else {
                return reply(
                    ctx,
                    interaction,
                    embeds::warn("Claim not found", "It may already be resolved."),
                    Vec::new(),
                    true,
                )
                .await;
            };
            // Guild scoping: never resolve a claim from another server.
            if claim.requesting_guild_id != guild_id.to_string() {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("this guild's claims"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            if approve {
                db::players::relink(
                    &data.db,
                    &claim.fid,
                    claim.requesting_user_id.parse()?,
                    guild_id,
                    None,
                )
                .await?;
                db::player_limits::resolve_claim(&data.db, id, "approved", user_id).await?;
                crate::admintoolkit::log_audit(
                    ctx,
                    data,
                    guild_id,
                    user_id,
                    Some("player_ids"),
                    "claim_approved",
                    Some(&claim.fid),
                )
                .await;
                reply(
                    ctx,
                    interaction,
                    embeds::ok(format!(
                        "`{}` is now linked to <@{}>.",
                        claim.fid, claim.requesting_user_id
                    )),
                    Vec::new(),
                    true,
                )
                .await
            } else {
                db::player_limits::resolve_claim(&data.db, id, "denied", user_id).await?;
                crate::admintoolkit::log_audit(
                    ctx,
                    data,
                    guild_id,
                    user_id,
                    Some("player_ids"),
                    "claim_denied",
                    Some(&claim.fid),
                )
                .await;
                reply(
                    ctx,
                    interaction,
                    embeds::ok(format!(
                        "Claim for `{}` denied; owner unchanged.",
                        claim.fid
                    )),
                    Vec::new(),
                    true,
                )
                .await
            }
        }
        other => Err(anyhow::anyhow!("unknown player action `{other}`")),
    }
}

// --------------------------------------------------------- admin toolkit

/// Handle an `atk:<tool>:<action>` interaction on a Toolkit post. Every
/// response is private; the shared post is never edited here.
async fn toolkit_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    use crate::db::admin_toolkit::Level;

    if action == "cancel" {
        interaction
            .create_response(
                &ctx.http,
                serenity::CreateInteractionResponse::UpdateMessage(
                    serenity::CreateInteractionResponseMessage::new().content("Cancelled."),
                ),
            )
            .await?;
        return Ok(());
    }

    let (confirmed, action) = match action.strip_prefix("cf:") {
        Some(rest) => (true, rest),
        None => (false, action),
    };
    let (tool_key, button_id) = action.split_once(':').unwrap_or((action, ""));
    let Some(guild_id) = interaction.guild_id.map(|id| id.get()) else {
        anyhow::bail!("Admin Toolkit only works inside a server");
    };
    let user_id = interaction.user.id.get();
    let panel = match crate::admintoolkit::registry::get_panel(tool_key) {
        Some(panel) => panel,
        None => {
            return reply(
                ctx,
                interaction,
                embeds::warn(
                    "Unknown Toolkit panel",
                    "Run Admin Toolkit repair in Settings → Admin.",
                ),
                Vec::new(),
                true,
            )
            .await;
        }
    };
    let config = crate::db::admin_toolkit::ToolkitConfig::for_guild(&data.db, guild_id)
        .await
        .ok()
        .flatten();
    if config.as_ref().is_none_or(|config| !config.enabled) {
        return reply(
            ctx,
            interaction,
            embeds::warn(
                "Admin Toolkit disabled",
                "An administrator can enable it in Settings → Admin.",
            ),
            Vec::new(),
            true,
        )
        .await;
    }
    let owner = db::admin::owner_id(&data.db)
        .await
        .ok()
        .flatten()
        .unwrap_or(0);
    let mut level = crate::admintoolkit::level_for(
        &data.db,
        guild_id,
        &crate::admintoolkit::member_role_ids(interaction),
        owner,
    )
    .await;
    // Bot owner / bot admin / guild owner / Administrator follow the
    // JavaScript level order (they rank at least as high as R5).
    let guild_owner = ctx
        .cache
        .guild(serenity::GuildId::new(guild_id))
        .is_some_and(|guild| guild.owner_id.get() == user_id);
    if level != Level::Owner
        && (guild_owner || crate::permissions::component_is_admin(ctx, data, interaction).await)
    {
        level = Level::Admin;
    }
    if !level.meets(Level::R4) {
        return reply(
            ctx,
            interaction,
            embeds::denied("R4 Toolkit role"),
            Vec::new(),
            true,
        )
        .await;
    }

    if button_id == "refresh" {
        interaction.defer(&ctx.http).await?;
        let ok = crate::admintoolkit::forum::refresh_post(ctx, data, guild_id, tool_key).await;
        interaction
            .edit_response(
                &ctx.http,
                serenity::EditInteractionResponse::new().content(if ok {
                    "✅ Panel refreshed."
                } else {
                    "❌ This panel could not be refreshed. Ask an admin to repair the Admin Toolkit."
                }),
            )
            .await?;
        return Ok(());
    }

    let button = match crate::admintoolkit::registry::action(panel, button_id) {
        Some(button) => button,
        None => {
            return reply(
                ctx,
                interaction,
                embeds::warn(
                    "Button unavailable",
                    "Ask an admin to repair this Toolkit post.",
                ),
                Vec::new(),
                true,
            )
            .await;
        }
    };
    if !level.meets(button.min_level) {
        return reply(
            ctx,
            interaction,
            embeds::denied("R5 Toolkit role"),
            Vec::new(),
            true,
        )
        .await;
    }

    if let Some(text) = button.confirm {
        if !confirmed {
            interaction
                .create_response(
                    &ctx.http,
                    serenity::CreateInteractionResponse::Message(
                        serenity::CreateInteractionResponseMessage::new()
                            .content(format!("⚠️ {text}"))
                            .components(vec![CreateActionRow::Buttons(vec![
                                components::danger(
                                    format!("atk:cf:{tool_key}:{button_id}"),
                                    "YES, RESET",
                                ),
                                components::secondary("atk:cancel", "Cancel"),
                            ])])
                            .ephemeral(true),
                    ),
                )
                .await?;
            return Ok(());
        }
        interaction
            .create_response(
                &ctx.http,
                serenity::CreateInteractionResponse::UpdateMessage(
                    serenity::CreateInteractionResponseMessage::new()
                        .content("⏳ Working…")
                        .components(Vec::new()),
                ),
            )
            .await?;
    }

    // Modal delegates must be opened before any deferral (Discord rule).
    if button.delegate.starts_with("atkmodal:") {
        interaction
            .create_response(
                &ctx.http,
                serenity::CreateInteractionResponse::Modal(
                    serenity::CreateModal::new("atkmodal:forum:create", "Create Forum").components(
                        vec![CreateActionRow::InputText(
                            components::short("name", "Forum name").max_length(90),
                        )],
                    ),
                ),
            )
            .await?;
        return Ok(());
    }
    if button.delegate == "atkforum:list" {
        let list = crate::admintoolkit::forum::forum_list(ctx, guild_id)
            .await
            .unwrap_or_else(|err| err.to_string());
        return reply(
            ctx,
            interaction,
            embeds::info("Forum List", list),
            Vec::new(),
            true,
        )
        .await;
    }

    // JS `adminToolkit/panels/tickets.js:update` is a custom action: it posts or
    // updates the panel, records a single concrete audit line, and edits the
    // deferred reply. Handle it here instead of delegating so the generic
    // "Opened" audit below cannot create a duplicate record, and so `ticket:post`
    // (the settings-hub variant, which JS does not audit) stays separate.
    if tool_key == "tickets" && button_id == "update" {
        interaction.defer(&ctx.http).await?;
        match crate::tickets::post_panel(ctx, data, guild_id).await {
            Ok((message_id, edited)) => {
                let channel = db::tickets::settings(&data.db, guild_id)
                    .await
                    .ok()
                    .and_then(|settings| settings.panel_channel())
                    .unwrap_or(0);
                let url = format!("https://discord.com/channels/{guild_id}/{channel}/{message_id}");
                let detail = if edited {
                    "Updated ticket panel"
                } else {
                    "Posted ticket panel"
                };
                crate::admintoolkit::log_audit(
                    ctx,
                    data,
                    guild_id,
                    user_id,
                    Some("tickets"),
                    "action",
                    Some(detail),
                )
                .await;
                interaction
                    .edit_response(
                        &ctx.http,
                        serenity::EditInteractionResponse::new().content(format!(
                            "✅ Ticket panel {}: {url}",
                            if edited { "updated" } else { "posted" }
                        )),
                    )
                    .await?;
            }
            Err(err) => {
                interaction
                    .edit_response(
                        &ctx.http,
                        serenity::EditInteractionResponse::new().content(format!(
                            "❌ **Unable to complete that action.**\n\n**Reason:** {}\nUse **Panel Channel** to select one.",
                            crate::error::public(&err)
                        )),
                    )
                    .await?;
            }
        }
        // JS `adminToolkit/index.js:78` also records the framework's standard
        // audit after the custom action. These are two distinct entries (the
        // custom effect above and the generic button-open line), not a repeat
        // of the same audit.
        crate::admintoolkit::log_audit(
            ctx,
            data,
            guild_id,
            user_id,
            Some("tickets"),
            "open",
            Some("Opened “Update Panel”"),
        )
        .await;
        return Ok(());
    }

    // Delegate to the real feature handler with a regular custom id. Existing
    // `update_panel`/`update_response` logic keeps the reply private on posts.
    crate::admintoolkit::delegate_action(ctx, data, interaction, button.delegate).await?;
    // The JavaScript Toolkit records the concrete effect for the confirmed
    // leveling reset instead of a generic "opened" line.
    let detail = if confirmed && tool_key == "leveling" && button_id == "reset" {
        "Reset ALL leveling XP".to_string()
    } else {
        format!("Opened “{}”", button.label)
    };
    crate::admintoolkit::log_audit(
        ctx,
        data,
        guild_id,
        user_id,
        Some(tool_key),
        if confirmed { "confirmed" } else { "open" },
        Some(&detail),
    )
    .await;
    Ok(())
}

// ------------------------------------------------------------- translate

/// Outcome of producing a private translation. Terminal errors deliberately
/// render without controls; successful views keep the original/translated
/// toggle so the user can switch without another API call.
enum PrivatePayload {
    Embed(CreateEmbed),
    Content(String),
    Error(String),
}

async fn build_private_translation(
    client: &reqwest::Client,
    record: Option<crate::db::translate::TranslatableMessage>,
    target: &str,
) -> PrivatePayload {
    let Some(record) = record else {
        return PrivatePayload::Error(
            "Could not find the original message data to translate.".into(),
        );
    };
    if let Some(json) = record.embed_json.as_deref() {
        match crate::translate::translate_embed_payload(client, json, target).await {
            Some(embed) => PrivatePayload::Embed(embed),
            None => PrivatePayload::Error("Could not decode the stored embed.".into()),
        }
    } else if let Some(content) = record.content.as_deref() {
        if content.trim().is_empty() {
            return PrivatePayload::Error("Nothing to translate for this message.".into());
        }
        let source = content.to_string();
        let translated =
            crate::translate::translate_batch(client, std::slice::from_ref(&source), target).await;
        let text = translated.first().cloned().unwrap_or(source);
        PrivatePayload::Content(crate::translate::translated_content(&text))
    } else {
        PrivatePayload::Error("Nothing to translate for this message.".into())
    }
}

async fn render_private_payload(
    ctx: &serenity::Context,
    interaction: &ComponentInteraction,
    payload: &PrivatePayload,
    message_id: u64,
    lang: &str,
    cache: bool,
    user_id: u64,
) -> anyhow::Result<()> {
    let mut response = EditInteractionResponse::new();
    let rows = match payload {
        PrivatePayload::Embed(embed) => {
            response = response.embed(embed.clone());
            vec![crate::translate::private_view_row(message_id, lang)]
        }
        PrivatePayload::Content(content) => {
            response = response.content(content.clone());
            vec![crate::translate::private_view_row(message_id, lang)]
        }
        PrivatePayload::Error(message) => {
            response = response.content(message.clone());
            Vec::new()
        }
    };
    if cache {
        let view = match payload {
            PrivatePayload::Embed(embed) => crate::translate::PrivateTranslation {
                embed: Some(embed.clone()),
                content: None,
            },
            PrivatePayload::Content(content) => crate::translate::PrivateTranslation {
                embed: None,
                content: Some(content.clone()),
            },
            PrivatePayload::Error(_) => crate::translate::PrivateTranslation::default(),
        };
        crate::translate::cache_translation(message_id, user_id, lang, view);
    }
    interaction
        .edit_response(&ctx.http, response.components(rows))
        .await?;
    Ok(())
}

async fn translate_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    namespace: &str,
    action: &str,
) -> anyhow::Result<()> {
    let message_id: u64 = action
        .parse()
        .map_err(|_| anyhow::anyhow!("malformed translate custom_id"))?;
    let user_id = interaction.user.id.get();
    let guild_id = interaction.guild_id.map(|id| id.get());

    match namespace {
        "translate" => {
            let current = crate::db::translate::get_user_lang(&data.db, guild_id, user_id).await;
            interaction
                .create_response(
                    &ctx.http,
                    CreateInteractionResponse::Message(
                        CreateInteractionResponseMessage::new()
                            .content("Choose your language below. Only you can see this translated copy.")
                            .components(vec![crate::translate::language_select_row_with_default(
                                message_id, &current,
                            )])
                            .ephemeral(true),
                    ),
                )
                .await?;
            Ok(())
        }
        "translate_lang" => {
            let target = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => values
                    .first()
                    .cloned()
                    .ok_or_else(|| anyhow::anyhow!("no language selected"))?,
                _ => return Err(anyhow::anyhow!("expected a language select menu")),
            };
            // Ack in place (deferUpdate) before the slow translation request;
            // the eventual edit replaces the picker on this private message.
            interaction.defer(&ctx.http).await?;
            if !crate::translate::is_supported_lang(&target) {
                return render_private_payload(
                    ctx,
                    interaction,
                    &PrivatePayload::Error(format!("Unsupported language: `{target}`.")),
                    message_id,
                    &target,
                    false,
                    user_id,
                )
                .await;
            }
            // Remember the choice: guild-specific, falling back to the DM
            // preference in other guilds, exactly like the JavaScript menus.
            let _ = crate::db::translate::set_user_lang(&data.db, guild_id, user_id, &target).await;
            let record = crate::db::translate::get(&data.db, message_id).await?;
            let payload =
                build_private_translation(crate::translate::translation_client(), record, &target)
                    .await;
            render_private_payload(
                ctx,
                interaction,
                &payload,
                message_id,
                &target,
                true,
                user_id,
            )
            .await
        }
        other => Err(anyhow::anyhow!("unknown translate action `{other}`")),
    }
}

/// `translate_view:original:{message_id}:{lang}` /
/// `translate_view:translated:{message_id}:{lang}` — Task 3's private toggle.
async fn translate_view_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let mut parts = action.splitn(3, ':');
    let view = parts.next().unwrap_or("");
    let id = parts
        .next()
        .ok_or_else(|| anyhow::anyhow!("malformed translate view id"))?;
    let lang = parts.next().unwrap_or("en");
    let message_id: u64 = id
        .parse()
        .map_err(|_| anyhow::anyhow!("malformed translate view id"))?;
    let user_id = interaction.user.id.get();

    interaction.defer(&ctx.http).await?;

    if !crate::translate::is_supported_lang(lang) {
        return render_private_payload(
            ctx,
            interaction,
            &PrivatePayload::Error("Unsupported language for this view.".into()),
            message_id,
            "en",
            false,
            user_id,
        )
        .await;
    }

    if view == "translated" {
        if let Some(cached) = crate::translate::cached_translation(message_id, user_id, lang) {
            let mut response = EditInteractionResponse::new()
                .components(vec![crate::translate::private_view_row(message_id, lang)]);
            if let Some(embed) = cached.embed {
                response = response.embed(embed);
            }
            if let Some(content) = cached.content {
                response = response.content(content);
            }
            interaction.edit_response(&ctx.http, response).await?;
            return Ok(());
        }
        // Cache miss (restart / eviction): retranslate once, then cache again.
        let record = crate::db::translate::get(&data.db, message_id).await?;
        let payload =
            build_private_translation(crate::translate::translation_client(), record, lang).await;
        return render_private_payload(ctx, interaction, &payload, message_id, lang, true, user_id)
            .await;
    }

    if view == "original" {
        let record = crate::db::translate::get(&data.db, message_id).await?;
        let payload = match record {
            None => PrivatePayload::Error(
                "Could not find the original message data to translate.".into(),
            ),
            Some(record) => {
                if let Some(json) = record.embed_json.as_deref() {
                    match crate::translate::original_embed_payload(json) {
                        Some(embed) => {
                            // Keep the original embed (including its image and
                            // original footer) readable in the private view.
                            let mut response = EditInteractionResponse::new()
                                .embed(embed)
                                .content("📄 Private original — only you can see this.");
                            response =
                                response.components(vec![crate::translate::private_view_row(
                                    message_id, lang,
                                )]);
                            interaction.edit_response(&ctx.http, response).await?;
                            return Ok(());
                        }
                        None => PrivatePayload::Error("Could not decode the stored embed.".into()),
                    }
                } else if let Some(content) = record.content.as_deref() {
                    if content.trim().is_empty() {
                        PrivatePayload::Error("Nothing to translate for this message.".into())
                    } else {
                        PrivatePayload::Content(crate::translate::original_content(content))
                    }
                } else {
                    PrivatePayload::Error("Nothing to translate for this message.".into())
                }
            }
        };
        return render_private_payload(
            ctx,
            interaction,
            &payload,
            message_id,
            lang,
            false,
            user_id,
        )
        .await;
    }

    render_private_payload(
        ctx,
        interaction,
        &PrivatePayload::Error("Unknown translation view.".into()),
        message_id,
        "en",
        false,
        user_id,
    )
    .await
}

// -------------------------------------------------------------------- gift

async fn gift_component(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    let guild_id = interaction
        .guild_id
        .map(|id| id.get())
        .ok_or_else(|| anyhow::anyhow!("gift codes only work inside a server"))?;
    match action {
        "handoff" => {
            if !is_effective_owner(data, interaction.user.id.get()).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Bot owner"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            interaction
                .create_response(
                    &ctx.http,
                    serenity::CreateInteractionResponse::Message(
                        serenity::CreateInteractionResponseMessage::new()
                            .content(
                                "⚠️ Confirm the legacy JS bot and its gift-code worker are stopped. This will hand off active, unannounced JS auto-sync codes to Rust and start redemption for registered players.",
                            )
                            .components(vec![serenity::CreateActionRow::Buttons(vec![
                                components::danger("gift:handoff_confirm", "Confirm JS is stopped"),
                                components::secondary("gift:handoff_cancel", "Cancel"),
                            ])])
                            .ephemeral(true),
                    ),
                )
                .await?;
            Ok(())
        }
        "handoff_confirm" => {
            if !is_effective_owner(data, interaction.user.id.get()).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Bot owner"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            interaction.defer_ephemeral(&ctx.http).await?;
            match crate::giftcode::handoff_js_pending(data, interaction.user.id.get()).await {
                Ok(0) => {
                    interaction
                        .edit_response(
                            &ctx.http,
                            serenity::EditInteractionResponse::new().content(
                                "No eligible active, unannounced JS auto-sync codes were found.",
                            ),
                        )
                        .await?;
                }
                Ok(count) => {
                    interaction
                        .edit_response(
                            &ctx.http,
                            serenity::EditInteractionResponse::new().content(format!(
                                "Handed off **{count}** code(s) to Rust. They are queued for background redemption and announcement; if another redemption batch is active, the next sync recovery pass will pick them up."
                            )),
                        )
                        .await?;
                }
                Err(err) => {
                    interaction
                        .edit_response(
                            &ctx.http,
                            serenity::EditInteractionResponse::new()
                                .content(format!("Handoff failed: {}", crate::error::public(&err))),
                        )
                        .await?;
                }
            }
            Ok(())
        }
        "handoff_cancel" => {
            interaction
                .create_response(
                    &ctx.http,
                    serenity::CreateInteractionResponse::Message(
                        serenity::CreateInteractionResponseMessage::new()
                            .content("Handoff cancelled.")
                            .ephemeral(true),
                    ),
                )
                .await?;
            Ok(())
        }
        "cancel" => {
            interaction
                .create_response(
                    &ctx.http,
                    serenity::CreateInteractionResponse::UpdateMessage(
                        serenity::CreateInteractionResponseMessage::new().content("Cancelled."),
                    ),
                )
                .await?;
            Ok(())
        }
        "cfremove" => {
            interaction
                .create_response(
                    &ctx.http,
                    serenity::CreateInteractionResponse::Message(
                        serenity::CreateInteractionResponseMessage::new()
                            .content("⚠️ Remove this code from the list? Past redemption history is kept.")
                            .components(vec![CreateActionRow::Buttons(vec![
                                components::danger("gift:delete", "Remove"),
                                components::secondary("gift:cancel", "Cancel"),
                            ])])
                            .ephemeral(true),
                    ),
                )
                .await?;
            Ok(())
        }
        "add" => {
            let inputs = vec![
                CreateActionRow::InputText(components::short("code", "Gift code")),
                CreateActionRow::InputText(
                    components::short("vip", "VIP? (yes/no)").required(false),
                ),
            ];
            interaction
                .create_response(&ctx.http, modal("gift:add_modal", "Add gift code", inputs))
                .await?;
            Ok(())
        }
        "use" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "code",
                "Gift code to redeem",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("gift:use_modal", "Redeem a gift code", inputs),
                )
                .await?;
            Ok(())
        }
        "delete" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "code",
                "Code to remove",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("gift:delete_modal", "Remove gift code", inputs),
                )
                .await?;
            Ok(())
        }
        "validate" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let inputs = vec![CreateActionRow::InputText(components::short(
                "code",
                "Gift code to validate",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("gift:validate_modal", "Validate gift code", inputs),
                )
                .await?;
            Ok(())
        }
        "probe" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let fid = db::settings::get(&data.db, guild_id, db::settings::keys::GIFT_PROBE_FID)
                .await
                .ok()
                .flatten()
                .unwrap_or_default();
            let state = db::settings::get(&data.db, guild_id, db::settings::keys::GIFT_PROBE_STATE)
                .await
                .ok()
                .flatten()
                .unwrap_or_default();
            let inputs = vec![
                CreateActionRow::InputText(
                    components::short("fid", "Probe player FID (blank clears override)")
                        .required(false)
                        .value(fid),
                ),
                CreateActionRow::InputText(
                    components::short("state", "Player state ID")
                        .required(false)
                        .value(state),
                ),
            ];
            interaction
                .create_response(
                    &ctx.http,
                    modal("gift:probe_modal", "Gift-code validation probe", inputs),
                )
                .await?;
            Ok(())
        }
        "template" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let current = db::settings::get(
                &data.db,
                guild_id,
                db::settings::keys::GIFT_ANNOUNCE_TEMPLATE,
            )
            .await
            .ok()
            .flatten()
            .unwrap_or_default();
            let input =
                components::paragraph("template", "Announcement text; tokens: {codes}, {count}")
                    .required(false)
                    .value(current)
                    .max_length(3500);
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "gift:template_modal",
                        "Gift-code announcement template",
                        vec![CreateActionRow::InputText(input)],
                    ),
                )
                .await?;
            Ok(())
        }
        "template_preview" => {
            let template = db::settings::get(
                &data.db,
                guild_id,
                db::settings::keys::GIFT_ANNOUNCE_TEMPLATE,
            )
            .await
            .ok()
            .flatten();
            let sample = vec!["SAMPLE2026".to_string(), "WOSGIFT".to_string()];
            let embed = crate::giftcode::announcement_embed(&sample, template.as_deref());
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        "template_reset" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            db::settings::set(
                &data.db,
                guild_id,
                db::settings::keys::GIFT_ANNOUNCE_TEMPLATE,
                None,
            )
            .await?;
            reply(
                ctx,
                interaction,
                embeds::ok("Gift-code announcement template reset to the default."),
                Vec::new(),
                true,
            )
            .await
        }
        "retry" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let inputs = vec![CreateActionRow::InputText(components::short(
                "code",
                "Code whose failures should be retried",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("gift:retry_modal", "Retry failed redemptions", inputs),
                )
                .await?;
            Ok(())
        }
        "history" => {
            let inputs = vec![CreateActionRow::InputText(components::short(
                "code",
                "Code to show history for",
            ))];
            interaction
                .create_response(
                    &ctx.http,
                    modal("gift:history_modal", "Redemption history", inputs),
                )
                .await?;
            Ok(())
        }
        "channel" => {
            let (embed, rows) =
                settings_section(ctx, data, guild_id, "gift", interaction.user.id.get()).await?;
            update_panel(ctx, data, interaction, embed, rows).await
        }
        "list" => {
            let rows = db::giftcodes::list_recent(&data.db, 15).await?;
            let body = if rows.is_empty() {
                "_No codes stored yet._".to_string()
            } else {
                rows.iter()
                    .map(|row| {
                        format!(
                            "`{}` {} · **{}** · {}",
                            row.code,
                            if row.is_vip() {
                                icons::CROWN
                            } else {
                                icons::GIFT
                            },
                            row.status,
                            embeds::db_relative(row.added_at)
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
            };
            let embed = embeds::brand(format!("{} Gift codes", icons::GIFT))
                .color(colors::GOLD)
                .description(format!("{}\n{}", theme::DIVIDER, body))
                .footer(serenity::CreateEmbedFooter::new(theme::footer()));
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        "sync" => {
            if !permissions::component_is_admin(ctx, data, interaction).await {
                return reply(
                    ctx,
                    interaction,
                    embeds::denied("Manage Server"),
                    Vec::new(),
                    true,
                )
                .await;
            }
            let embed = match crate::giftcode::sync(data).await {
                Ok(outcome) => embeds::success(
                    "Gift-code sync complete",
                    format!(
                        "**{}** active · **{}** new · **{}** channel(s).",
                        outcome.total,
                        outcome.fresh.len(),
                        outcome.announcements
                    ),
                ),
                Err(err) => {
                    embeds::error("Sync failed", format!("`{}`", crate::error::public(&err)))
                }
            };
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        "announce" => {
            let embed = match crate::giftcode::announce_pending(data, 15).await {
                Ok(0) => embeds::info(
                    "Nothing to announce",
                    "Every stored code is already announced.",
                ),
                Ok(count) => embeds::ok(format!("Announced **{count}** channel(s).")),
                Err(err) => embeds::error(
                    "Announcement failed",
                    format!("`{}`", crate::error::public(&err)),
                ),
            };
            reply(ctx, interaction, embed, Vec::new(), true).await
        }
        other => Err(anyhow::anyhow!("unknown gift action `{other}`")),
    }
}

