// -------------------------------------------------------- birthday modals

async fn birthday_public_component(
    ctx: &serenity::Context,
    interaction: &ComponentInteraction,
    action: &str,
) -> anyhow::Result<()> {
    match action {
        "set" => {
            interaction
                .create_response(
                    &ctx.http,
                    modal(
                        "bdaypanelmodal:set",
                        "Add Your Birthday",
                        vec![
                            CreateActionRow::InputText(
                                components::short("day", "Day (1–31)").max_length(2),
                            ),
                            CreateActionRow::InputText(
                                components::short("month", "Month (1–12 or name)").max_length(20),
                            ),
                        ],
                    ),
                )
                .await?;
            Ok(())
        }
        "translate" => {
            let options = crate::translate::LANGUAGES
                .iter()
                .map(|(label, emoji, code)| {
                    serenity::CreateSelectMenuOption::new(*label, *code)
                        .emoji(serenity::ReactionType::Unicode((*emoji).to_string()))
                })
                .collect();
            let menu = serenity::CreateSelectMenu::new(
                "bdaypanel:lang",
                serenity::CreateSelectMenuKind::String { options },
            )
            .placeholder("Choose a language")
            .min_values(1)
            .max_values(1);
            reply(
                ctx,
                interaction,
                embeds::brand("🌐 Translate Birthday Signup"),
                vec![CreateActionRow::SelectMenu(menu)],
                true,
            )
            .await
        }
        "lang" => {
            let lang = match &interaction.data.kind {
                serenity::ComponentInteractionDataKind::StringSelect { values } => {
                    values.first().cloned()
                }
                _ => None,
            }
            .ok_or_else(|| anyhow::anyhow!("choose a language"))?;
            if !crate::translate::is_supported_lang(&lang) {
                return Err(anyhow::anyhow!("unsupported language"));
            }
            let lines = vec![
                "🎂 Birthday Signup".to_string(),
                "Optional and free — share your day and month so we can celebrate you on the server.".to_string(),
                "We only store day and month, never your birth year.".to_string(),
                "Add / update my birthday".to_string(),
                "Translate".to_string(),
            ];
            let translated = crate::translate::translate_batch(
                crate::translate::translation_client(),
                &lines,
                &lang,
            )
            .await;
            let embed = embeds::brand(&translated[0])
                .description(format!("{}\n\n🔒 {}", translated[1], translated[2]));
            reply(
                ctx,
                interaction,
                embed,
                vec![CreateActionRow::Buttons(vec![components::primary(
                    "bdaypanel:set",
                    format!("🎂 {}", translated[3]),
                )])],
                true,
            )
            .await
        }
        _ => Err(anyhow::anyhow!("unknown birthday panel action")),
    }
}

