// ----------------------------------------------------- giveaways modals

async fn giveaways_create_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
    required_role_id: Option<u64>,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild = guild_of(interaction)?;
    let prize =
        trimmed(interaction, "prize").ok_or_else(|| anyhow::anyhow!("prize is required"))?;
    if prize.trim().is_empty() {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Prize required", "Enter a prize description."),
        )
        .await;
    }
    let duration = trimmed(interaction, "minutes").unwrap_or_default();
    let Some(minutes) = parse_giveaway_duration_minutes(&duration) else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn(
                "Invalid duration",
                "Use a duration from 1 minute to 60 days, such as `30m`, `2h`, or `1d 12h`.",
            ),
        )
        .await;
    };
    let winners = trimmed(interaction, "winners")
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|count| (1..=20).contains(count));
    let Some(winners) = winners else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Invalid winners", "Choose a whole number from 1 to 20."),
        )
        .await;
    };
    let description = trimmed(interaction, "description").filter(|value| !value.trim().is_empty());
    let configured = db::settings::get_u64(&data.db, guild, db::settings::keys::GIVEAWAY_CHANNEL)
        .await
        .unwrap_or(None);
    let from_toolkit = db::admin_toolkit::find_post(&data.db, interaction.channel_id.get())
        .await
        .ok()
        .flatten()
        .is_some_and(|(post_guild, key)| post_guild == guild && key == "giveaways");
    let channel = configured.or_else(|| (!from_toolkit).then_some(interaction.channel_id.get()));
    defer_modal(ctx, interaction).await?;
    let draft = GiveawayDraft {
        guild_id: guild,
        prize: prize.trim().to_string(),
        duration_minutes: minutes,
        winner_count: winners,
        description,
        required_role_id,
        channel_id: channel,
        rules: db::giveaways::GiveawayRules::default(),
        created: Instant::now(),
    };
    set_giveaway_draft(interaction.user.id.get(), draft.clone());
    let (embed, rows) = giveaway_draft_payload(&draft);
    interaction
        .edit_response(
            &ctx.http,
            EditInteractionResponse::new().embed(embed).components(rows),
        )
        .await?;
    Ok(())
}

fn parse_giveaway_duration_minutes(raw: &str) -> Option<i64> {
    let bytes = raw.trim().as_bytes();
    let mut index = 0;
    let mut total = 0_i64;
    let mut found = false;
    while index < bytes.len() {
        while index < bytes.len() && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        if index == bytes.len() {
            break;
        }
        let start = index;
        while index < bytes.len() && bytes[index].is_ascii_digit() {
            index += 1;
        }
        if start == index {
            return None;
        }
        let amount = std::str::from_utf8(&bytes[start..index])
            .ok()?
            .parse::<i64>()
            .ok()?;
        while index < bytes.len() && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        let unit = *bytes.get(index)?;
        index += 1;
        let multiplier = match unit.to_ascii_lowercase() {
            b'm' => 1,
            b'h' => 60,
            b'd' => 1440,
            b'w' => 10080,
            _ => return None,
        };
        total = total.checked_add(amount.checked_mul(multiplier)?)?;
        found = true;
    }
    (found && (1..=86_400).contains(&total)).then_some(total)
}

async fn giveaways_channel_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild = guild_of(interaction)?;
    let channel = channel_from_interaction(interaction, "channel")?;
    let channel = if let Some(id) = channel {
        match ctx.http.get_channel(serenity::ChannelId::new(id)).await? {
            serenity::Channel::Guild(channel)
                if channel.guild_id.get() == guild
                    && matches!(
                        channel.kind,
                        serenity::ChannelType::Text | serenity::ChannelType::News
                    ) =>
            {
                Some(id)
            }
            _ => {
                return finish_modal(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Invalid giveaway channel",
                        "Choose a text or announcement channel in this server.",
                    ),
                )
                .await;
            }
        }
    } else {
        None
    };
    defer_modal(ctx, interaction).await?;
    let channel_value = channel.map(|id| id.to_string());
    db::settings::set(
        &data.db,
        guild,
        db::settings::keys::GIVEAWAY_CHANNEL,
        channel_value.as_deref(),
    )
    .await?;
    let _ = crate::admintoolkit::forum::refresh_post(ctx, data, guild, "giveaways").await;
    let embed = match channel {
        Some(id) => embeds::ok(format!("New giveaways will be posted in <#{id}>.")),
        None => embeds::ok("Giveaway channel cleared. New giveaways outside the Toolkit will use the channel where they are created."),
    };
    finish_modal(ctx, interaction, embed).await
}

async fn giveaways_cleanup_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild_id = guild_of(interaction)?;
    let minutes = trimmed(interaction, "minutes")
        .and_then(|value| value.parse::<i64>().ok())
        .filter(|minutes| (1..=43_200).contains(minutes));
    let Some(minutes) = minutes else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn(
                "Invalid delay",
                "Enter a whole number of minutes from 1 to 43,200 (30 days).",
            ),
        )
        .await;
    };
    db::welcome::set_giveaway_cleanup_settings(&data.db, guild_id, true, minutes).await?;
    finish_modal(
        ctx,
        interaction,
        embeds::ok(format!("Giveaway cleanup is on. Finished giveaway messages will be removed after {minutes} minutes.")),
    )
    .await
}

