async fn messages_send_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild = guild_of(interaction)?;
    let group =
        trimmed(interaction, "group").ok_or_else(|| anyhow::anyhow!("group is required"))?;
    let name = trimmed(interaction, "name").ok_or_else(|| anyhow::anyhow!("name is required"))?;
    let channel = match trimmed(interaction, "channel") {
        Some(value) => Some(
            value
                .parse::<u64>()
                .map_err(|_| anyhow::anyhow!("channel must be a numeric Discord channel ID"))?,
        ),
        None => None,
    };
    let group_id = group_id_or_name(data, guild, interaction.user.id.get(), &group).await?;
    let record = db::messages::get_message(&data.db, group_id, name.trim()).await?;
    let Some((message, embed)) = record else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn(
                "Unknown message",
                format!("No message named `{}` in group {group_id}.", name.trim()),
            ),
        )
        .await;
    };

    defer_modal(ctx, interaction).await?;

    let target = channel.unwrap_or_else(|| interaction.channel_id.get());
    let content = message.plain_text.as_deref().unwrap_or_default();
    let mention = message.mention_type.as_deref().unwrap_or("none");
    let mention_text = match mention {
        "here" => "@here\n".to_string(),
        "everyone" => "@everyone\n".to_string(),
        _ => String::new(),
    };

    let allowed_mentions =
        serenity::CreateAllowedMentions::new().everyone(matches!(mention, "here" | "everyone"));
    let sent = if message.is_embed() {
        let mut builder = serenity::CreateMessage::new()
            .allowed_mentions(allowed_mentions)
            .embeds(message_embed_payload(&embed));
        if !mention_text.is_empty() {
            builder = builder.content(mention_text.clone());
        }
        let sent = serenity::ChannelId::new(target)
            .send_message(&ctx.http, builder)
            .await?;
        db::messages::track_embed_message(
            &data.db,
            guild,
            target,
            sent.id.get(),
            Some(message.id),
            interaction.user.id.get(),
            &embed,
        )
        .await?;
        sent
    } else {
        let tracked_content = format!("{mention_text}{content}");
        let sent = serenity::ChannelId::new(target)
            .send_message(
                &ctx.http,
                serenity::CreateMessage::new()
                    .content(tracked_content.clone())
                    .allowed_mentions(allowed_mentions),
            )
            .await?;
        db::messages::track_message(
            &data.db,
            guild,
            target,
            sent.id.get(),
            Some(message.id),
            interaction.user.id.get(),
            &tracked_content,
        )
        .await?;
        sent
    };

    // Attach the owner's contact button when branding is enabled (matches the
    // legacy "Message Necromancer" link under Messages-feature posts).
    if let Ok(branding) = db::branding::branding(&data.db).await {
        if branding.is_enabled() {
            if let Some(url) = branding.contact_url.as_deref().filter(|u| !u.is_empty()) {
                let row = serenity::CreateActionRow::Buttons(vec![crate::ui::components::link(
                    branding.label(),
                    url,
                )]);
                let _ = serenity::ChannelId::new(target)
                    .edit_message(
                        &ctx.http,
                        sent.id,
                        serenity::EditMessage::new().components(vec![row]),
                    )
                    .await;
            }
        }
    }

    finish_modal(
        ctx,
        interaction,
        embeds::ok(format!("`{}` posted.", message.name)),
    )
    .await
}

async fn messages_tracked_edit_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
    tracked_id: i64,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild_id = guild_of(interaction)?;
    let Some(text) = trimmed(interaction, "text") else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Message required", "Message text cannot be empty."),
        )
        .await;
    };
    let Some(tracked) = db::messages::get_tracked_message(&data.db, guild_id, tracked_id).await?
    else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not found", "This message is no longer tracked."),
        )
        .await;
    };
    if tracked.is_embed != 0 {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn(
                "Unsupported message",
                "Embed editing is not available for this message yet.",
            ),
        )
        .await;
    }
    let channel_id = tracked.channel_id.parse::<u64>()?;
    let message_id = tracked.message_id.parse::<u64>()?;
    defer_modal(ctx, interaction).await?;
    if let Err(err) = serenity::ChannelId::new(channel_id)
        .edit_message(
            &ctx.http,
            serenity::MessageId::new(message_id),
            serenity::EditMessage::new()
                .content(&text)
                .allowed_mentions(serenity::CreateAllowedMentions::new()),
        )
        .await
    {
        return finish_modal(
            ctx,
            interaction,
            embeds::error("Edit failed", crate::error::public(&err)),
        )
        .await;
    }
    db::messages::update_tracked_plain_text(&data.db, guild_id, tracked_id, &text).await?;
    finish_modal(
        ctx,
        interaction,
        embeds::ok("The sent message was updated."),
    )
    .await
}

async fn messages_library_plain_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
    group_id: i64,
    message_id: i64,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild_id = guild_of(interaction)?;
    let groups = db::messages::visible_groups(
        &data.db,
        guild_id,
        interaction.user.id.get(),
        data.cfg.owner_id == Some(interaction.user.id.get()),
    )
    .await?;
    if !groups.iter().any(|group| group.id == group_id) {
        return finish_modal(ctx, interaction, embeds::denied("Group access")).await;
    }
    let Some(text) = trimmed(interaction, "text") else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Message required", "Template text cannot be empty."),
        )
        .await;
    };
    defer_modal(ctx, interaction).await?;
    if !db::messages::update_library_plain_text(&data.db, group_id, message_id, &text).await? {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not found", "That plain-text template is gone."),
        )
        .await;
    }
    finish_modal(ctx, interaction, embeds::ok("Message template updated.")).await
}

async fn messages_library_embed_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
    group_id: i64,
    message_id: i64,
    field: &str,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild_id = guild_of(interaction)?;
    let groups = db::messages::visible_groups(
        &data.db,
        guild_id,
        interaction.user.id.get(),
        data.cfg.owner_id == Some(interaction.user.id.get()),
    )
    .await?;
    if !groups.iter().any(|group| group.id == group_id) {
        return finish_modal(ctx, interaction, embeds::denied("Group access")).await;
    }
    let Some((record, _)) =
        db::messages::get_library_message(&data.db, group_id, message_id).await?
    else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not found", "That template is gone."),
        )
        .await;
    };
    if !record.is_embed() {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not an embed", "This template is plain text."),
        )
        .await;
    }
    let raw = trimmed(interaction, "value").unwrap_or_default();
    let value = match field {
        "color" if !raw.is_empty() => {
            let hex = raw.trim_start_matches('#');
            if hex.len() != 6 || !hex.chars().all(|ch| ch.is_ascii_hexdigit()) {
                return finish_modal(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Invalid color",
                        "Enter a six-digit hex color such as 3498db.",
                    ),
                )
                .await;
            }
            Some(hex.to_string())
        }
        "image_url" | "thumbnail_url" if !raw.is_empty() => {
            if !(raw.starts_with("http://") || raw.starts_with("https://")) {
                return finish_modal(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Invalid image URL",
                        "Image URLs must start with http:// or https://.",
                    ),
                )
                .await;
            }
            Some(raw)
        }
        "images" => {
            let images = raw
                .split(['\n', ','])
                .map(str::trim)
                .filter(|url| url.starts_with("http://") || url.starts_with("https://"))
                .take(8)
                .map(str::to_string)
                .collect::<Vec<_>>();
            (!images.is_empty()).then(|| serde_json::to_string(&images).unwrap_or_default())
        }
        "title" | "description" | "footer" | "author" | "image_url" | "thumbnail_url" => {
            (!raw.is_empty()).then_some(raw)
        }
        _ => {
            return finish_modal(
                ctx,
                interaction,
                embeds::warn("Unsupported field", "This embed field cannot be edited."),
            )
            .await
        }
    };
    defer_modal(ctx, interaction).await?;
    if !db::messages::update_library_embed_field(
        &data.db,
        group_id,
        message_id,
        field,
        value.as_deref(),
    )
    .await?
    {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not found", "That embed template is gone."),
        )
        .await;
    }
    finish_modal(ctx, interaction, embeds::ok("Embed template updated.")).await
}

fn tracked_embed_field_value(
    tracked: &db::messages::TrackedMessage,
    field: &str,
) -> anyhow::Result<String> {
    match field {
        "title" => Ok(tracked.embed_title.clone().unwrap_or_default()),
        "description" => Ok(tracked.embed_description.clone().unwrap_or_default()),
        "color" => Ok(tracked
            .embed_color
            .map(|value| format!("{:06x}", value as u32))
            .unwrap_or_default()),
        "image_url" => Ok(tracked.embed_image_url.clone().unwrap_or_default()),
        "thumbnail_url" => Ok(tracked.embed_thumbnail_url.clone().unwrap_or_default()),
        "footer" => Ok(tracked.embed_footer.clone().unwrap_or_default()),
        "author" => Ok(tracked.embed_author.clone().unwrap_or_default()),
        "images" => Ok(tracked
            .embed_images
            .as_deref()
            .and_then(|raw| serde_json::from_str::<Vec<String>>(raw).ok())
            .unwrap_or_default()
            .join("\n")),
        _ => anyhow::bail!("unsupported embed field"),
    }
}

async fn messages_tracked_embed_modal(
    ctx: &serenity::Context,
    data: &Data,
    interaction: &ModalInteraction,
    tracked_id: i64,
    field: &str,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let guild_id = guild_of(interaction)?;
    let Some(tracked) = db::messages::get_tracked_message(&data.db, guild_id, tracked_id).await?
    else {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not found", "This message is no longer tracked."),
        )
        .await;
    };
    if tracked.is_embed == 0 {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not an embed", "This message is plain text."),
        )
        .await;
    }
    let raw = trimmed(interaction, "value").unwrap_or_default();
    let value = match field {
        "color" if !raw.is_empty() => {
            let hex = raw.trim_start_matches('#');
            if hex.len() != 6 || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
                return finish_modal(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Invalid color",
                        "Enter a six-digit hex color such as 3498db.",
                    ),
                )
                .await;
            }
            Some(hex.to_string())
        }
        "image_url" | "thumbnail_url" if !raw.is_empty() => {
            if !(raw.starts_with("http://") || raw.starts_with("https://")) {
                return finish_modal(
                    ctx,
                    interaction,
                    embeds::warn(
                        "Invalid image URL",
                        "Image URLs must start with http:// or https://.",
                    ),
                )
                .await;
            }
            Some(raw)
        }
        "images" => {
            let images = raw
                .split(['\n', ','])
                .map(str::trim)
                .filter(|url| url.starts_with("http://") || url.starts_with("https://"))
                .take(8)
                .map(str::to_string)
                .collect::<Vec<_>>();
            (!images.is_empty()).then(|| serde_json::to_string(&images).unwrap_or_default())
        }
        "title" | "description" | "footer" | "author" | "image_url" | "thumbnail_url" => {
            (!raw.is_empty()).then_some(raw)
        }
        _ => {
            return finish_modal(
                ctx,
                interaction,
                embeds::warn("Unsupported field", "This embed field cannot be edited."),
            )
            .await
        }
    };
    defer_modal(ctx, interaction).await?;
    if !db::messages::update_tracked_embed_field(
        &data.db,
        guild_id,
        tracked_id,
        field,
        value.as_deref(),
    )
    .await?
    {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn("Not found", "This tracked embed is no longer available."),
        )
        .await;
    }
    let updated = db::messages::get_tracked_message(&data.db, guild_id, tracked_id)
        .await?
        .ok_or_else(|| anyhow::anyhow!("tracked embed disappeared"))?;
    let embed = db::messages::MessageEmbed {
        library_id: updated.library_id.unwrap_or_default(),
        title: updated.embed_title,
        description: updated.embed_description,
        color: updated.embed_color,
        image_url: updated.embed_image_url,
        thumbnail_url: updated.embed_thumbnail_url,
        footer: updated.embed_footer,
        author: updated.embed_author,
        images: updated.embed_images,
    };
    let channel_id = updated.channel_id.parse::<u64>()?;
    let message_id = updated.message_id.parse::<u64>()?;
    if let Err(err) = serenity::ChannelId::new(channel_id)
        .edit_message(
            &ctx.http,
            serenity::MessageId::new(message_id),
            serenity::EditMessage::new().embeds(message_embed_payload(&embed)),
        )
        .await
    {
        return finish_modal(
            ctx,
            interaction,
            embeds::warn(
                "Saved locally",
                format!(
                    "Could not update the Discord post: {}",
                    crate::error::public(&err)
                ),
            ),
        )
        .await;
    }
    finish_modal(ctx, interaction, embeds::ok("The sent embed was updated.")).await
}

// -------------------------------------------------------- cleanup modals

async fn cleanup_clear_modal(
    ctx: &serenity::Context,
    _data: &Data,
    interaction: &ModalInteraction,
) -> anyhow::Result<()> {
    if !permissions::modal_is_admin(ctx, _data, interaction).await {
        return finish_modal(ctx, interaction, embeds::denied("Manage Server")).await;
    }
    let amount = trimmed(interaction, "amount")
        .and_then(|v| v.parse::<u64>().ok())
        .ok_or_else(|| anyhow::anyhow!("amount must be a number between 1 and 100"))?
        .clamp(1, 100);
    defer_modal(ctx, interaction).await?;

    let channel_id = interaction.channel_id.get();
    let channel_id = serenity::ChannelId::new(channel_id);
    let mut deleted = 0u64;
    let mut skipped_old = 0u64;
    let mut last_id: Option<serenity::MessageId> = None;
    // Discord refuses bulk-deleting messages older than 14 days (1h safety margin).
    let cutoff = chrono::Utc::now().timestamp() - 14 * 24 * 3600 + 3600;
    while deleted < amount {
        let builder = serenity::GetMessages::new().limit(100u8);
        let builder = if let Some(id) = last_id {
            builder.before(id)
        } else {
            builder
        };
        let messages = channel_id.messages(&ctx.http, builder).await?;
        if messages.is_empty() {
            break;
        }
        last_id = messages.last().map(|m| m.id);
        let remaining = (amount - deleted) as usize;
        let mut batch: Vec<serenity::MessageId> = Vec::new();
        for m in messages.iter().take(remaining) {
            if m.id.created_at().unix_timestamp() >= cutoff {
                batch.push(m.id);
            } else {
                skipped_old += 1;
            }
        }
        match batch.len() {
            0 => {}
            1 => channel_id.delete_message(&ctx.http, batch[0]).await?,
            _ => channel_id.delete_messages(&ctx.http, batch.clone()).await?,
        }
        deleted += batch.len() as u64;
        // Messages arrive newest-first: once one is too old, the rest are too.
        if skipped_old > 0 {
            break;
        }
    }

    finish_modal(
        ctx,
        interaction,
        embeds::ok(format!(
            "Deleted {deleted} messages.{}",
            if skipped_old > 0 {
                " Messages older than 14 days can't be bulk-deleted and were skipped."
            } else {
                ""
            }
        )),
    )
    .await
}

